NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: 'In principio creavit Deus caelum, et terram.',
        2: 'Terra autem erat inanis et vacua, et tenebrae erant super faciem abyssi: et Spiritus Domini ferebatur super aquas.',
        3: 'Dixitque Deus: Fiat lux. Et facta est lux.',
        4: 'Et vidit Deus lucem quod esset bona: et divisit lucem a tenebris.',
        5: 'Appellavitque lucem Diem, et tenebras Noctem: factumque est vespere et mane, dies unus.',
        6: 'Dixit quoque Deus: Fiat firmamentum in medio aquarum: et dividat aquas ab aquis.',
        7: 'Et fecit Deus firmamentum, divisitque aquas, quae erant sub firmamento, ab his, quae erant super firmamentum. Et factum est ita.',
        8: 'Vocavitque Deus firmamentum, Caelum: et factum est vespere et mane, dies secundus.',
        9: 'Dixit vero Deus: Congregentur aquae, quae sub caelo sunt, in locum unum: et appareat arida. Et factum est ita.',
        10: 'Et vocavit Deus aridam, Terram, congregationesque aquarum appellavit Maria. Et vidit Deus quod esset bonum.',
        11: 'Et ait: Germinet terra herbam virentem, et facientem semen, et lignum pomiferum faciens fructum iuxta genus suum, cuius semen in semetipso sit super terram. Et factum est ita.',
        12: 'Et protulit terra herbam virentem, et facientem semen iuxta genus suum, lignumque faciens fructum, et habens unumquodque sementem secundum speciem suam. Et vidit Deus quod esset bonum.',
        13: 'Et factum est vespere et mane, dies tertius.',
        14: 'Dixit autem Deus: Fiant luminaria in firmamento caeli, et dividant diem ac noctem, et sint in signa et tempora, et dies et annos:',
        15: 'ut luceant in firmamento caeli, et illuminent terram. Et factum est ita.',
        16: 'Fecitque Deus duo luminaria magna: luminare maius, ut praeesset diei: et luminare minus, ut praeesset nocti: et stellas.',
        17: 'Et posuit eas in firmamento caeli, ut lucerent super terram,',
        18: 'et praeessent diei ac nocti, et dividerent lucem ac tenebras. Et vidit Deus quod esset bonum.',
        19: 'Et factum est vespere et mane, dies quartus.',
        20: 'Dixit etiam Deus: Producant aquae reptile animae viventis, et volatile super terram sub firmamento caeli.',
        21: 'Creavitque Deus Cete grandia, et omnem animam viventem atque motabilem, quam produxerant aquae in species suas, et omne volatile secundum genus suum. Et vidit Deus quod esset bonum.',
        22: 'Benedixitque eis, dicens: Crescite, et multiplicamini, et replete aquas maris: avesque multiplicentur super terram.',
        23: 'Et factum est vespere et mane, dies quintus.',
        24: 'Dixit quoque Deus: Producat terra animam viventem in genere suo, iumenta, et reptilia, et bestias terrae secundum species suas. Factumque est ita.',
        25: 'Et fecit Deus bestias terrae iuxta species suas, et iumenta, et omne reptile terrae in genere suo. Et vidit Deus quod esset bonum,',
        26: 'et ait: Faciamus Hominem ad imaginem, et similitudinem nostram: et praesit piscibus maris, et volatilibus caeli, et bestiis, universaeque terrae, omnique reptili, quod movetur in terra.',
        27: 'Et creavit Deus hominem ad imaginem et similitudinem suam: ad imaginem Dei creavit illum, masculum et feminam creavit eos.',
        28: 'Benedixitque illis Deus, et ait: Crescite et multiplicamini, et replete terram, et subiicite eam, et dominamini piscibus maris, et volatilibus caeli, et universis animantibus, quae moventur super terram.',
        29: 'Dixitque Deus: Ecce dedi vobis omnem herbam afferentem semen super terram, et universa ligna quae habent in semetipsis sementem generis sui, ut sint vobis in escam:',
        30: 'et cunctis animantibus terrae, omnique volucri caeli, et universis quae moventur in terra, et in quibus est anima vivens, ut habeant ad vescendum. Et factum est ita.',
        31: 'Viditque Deus cuncta quae fecerat: et erant valde bona. Et factum est vespere et mane, dies sextus.',
    },
    2: {
        1: 'Igitur perfecti sunt caeli et terra, et omnis ornatus eorum.',
        2: 'Complevitque Deus die septimo opus suum quod fecerat: et requievit die septimo ab universo opere quod patrarat.',
        3: 'Et benedixit diei septimo; et sanctificavit illum: quia in ipso cessaverat ab omni opere suo quod creavit Deus ut faceret.',
        4: 'Istae sunt generationes caeli et terrae, quando creata sunt, in die quo fecit Dominus Deus caelum et terram:',
        5: 'Et omne virgultum agri antequam oriretur in terra, omnemque herbam regionis priusquam germinaret: non enim pluerat Dominus Deus super terram, et homo non erat qui operaretur terram:',
        6: 'Sed fons ascendebat e terra, irrigans universam superficiem terrae.',
        7: 'Formavit igitur Dominus Deus hominem de limo terrae, et inspiravit in faciem eius spiraculum vitae, et factus est homo in animam viventem.',
        8: 'Plantaverat autem Dominus Deus Paradisum voluptatis a principio: in quo posuit hominem quem formaverat.',
        9: 'Produxitque Dominus Deus de humo omne lignum pulchrum visu, et ad vescendum suave: lignum etiam vitae in medio paradisi, lignumque scientiae boni et mali.',
        10: 'Et fluvius egrediebatur de loco voluptatis ad irrigandum paradisum, qui inde dividitur in quattuor capita.',
        11: 'Nomen uni Phison: ipse est qui circuit omnem terram Hevilath, ubi nascitur aurum:',
        12: 'et aurum terrae illius optimum est: ibique invenitur bdellium, et lapis onychinus.',
        13: 'Et nomen fluvii secundi Gehon: ipse est qui circumit omnem terram Aethiopiae.',
        14: 'Nomen vero fluminis tertii, Tigris: ipse vadit contra Assyrios. Fluvius autem quartus, ipse est Euphrates.',
        15: 'Tulit ergo Dominus Deus hominem, et posuit eum in paradisum voluptatis, ut operaretur, et custodiret illum:',
        16: 'Praecepitque ei dicens: Ex omni ligno paradisi comede:',
        17: 'De ligno autem scientiae boni et mali ne comedas. in quocumque enim die comederis ex eo, morte morieris.',
        18: 'Dixit quoque Dominus Deus: Non est bonum esse hominem solum: faciamus ei adiutorium simile sibi.',
        19: 'Formatis igitur, Dominus Deus, de humo cunctis animantibus terrae, et universis volatilibus caeli, adduxit ea ad Adam, ut videret quid vocaret ea: omne enim quod vocavit Adam animae viventis, ipsum est nomen eius.',
        20: 'Appellavitque Adam nominibus suis cuncta animantia, et universa volatilia caeli, et omnes bestias terrae: Adae vero non inveniebatur adiutor similis eius.',
        21: 'Immisit ergo Dominus Deus soporem in Adam: cumque obdormisset, tulit unam de costis eius, et replevit carnem pro ea.',
        22: 'Et aedificavit Dominus Deus costam, quam tulerat de Adam, in mulierem: et adduxit eam ad Adam.',
        23: 'Dixitque Adam: Hoc nunc, os ex ossibus meis, et caro de carne mea: haec vocabitur Virago, quoniam de viro sumpta est.',
        24: 'Quamobrem relinquet homo patrem suum, et matrem, et adhaerebit uxori suae: et erunt duo in carne una.',
        25: 'Erat autem uterque nudus, Adam scilicet et uxor eius: et non erubescebant.',
    },
    3: {
        1: 'Sed et serpens erat callidior cunctis animantibus terrae quae fecerat Dominus Deus. Qui dixit ad mulierem: Cur praecepit vobis Deus ut non comederetis ex omni ligno paradisi?',
        2: 'Cui respondit mulier: De fructu lignorum, quae sunt in paradiso, vescimur:',
        3: 'de fructu vero ligni, quod est in medio paradisi, praecepit nobis Deus ne comederemus: et ne tangeremus illud, ne forte moriamur.',
        4: 'Dixit autem serpens ad mulierem: Nequaquam morte moriemini.',
        5: 'Scit enim Deus quod in quocumque die comederitis ex eo, aperientur oculi vestri: et eritis sicut dii, scientes bonum et malum.',
        6: 'Vidit igitur mulier quod bonum esset lignum ad vescendum, et pulchrum oculis, aspectuque delectabile: et tulit de fructu illius, et comedit: deditque viro suo, qui comedit.',
        7: 'Et aperti sunt oculi amborum: cumque cognovissent se esse nudos, consuerunt folia ficus, et fecerunt sibi perizomata.',
        8: 'Et cum audissent vocem Domini Dei deambulantis in paradiso ad auram post meridiem, abscondit se Adam et uxor eius a facie Domini Dei in medio ligni paradisi.',
        9: 'Vocavitque Dominus Deus Adam, et dixit ei: Ubi es?',
        10: 'Qui ait: Vocem tuam audivi in paradiso: et timui, eo quod nudus essem, et abscondi me.',
        11: 'Cui dixit Dominus: Quis enim indicavit tibi quod nudus esses, nisi quod ex ligno de quo praeceperam tibi ne comederes, comedisti?',
        12: 'Dixitque Adam: Mulier, quam dedisti mihi sociam, dedit mihi de ligno, et comedi.',
        13: 'Et dixit Dominus Deus ad mulierem: Quare hoc fecisti? Quae respondit: Serpens decepit me, et comedi.',
        14: 'Et ait Dominus Deus ad serpentem: Quia fecisti hoc, maledictus es inter omnia animantia, et bestias terrae: super pectus tuum gradieris, et terram comedes cunctis diebus vitae tuae.',
        15: 'Inimicitias ponam inter te et mulierem, et semen tuum et semen illius: ipsa conteret caput tuum, et tu insidiaberis calcaneo eius.',
        16: 'Mulieri quoque dixit: Multiplicabo aerumnas tuas, et conceptus tuos: in dolore paries filios, et sub viri potestate eris, et ipse dominabitur tui.',
        17: 'Adae vero dixit: Quia audisti vocem uxoris tuae, et comedisti de ligno, ex quo, praeceperam tibi, ne comederes, maledicta terra in opere tuo: in laboribus comedes ex ea cunctis diebus vitae tuae.',
        18: 'Spinas et tribulos germinabit tibi, et comedes herbas terrae.',
        19: 'In sudore vultus tui vesceris pane tuo, donec revertaris in terram de qua sumptus es: quia pulvis es, et in pulverem reverteris.',
        20: 'Et vocavit Adam nomen uxoris suae, Heva: eo quod mater esset cunctorum viventium.',
        21: 'Fecit quoque Dominus Deus Adae et uxori eius tunicas pelliceas, et induit eos:',
        22: 'Et ait: Ecce Adam quasi unus ex nobis factus est, sciens bonum et malum: nunc ergo ne forte mittat manum suam, et sumat etiam de ligno vitae, et comedat, et vivat in aeternum.',
        23: 'Emisit eum Dominus Deus de paradiso voluptatis, ut operaretur terram de qua sumptus est.',
        24: 'Eiecitque Adam: et collocavit ante paradisum voluptatis Cherubim, et flammeum gladium, atque versatilem, ad custodiendam viam ligni vitae.',
    },
    4: {
        1: 'Adam vero cognovit uxorem suam Hevam: quae concepit et peperit Cain, dicens: Possedi hominem per Deum.',
        2: 'Rursumque peperit fratrem eius Abel. Fuit autem Abel pastor ovium, et Cain agricola.',
        3: 'Factum est autem post multos dies ut offerret Cain de fructibus terrae munera Domino.',
        4: 'Abel quoque obtulit de primogenitis gregis sui, et de adipibus eorum: et respexit Dominus ad Abel, et ad munera eius.',
        5: 'Ad Cain autem, et ad munera illius non respexit: iratusque est Cain vehementer, et concidit vultus eius.',
        6: 'Dixitque Dominus ad eum: Quare iratus es? et cur concidit facies tua?',
        7: 'Nonne si bene egeris, recipies: sin autem male, statim in foribus peccatum tuum aderit? sed sub te erit appetitus eius, et tu dominaberis illius.',
        8: 'Dixitque Cain ad Abel fratrem suum: Egrediamur foras. Cumque essent in agro, consurrexit Cain adversus fratrem suum Abel, et interfecit eum.',
        9: 'Et ait Dominus ad Cain: Ubi est Abel frater tuus? Qui respondit: Nescio: Numquid custos fratris mei sum ego?',
        10: 'Dixitque ad eum: Quid fecisti? vox sanguinis fratris tui clamat ad me de terra.',
        11: 'Nunc igitur maledictus eris super terram, quae aperuit os suum, et suscepit sanguinem fratris tui de manu tua.',
        12: 'Cum operatus fueris eam, non dabit tibi fructus suos: vagus et profugus eris super terram.',
        13: 'Dixitque Cain ad Dominum: Maior est iniquitas mea, quam ut veniam merear.',
        14: 'Ecce eiicis me hodie a facie terrae, et a facie tua abscondar, et ero vagus et profugus in terra: omnis igitur qui invenerit me, occidet me.',
        15: 'Dixitque ei Dominus: Nequaquam ita fiet: sed omnis qui occiderit Cain, septuplum punietur. Posuitque Dominus in Cain signum, ut non interficeret eum omnis qui invenisset eum.',
        16: 'Egressusque Cain a facie Domini, habitavit profugus in terra ad orientalem plagam Eden.',
        17: 'Cognovit autem Cain uxorem suam, quae concepit, et peperit Henoch: et aedificavit civitatem, vocavitque nomen eius ex nomine filii sui, Henoch.',
        18: 'Porro Henoch genuit Irad, et Irad genuit Maviael, et Maviael genuit Mathusael, et Mathusael genuit Lamech.',
        19: 'Qui accepit duas uxores, nomen uni Ada, et nomen alteri Sella.',
        20: 'Genuitque Ada Iabel, qui fuit pater habitantium in tentoriis, atque pastorum.',
        21: 'Et nomen fratris eius Iubal: ipse fuit pater canentium cithara et organo.',
        22: 'Sella quoque genuit Tubalcain, qui fuit malleator et faber in cuncta opera aeris et ferri. Soror vero Tubalcain, Noema.',
        23: 'Dixitque Lamech uxoribus suis Adae et Sellae: Audite vocem meam uxores Lamech, auscultate sermonem meum: quoniam occidi virum in vulnus meum, et adolescentulum in livorem meum.',
        24: 'Septuplum ultio dabitur de Cain: de Lamech vero septuagies septies.',
        25: 'Cognovit quoque adhuc Adam uxorem suam: et peperit filium, vocavitque nomen eius Seth, dicens: Posuit mihi Deus semen aliud pro Abel, quem occidit Cain.',
        26: 'Sed et Seth natus est filius, quem vocavit Enos: iste coepit invocare nomen Domini.',
    },
    5: {
        1: 'Hic est liber generationis Adam. In die, qua creavit Deus hominem, ad similitudinem Dei fecit illum.',
        2: 'Masculum et feminam creavit eos, et benedixit illis: et vocavit nomen eorum Adam, in die quo creati sunt.',
        3: 'Vixit autem Adam centum triginta annis: et genuit filium ad imaginem et similitudinem suam, vocavitque nomen eius Seth.',
        4: 'Et facti sunt dies Adam, postquam genuit Seth, octingenti anni: genuitque filios et filias.',
        5: 'Et factum est omne tempus quod vixit Adam, anni nongenti triginta, et mortuus est.',
        6: 'Vixit quoque Seth centum quinque annis, et genuit Enos.',
        7: 'Vixitque Seth postquam genuit Enos, octingentis septem annis, genuitque filios et filias.',
        8: 'Et facti sunt omnes dies Seth nongentorum duodecim annorum, et mortuus est.',
        9: 'Vixit vero Enos nonaginta annis, et genuit Cainan.',
        10: 'Post cuius ortum vixit octingentis quindecim annis, et genuit filios, et filias.',
        11: 'Factique sunt omnes dies Enos nongenti quinque anni, et mortuus est.',
        12: 'Vixit quoque Cainan septuaginta annis, et genuit Malaleel.',
        13: 'Et vixit Cainan, postquam genuit Malaleel, octingentis quadraginta annis, genuitque filios et filias.',
        14: 'Et facti sunt omnes dies Cainan nongenti decem anni, et mortuus est.',
        15: 'Vixit autem Malaleel sexaginta quinque annis, et genuit Iared.',
        16: 'Et vixit Malaleel postquam genuit Iared, octingentis triginta annis: et genuit filios et filias.',
        17: 'Et facti sunt omnes dies Malaleel octingenti nonaginta quinque anni, et mortuus est.',
        18: 'Vixitque Iared centum sexaginta duobus annis, et genuit Henoch.',
        19: 'Et vixit Iared, postquam genuit Henoch, octingentis annis, et genuit filios et filias.',
        20: 'Et facti sunt omnes dies Iared nongenti sexaginta duo anni, et mortuus est.',
        21: 'Porro Henoch vixit sexaginta quinque annis, et genuit Mathusalam.',
        22: 'Et vixit Henoch postquam genuit Mathusalam, trecentis annis, et genuit filios et filias.',
        23: 'Et facti sunt omnes dies Henoch trecenti sexaginta quinque anni.',
        24: 'Ambulavitque cum Deo, et non apparuit: quia tulit eum Deus.',
        25: 'Vixit quoque Mathusala centum octoginta septem annis, et genuit Lamech.',
        26: 'Et vixit Mathusala, postquam genuit Lamech, septingentis octoginta duobus annis, et genuit filios et filias.',
        27: 'Et facti sunt omnes dies Mathusala nongenti sexaginta novem anni, et mortuus est.',
        28: 'Vixit autem Lamech centum octoginta duobus annis, et genuit filium:',
        29: 'vocavitque nomen eius Noe, dicens: Iste consolabitur nos ab operibus et laboribus manuum nostrarum in terra, cui maledixit Dominus.',
        30: 'Vixitque Lamech, postquam genuit Noe, quingentis nonaginta quinque annis, et genuit filios et filias.',
        31: 'Et facti sunt omnes dies Lamech, septingenti septuaginta septem anni, et mortuus est. Noe vero cum quingentorum esset annorum, genuit Sem, Cham, et Iapheth.',
    },
    6: {
        1: 'Cumque coepissent homines multiplicari super terram, et filias procreassent,',
        2: 'Videntes filii Dei filias hominum quod essent pulchrae, acceperunt sibi uxores ex omnibus, quas elegerant.',
        3: 'Dixitque Deus: Non permanebit spiritus meus in homine in aeternum, quia caro est: eruntque dies illius centum viginti annorum.',
        4: 'Gigantes autem erant super terram in diebus illis. postquam enim ingressi sunt filii Dei ad filias hominum, illaeque genuerunt, isti sunt potentes a saeculo viri famosi.',
        5: 'Videns autem Deus quod multa malitia hominum esset in terra, et cuncta cogitatio cordis intenta esset ad malum omni tempore,',
        6: 'poenituit eum quod hominum fecisset in terra. Et tactus dolore cordis intrinsecus,',
        7: 'Delebo, inquit, hominem, quem creavi, a facie terrae, ab homine usque ad animantia, a reptili usque ad volucres caeli. poenitet enim me fecisse eos.',
        8: 'Noe vero invenit gratiam coram Domino.',
        9: 'Hae sunt generationes Noe: Noe vir iustus atque perfectus fuit in generationibus suis, cum Deo ambulavit.',
        10: 'Et genuit tres filios, Sem, Cham et Iapheth.',
        11: 'Corrupta est autem terra coram Deo, et repleta est iniquitate.',
        12: 'Cumque vidisset Deus terram esse corruptam, (omnis quippe caro corruperat viam suam super terram)',
        13: 'dixit ad Noe: Finis universae carnis venit coram me: repleta est terra iniquitate a facie eorum, et ego disperdam eos cum terra.',
        14: 'Fac tibi arcam de lignis laevigatis: mansiunculas in arca facies, et bitumine linies intrinsecus, et extrinsecus.',
        15: 'Et sic facies eam: Trecentorum cubitorum erit longitudo arcae, quinquaginta cubitorum latitudo, et triginta cubitorum altitudo illius.',
        16: 'Fenestram in arca facies, et in cubito consummabis summitatem eius: ostium autem arcae pones ex latere: deorsum, coenacula, et tristega facies in ea.',
        17: 'Ecce ego adducam aquas diluvii super terram, ut interficiam omnem carnem, in qua spiritus vitae est subter caelum: et Universa quae in terra sunt, consumentur.',
        18: 'Ponamque foedus meum tecum: et ingredieris arcam tu et filii tui, uxor tua, et uxores filiorum tuorum tecum.',
        19: 'Et ex cunctis animantibus universae carnis bina induces in arcam, ut vivant tecum: masculini sexus et feminini.',
        20: 'De volucribus iuxta genus suum, et de iumentis in genere suo, et ex omni reptili terrae secundum genus suum: bina de omnibus ingredientur tecum, ut possint vivere.',
        21: 'Tolles igitur tecum ex omnibus escis, quae mandi possunt, et comportabis apud te: et erunt tam tibi, quam illis in cibum.',
        22: 'Fecit igitur Noe omnia, quae praeceperat illi Deus.',
    },
    7: {
        1: 'Dixitque Dominus ad eum: Ingredere tu, et omnis domus tua in arcam: te enim vidi iustum coram me in generatione hac.',
        2: 'Ex omnibus animantibus mundis tolle septena et septena, masculum et feminam: de animantibus vero immundis duo et duo, masculum et feminam.',
        3: 'Sed et de volatilibus caeli septena et septena, masculum et feminam: ut salvetur semen super faciem universae terrae.',
        4: 'Adhuc enim, et post dies septem ego pluam super terram quadraginta diebus et quadraginta noctibus: et delebo omnem substantiam, quam feci, de superficie terrae.',
        5: 'Fecit ergo Noe omnia, quae mandaverat ei Dominus.',
        6: 'Eratque sexcentorum annorum quando diluvii aquae inundaverunt super terram.',
        7: 'Et ingressus est Noe et filii eius, uxor eius et uxores filiorum eius cum eo in arcam propter aquas diluvii.',
        8: 'De animantibus quoque mundis et immundis, et de volucribus, et ex omni, quod movetur super terram,',
        9: 'duo et duo ingressa sunt ad Noe in arcam, masculus et femina, sicut praeceperat Dominus Noe.',
        10: 'Cumque transissent septem dies, aquae diluvii inundaverunt super terram.',
        11: 'Anno sexcentesimo vitae Noe, mense secundo, septimodecimo die mensis, rupti sunt omnes fontes abyssi magnae, et cataractae caeli apertae sunt:',
        12: 'et facta est pluvia super terram quadraginta diebus et quadraginta noctibus.',
        13: 'In articulo diei illius ingressus est Noe, et Sem, et Cham, et Iapheth filii eius: uxor illius, et uxores filiorum eius cum eis in arcam:',
        14: 'ipsi et omne animal secundum genus suum, universaque iumenta in genere suo, et omne quod movetur super terram in genere suo, cunctumque volatile secundum genus suum, universae aves, omnesque volucres',
        15: 'ingressae sunt ad Noe in arcam, bina et bina ex omni carne, in qua erat spiritus vitae.',
        16: 'Et quae ingressa sunt, masculus et femina ex omni carne introierunt, sicut praeceperat ei Deus: et inclusit eum Dominus deforis.',
        17: 'Factumque est diluvium quadraginta diebus super terram: et multiplicatae sunt aquae, et elevaverunt arcam in sublime a terra.',
        18: 'Vehementer enim inundaverunt: et omnia repleverunt in superficie terrae: porro arca ferebatur super aquas.',
        19: 'Et aquae praevaluerunt nimis super terram: opertique sunt omnes montes excelsi sub universo caelo.',
        20: 'Quindecim cubitis altior fuit aqua super montes, quos operuerat.',
        21: 'Consumptaque est omnis caro quae movebatur super terram, volucrum, bestiarum, omniumque reptilium, quae reptant super terram: animantiumque omnium universi homines,',
        22: 'et cuncta, in quibus spiraculum vitae est in terra, mortua sunt.',
        23: 'Et delevit omnem substantiam, quae erat super terram, ab homine usque ad pecus, tam reptile quam volucres caeli: deleta sunt de terra: remansit autem solus Noe, et qui cum eo erant in arca.',
        24: 'Obtinueruntque aquae terram centum quinquaginta diebus.',
    },
    8: {
        1: 'Recordatus autem Deus Noe, cunctorumque animantium, et omnium iumentorum, quae erant cum eo in arca, adduxit spiritum super terram, et imminutae sunt aquae.',
        2: 'Et clausi sunt fontes abyssi, et cataractae caeli: et prohibitae sunt pluviae de caelo.',
        3: 'Reversaeque sunt aquae de terra euntes et redeuntes: et coeperunt minui post centum quinquaginta dies.',
        4: 'Requievitque arca mense septimo, vigesimo septimo die mensis super montes Armeniae.',
        5: 'At vero aquae ibant et decrescebant usque ad decimum mensem: decimo enim mense, primo die mensis, apparuerunt cacumina montium.',
        6: 'Cumque transissent quadraginta dies, aperiens Noe fenestram arcae, quam fecerat, dimisit corvum:',
        7: 'qui egrediebatur, et non revertebatur, donec siccarentur aquae super terram.',
        8: 'Emisit quoque columbam post eum, ut videret si iam cessassent aquae super faciem terrae.',
        9: 'Quae cum non invenisset ubi requiesceret pes eius, reversa est ad eum in arcam: aquae enim erant super universam terram: extenditque manum suam, et apprehensam intulit in arcam.',
        10: 'Expectatis autem ultra septem diebus aliis, rursum dimisit columbam ex arca.',
        11: 'At illa venit ad eum ad vesperam, portans ramum olivae virentibus foliis in ore suo. intellexit ergo Noe quod cessassent aquae super terram.',
        12: 'Expectavitque nihilominus septem alios dies: et emisit columbam, quae non est reversa ultra ad eum.',
        13: 'Igitur sexcentesimo primo anno, primo mense, prima die mensis imminutae sunt aquae super terram: et aperiens Noe tectum arcae, aspexit, viditque quod exiccata esset superficies terrae.',
        14: 'Mense secundo, septimo et vigesimo die mensis arefacta est terra.',
        15: 'Locutus est autem Deus ad Noe, dicens:',
        16: 'Egredere de arca, tu et uxor tua, filii tui et uxores filiorum tuorum tecum.',
        17: 'Cuncta animantia, quae sunt apud te, ex omni carne, tam in volatilibus quam in bestiis et universis reptilibus, quae reptant super terram, educ tecum, et ingredimini super terram: crescite et multiplicamini super eam.',
        18: 'Egressus est ergo Noe, et filii eius: uxor illius, et uxores filiorum eius cum eo.',
        19: 'Sed et omnia animantia, iumenta, et reptilia quae reptant super terram secundum genus suum, egressa sunt de arca.',
        20: 'Aedificavit autem Noe altare Domino: et tollens de cunctis pecoribus et volucribus mundis, obtulit holocausta super altare.',
        21: 'Odoratusque est Dominus odorem suavitatis, et ait: Nequaquam ultra maledicam terrae propter homines: sensus enim et cogitatio humani cordis in malum prona sunt ab adolescentia sua: non igitur ultra percutiam omnem animam viventem sicut feci.',
        22: 'Cunctis diebus terrae, sementis et messis, frigus et aestus, aestas et hiems, nox et dies non requiescent.',
    },
    9: {
        1: 'Benedixitque Deus Noe et filiis eius. Et dixit ad eos: Crescite, et multiplicamini, et replete terram.',
        2: 'Et terror vester ac tremor sit super cuncta animalia terrae, et super omnes volucres caeli, cum universis quae moventur super terram: omnes pisces maris manui vestrae traditi sunt.',
        3: 'Et omne, quod movetur et vivit, erit vobis in cibum: quasi olera virentia tradidi vobis omnia.',
        4: 'Excepto, quod carnem cum sanguine non comedetis.',
        5: 'Sanguinem enim animarum vestrarum requiram de manu cunctarum bestiarum: et de manu hominis, de manu viri, et de manu fratris eius requiram animam hominis.',
        6: 'Quicumque effuderit humanum sanguinem, fundetur sanguis illius: ad imaginem quippe Dei factus est homo.',
        7: 'Vos autem crescite et multiplicamini, et ingredimini super terram, et implete eam.',
        8: 'Haec quoque dixit Deus ad Noe, et ad filios eius cum eo:',
        9: 'Ecce ego statuam pactum meum vobiscum, et cum semine vestro post vos:',
        10: 'et ad omnem animam viventem, quae est vobiscum, tam in volucribus quam in iumentis et pecudibus terrae cunctis, quae egressa sunt de arca, et universis bestiis terrae.',
        11: 'Statuam pactum meum vobiscum, et nequaquam ultra interficietur omnis caro aquis diluvii, neque erit deinceps diluvium dissipans terram.',
        12: 'Dixitque Deus: Hoc signum foederis quod do inter me et vos, et ad omnem animam viventem, quae est vobiscum in generationes sempiternas:',
        13: 'Arcum meum ponam in nubibus, et erit signum foederis inter me, et inter terram.',
        14: 'Cumque obduxero nubibus caelum, apparebit arcus meus in nubibus:',
        15: 'et recordabor foederis mei vobiscum, et cum omni anima vivente quae carnem vegetat: et non erunt ultra aquae diluvii ad delendum universam carnem.',
        16: 'Eritque arcus meus in nubibus, et videbo illum, et recordabor foederis sempiterni quod pactum est inter Deum et omnem animam viventem universae carnis quae est super terram.',
        17: 'Dixitque Deus ad Noe: Hoc est signum foederis, quod constitui inter me et omnem carnem super terram.',
        18: 'Erant ergo filii Noe, qui egressi sunt de arca, Sem, Cham, et Iapheth: porro Cham ipse est pater Chanaan.',
        19: 'Tres isti filii sunt Noe: et ab his disseminatum est omne genus hominum super universam terram.',
        20: 'Coepitque Noe vir agricola exercere terram, et plantavit vineam.',
        21: 'Bibensque vinum inebriatus est, et nudatus in tabernaculo suo.',
        22: 'Quod cum vidisset Cham pater Chanaan, verenda scilicet patris sui nudata, nunciavit duobus fratribus suis foras.',
        23: 'At vero Sem et Iapheth pallium imposuerunt humeris suis, et incedentes retrorsum, operuerunt verenda patris sui: faciesque eorum aversae erant, et patris virilia non viderunt.',
        24: 'Evigilans autem Noe ex vino, cum didicisset quae fecerat ei filius suus minor,',
        25: 'ait: Maledictus Chanaan, servus servorum erit fratribus suis.',
        26: 'Dixitque: Benedictus Dominus Deus Sem, sit Chanaan servus eius.',
        27: 'Dilatet Deus Iapheth, et habitet in tabernaculis Sem, sitque Chanaan servus eius.',
        28: 'Vixit autem Noe post diluvium trecentis quinquaginta annis.',
        29: 'Et impleti sunt omnes dies eius nongentorum quinquaginta annorum: et mortuus est.',
    },
    10: {
        1: 'Hae sunt generationes filiorum Noe, Sem, Cham, et Iapheth: natique sunt eis filii post diluvium.',
        2: 'Filii Iapheth: Gomer, et Magog, et Madai, et Iavan, et Thubal, et Mosoch, et Thiras.',
        3: 'Porro filii Gomer: Ascenez et Riphath et Thogorma.',
        4: 'Filii autem Iavan: Elisa et Tharsis, Cetthim et Dodanim.',
        5: 'Ab his divisae sunt insulae gentium in regionibus suis, unusquisque secundum linguam suam et familias suas in nationibus suis.',
        6: 'Filii autem Cham: Chus, et Mesraim, et Phuth, et Chanaan.',
        7: 'Filii autem Chus: Saba, et Hevila, et Sabatha, et Regma, et Sabatacha. Filii Regma: Saba, et Dadan.',
        8: 'Porro Chus genuit Nemrod: ipse coepit esse potens in terra,',
        9: 'et erat robustus venator coram Domino. Ob hoc exivit proverbium: Quasi Nemrod robustus venator coram Domino.',
        10: 'Fuit autem principium regni eius Babylon, et Arach, et Achad, et Chalanne, in terra Sennaar.',
        11: 'De terra illa egressus est Assur, et aedificavit Niniven, et plateas civitatis, et Chale.',
        12: 'Resen quoque inter Niniven et Chale: haec est civitas magna.',
        13: 'At vero Mesraim genuit Ludim, et Anamim, et Laabim, et Nephthuim,',
        14: 'et Phetrusim, et Chasluim: de quibus egressi sunt Philisthiim et Caphtorim.',
        15: 'Chanaan autem genuit Sidonem primogenitum suum, Hethaeum,',
        16: 'et Iebusaeum, et Amorrhaeum, et Gergesaeum,',
        17: 'et Hevaeum, et Aracaeum: Sinaeum,',
        18: 'et Aradium, Samaraeum et Amathaeum: et per hos disseminati sunt populi Chananaeorum.',
        19: 'Factique sunt termini Chanaan venientibus a Sidone Geraram usque ad Gazam, donec ingrediaris Sodomam et Gomorrham, et Adamam, et Seboim usque Lasa.',
        20: 'Hi sunt filii Cham in cognationibus, et linguis, et generationibus, terrisque et gentibus suis.',
        21: 'De Sem quoque nati sunt, patre omnium filiorum Heber, fratre Iapheth maiore.',
        22: 'Filii Sem: Aelam et Assur, et Arphaxad, et Lud, et Aram.',
        23: 'Filii Aram: Us, et Hul, et Gether, et Mes.',
        24: 'At vero Arphaxad genuit Sale, de quo ortus est Heber.',
        25: 'Natique sunt Heber filii duo: nomen uni Phaleg, eo quod in diebus eius divisa sit terra: et nomen fratris eius Iectan.',
        26: 'Qui Iectan genuit Elmodad, et Saleph, et Asarmoth, Iare,',
        27: 'et Aduram, et Uzal, et Decla,',
        28: 'et Ebal, et Abimael, Saba,',
        29: 'et Ophir, et Hevila, et Iobab. omnes isti, filii Iectan.',
        30: 'Et facta est habitatio eorum de Messa pergentibus usque Sephar montem orientalem.',
        31: 'Isti sunt filii Sem secundum cognationes et linguas, et regiones in gentibus suis.',
        32: 'Hae familiae Noe iuxta populos et nationes suas. Ab his divisae sunt gentes in terra post diluvium.',
    },
    11: {
        1: 'Erat autem terra labii unius, et sermonum eorumdem.',
        2: 'Cumque proficiscerentur de oriente, invenerunt campum in terra Sennaar, et habitaverunt in eo.',
        3: 'Dixitque alter ad proximum suum: Venite, faciamus lateres, et coquamus eos igni. Habueruntque lateres pro saxis, et bitumen pro caemento:',
        4: 'et dixerunt: Venite, faciamus nobis civitatem et turrim, cuius culmen pertingat ad caelum: et celebremus nomen nostrum antequam dividamur in universas terras.',
        5: 'Descendit autem Dominus ut videret civitatem et turrim, quam aedificabant filii Adam,',
        6: 'et dixit: Ecce, unus est populus, et unum est labium omnibus: coeperuntque hoc facere, nec desistent a cogitationibus suis, donec eas opere compleant.',
        7: 'Venite igitur, descendamus, et confundamus ibi linguam eorum, ut non audiat unusquisque vocem proximi sui.',
        8: 'Atque ita divisit eos Dominus ex illo loco in universas terras, et cessaverunt aedificare civitatem.',
        9: 'Et idcirco vocatum est nomen eius Babel, quia ibi confusum est labium universae terrae: et inde dispersit eos Dominus super faciem cunctarum regionum.',
        10: 'Hae sunt generationes Sem: Sem erat centum annorum quando genuit Arphaxad, biennio post diluvium.',
        11: 'Vixitque Sem postquam genuit Arphaxad, quingentis annis: et genuit filios et filias.',
        12: 'Porro Arphaxad vixit triginta quinque annis, et genuit Sale.',
        13: 'Vixitque Arphaxad postquam genuit Sale, trecentis tribus annis: et genuit filios et filias.',
        14: 'Sale quoque vixit triginta annis, et genuit Heber.',
        15: 'Vixitque Sale postquam genuit Heber, quadringentis tribus annis: et genuit filios et filias.',
        16: 'Vixit autem Heber triginta quattuor annis, et genuit Phaleg.',
        17: 'Et vixit Heber postquam genuit Phaleg, quadringentis triginta annis: et genuit filios et filias.',
        18: 'Vixit quoque Phaleg triginta annis, et genuit Reu.',
        19: 'Vixitque Phaleg postquam genuit Reu, ducentis novem annis, et genuit filios et filias.',
        20: 'Vixit autem Reu triginta duobus annis, et genuit Sarug.',
        21: 'Vixit quoque Reu postquam genuit Sarug, ducentis septem annis: et genuit filios et filias.',
        22: 'Vixit vero Sarug triginta annis, et genuit Nachor.',
        23: 'Vixitque Sarug postquam genuit Nachor, ducentis annis: et genuit filios et filias.',
        24: 'Vixit autem Nachor viginti novem annis, et genuit Thare.',
        25: 'Vixitque Nachor postquam genuit Thare, centum decem et novem annis: et genuit filios et filias.',
        26: 'Vixitque Thare septuaginta annis, et genuit Abram et Nachor, et Aran.',
        27: 'Hae sunt autem generationes Thare: Thare genuit Abram, Nachor, et Aran. Porro Aran genuit Lot.',
        28: 'Mortuusque est Aran ante Thare patrem suum, in terra nativitatis suae in Ur Chaldaeorum.',
        29: 'Duxerunt autem Abram et Nachor uxores: nomen uxoris Abram, Sarai: et nomen uxoris Nachor, Melcha filia Aran patris Melchae, et patris Ieschae.',
        30: 'Erat autem Sarai sterilis, nec habebat liberos.',
        31: 'Tulit itaque Thare Abram filium suum, et Lot filium Aran, filium filii sui, et Sarai nurum suam, uxorem Abram filii sui, et eduxit eos de Ur Chaldaeorum, ut irent in terram Chanaan: veneruntque usque Haran, et habitaverunt ibi.',
        32: 'Et facti sunt dies Thare ducentorum quinque annorum, et mortuus est in Haran.',
    },
    12: {
        1: 'Dixit autem Dominus ad Abram: Egredere de terra tua, et de cognatione tua, et de domo patris tui, et veni in terram, quam monstravero tibi.',
        2: 'Faciamque te in gentem magnam, et benedicam tibi, et magnificabo nomen tuum, erisque benedictus.',
        3: 'Benedicam benedicentibus tibi, et maledicam maledicentibus tibi, atque IN TE benedicentur universae cognationes terrae.',
        4: 'Egressus est itaque Abram sicut praeceperat ei Dominus, et ivit cum eo Lot: septuaginta quinque annorum erat Abram cum egrederetur de Haran.',
        5: 'Tulitque Sarai uxorem suam, et Lot filium fratris sui, universamque substantiam quam possederant, et animas quas fecerant in Haran: et egressi sunt ut irent in terram Chanaan. Cumque venissent in eam,',
        6: 'pertransivit Abram terram usque ad locum Sichem, et usque ad convallem illustrem: Chananaeus autem tunc erat in terra.',
        7: 'Apparuit autem Dominus Abram, et dixit ei: Semini tuo dabo terram hanc. Qui aedificavit ibi altare Domino, qui apparuerat ei.',
        8: 'Et inde transgrediens ad montem, qui erat contra orientem Bethel, tetendit ibi tabernaculum suum, ab occidente habens Bethel, et ab oriente Hai: aedificavit quoque ibi altare Domino, et invocavit nomen eius.',
        9: 'Perrexitque Abram vadens, et ultra progrediens ad meridiem.',
        10: 'Facta est autem fames in terra: descenditque Abram in Aegyptum, ut peregrinaretur ibi: praevaluerat enim fames in terra.',
        11: 'Cumque prope esset ut ingrederetur Aegyptum, dixit Sarai uxori suae: Novi quod pulchra sis mulier:',
        12: 'et quod cum viderint te Aegyptii, dicturi sunt: Uxor illius est: et interficient me, et te reservabunt.',
        13: 'Dic ergo, obsecro te, quod soror mea sis: ut bene sit mihi propter te, et vivat anima mea ob gratiam tui.',
        14: 'Cum itaque ingressus esset Abram Aegyptum, viderunt Aegyptii mulierem quod esset pulchra nimis.',
        15: 'Et nunciaverunt principes Pharaoni, et laudaverunt eam apud illum: et sublata est mulier in domum Pharaonis.',
        16: 'Abram vero bene usi sunt propter illam: Fueruntque ei oves et boves, et asini, et servi et famulae, et asinae et cameli.',
        17: 'Flagellavit autem Dominus Pharaonem plagis maximis, et domum eius propter Sarai uxorem Abram.',
        18: 'Vocavitque Pharao Abram, et dixit ei: Quidnam est hoc quod fecisti mihi? quare non indicasti quod uxor tua esset?',
        19: 'Quam ob causam dixisti esse sororem tuam, ut tollerem eam mihi in uxorem? Nunc igitur ecce coniux tua, accipe eam, et vade.',
        20: 'Praecepitque Pharao super Abram viris: et deduxerunt eum, et uxorem illius, et omnia quae habebat.',
    },
    13: {
        1: 'Ascendit ergo Abram de Aegypto, ipse et uxor eius, et omnia quae habebat, et Lot cum eo ad australem plagam.',
        2: 'Erat autem dives valde in possessione auri et argenti.',
        3: 'Reversusque est per iter, quo venerat, a meridie in Bethel usque ad locum ubi prius fixerat tabernaculum inter Bethel et Hai:',
        4: 'in loco altaris quod fecerat prius, et invocavit ibi nomen Domini.',
        5: 'Sed et Lot qui erat cum Abram, fuerunt greges ovium, et armenta, et tabernacula.',
        6: 'Nec poterat eos capere terra, ut habitarent simul: erat quippe substantia eorum multa, et nequibant habitare communiter.',
        7: 'Unde et facta est rixa inter pastores gregum Abram et Lot. Eo autem tempore Chananaeus et Pherezaeus habitabant in terra illa.',
        8: 'Dixit ergo Abram ad Lot: Ne quaeso sit iurgium inter me et te, et inter pastores meos, et pastores tuos: fratres enim sumus.',
        9: 'Ecce universa terra coram te est: recede a me, obsecro: si ad sinistram ieris, ego dexteram tenebo: si tu dexteram elegeris, ego ad sinistram pergam.',
        10: 'Elevatis itaque Lot oculis, vidit omnem circa regionem Iordanis, quae universa irrigabatur antequam subverteret Dominus Sodomam et Gomorrham, sicut paradisus Domini, et sicut Aegyptus venientibus in Segor.',
        11: 'Elegitque sibi Lot regionem circa Iordanem, et recessit ab Oriente: divisique sunt alterutrum a fratre suo.',
        12: 'Abram habitavit in terra Chanaan: Lot vero moratus est in oppidis, quae erant circa Iordanem, et habitavit in Sodomis.',
        13: 'Homines autem Sodomitae pessimi erant, et peccatores coram Domino nimis.',
        14: 'Dixitque Dominus ad Abram, postquam divisus est ab eo Lot: Leva oculos tuos in directum, et vide a loco, in quo nunc es, ad aquilonem et meridiem, ad orientem et occidentem.',
        15: 'Omnem terram, quam conspicis, tibi dabo, et semini tuo usque in sempiternum.',
        16: 'Faciamque semen tuum sicut pulverem terrae: si quis potest hominum numerare pulverem terrae, semen quoque tuum numerare poterit.',
        17: 'Surge ergo, et perambula terram in longitudine, et in latitudine sua: quia tibi daturus sum eam.',
        18: 'Movens igitur tabernaculum suum Abram, venit et habitavit iuxta convallem Mambre, quae est in Hebron: aedificavitque ibi altare Domino.',
    },
    14: {
        1: 'Factum est autem in illo tempore, ut Amraphel rex Sennaar, et Arioch rex Ponti, et Chodorlahomor rex Elamitarum, et Thadal rex Gentium',
        2: 'inirent bellum contra Bara regem Sodomorum, et contra Bersa regem Gomorrhae, et contra Sennaab regem Adamae, et contra Semeber regem Seboim, contraque regem Balae, ipsa est Segor.',
        3: 'Omnes hi convenerunt in vallem Silvestrem, quae nunc est mare salis.',
        4: 'Duodecim enim annis servierunt Chodorlahomor, et tertiodecimo anno recesserunt ab eo.',
        5: 'Igitur quartodecimo anno venit Chodorlahomor, et reges qui erant cum eo: percusseruntque Raphaim in Astaroth et Carnaim, et Zuzim cum eis, et Emim in Save Cariathaim,',
        6: 'et Chorraeos in montibus Seir, usque ad Campestria Pharan, quae est in solitudine.',
        7: 'Reversique sunt, et venerunt usque ad fontem Misphat, ipsa est Cades: et percusserunt omnem regionem Amalecitarum, et Amorrhaeum, qui habitabat in Asasonthamar.',
        8: 'Et egressi sunt rex Sodomorum, et rex Gomorrhae, rexque Adamae, et rex Seboim, necnon et rex Balae, quae est Segor: et direxerunt aciem contra eos in valle Silvestri:',
        9: 'scilicet adversus Chodorlahomor regem Elamitarum, et Thadal regem gentium, et Amraphel regem Sennaar, et Arioch regem Ponti: quattuor reges adversus quinque.',
        10: 'Vallis autem Silvestris habebat puteos multos bituminis. Itaque rex Sodomorum, et rex Gomorrhae, terga verterunt, cecideruntque ibi: et qui remanserant, fugerunt ad montem.',
        11: 'Tulerunt autem omnem substantiam Sodomorum et Gomorrhae, et universa quae ad cibum pertinent, et abierunt:',
        12: 'necnon et Lot et substantiam eius, filium fratris Abram, qui habitabat in Sodomis.',
        13: 'Et ecce unus, qui evaserat, nunciavit Abram Hebraeo, qui habitabat in convalle Mambre Amorrhaei fratris Escol, et fratris Aner: hi enim pepigerant foedus cum Abram.',
        14: 'Quod cum audisset Abram, captum videlicet Lot fratrem suum, numeravit expeditos vernaculos suos trecentos decem, et octo: et persecutus est eos usque Dan.',
        15: 'Et divisis sociis, irruit super eos nocte: percussitque eos, et persecutus est eos usque Hoba, et Phoenicem, quae est ad laevam Damasci.',
        16: 'Reduxitque omnem substantiam, et Lot fratrem suum cum substantia illius, mulieres quoque et populum.',
        17: 'Egressus est autem rex Sodomorum in occursum eius postquam reversus est a caede Chodorlahomor, et regum qui cum eo erant in valle Save, quae est vallis regis.',
        18: 'At vero Melchisedech rex Salem, proferens panem et vinum, erat enim Sacerdos Dei altissimi,',
        19: 'benedixit ei, et ait: Benedictus Abram Deo excelso, qui creavit caelum et terram:',
        20: 'et benedictus Deus excelsus, quo protegente, hostes in manibus tuis sunt. Et dedit ei decimas ex omnibus.',
        21: 'Dixit autem rex Sodomorum ad Abram: Da mihi animas, cetera tolle tibi.',
        22: 'Qui respondit ei: Levo manum meam ad Dominum Deum excelsum possessorem caeli et terrae,',
        23: 'quod a filo subtegminis usque ad corigiam caligae, non accipiam ex omnibus quae tua sunt, ne dicas: Ego ditavi Abram:',
        24: 'exceptis his, quae comederunt iuvenes, et partibus virorum, qui venerunt mecum, Aner, Eschol, et Mambre: isti accipient partes suas.',
    },
    15: {
        1: 'His itaque transactis, factus est sermo Domini ad Abram per visionem dicens: Noli timere Abram, ego protector tuus sum, et merces tua magna nimis.',
        2: 'Dixitque Abram: Domine Deus, quid dabis mihi? ego vadam absque liberis: et filius procuratoris domus meae iste Damascus Eliezer.',
        3: 'Addiditque Abram: Mihi autem non dedisti semen: et ecce vernaculus meus, heres meus erit.',
        4: 'Statimque sermo Domini factus est ad eum, dicens: Non erit hic heres tuus: sed qui egredietur de utero tuo, ipsum habebis heredem.',
        5: 'Eduxitque eum foras, et ait illi: Suspice caelum, et numera stellas, si potes. Et dixit ei: Sic erit semen tuum.',
        6: 'Credidit Abram Deo, et reputatum est illi ad iustitiam.',
        7: 'Dixitque ad eum: Ego Dominus qui eduxi te de Ur Chaldaeorum ut darem tibi terram istam, et possideres eam.',
        8: 'At ille ait: Domine Deus, unde scire possum, quod possessurus sim eam?',
        9: 'Et respondens Dominus: Sume, inquit, mihi vaccam triennem, et capram trimam, et arietem annorum trium, turturem quoque, et columbam.',
        10: 'Qui tollens universa haec, divisit ea per medium, et utrasque partes contra se altrinsecus posuit: aves autem non divisit.',
        11: 'Descenderuntque volucres super cadavera, et abigebat eas Abram.',
        12: 'Cumque sol occumberet, sopor irruit super Abram, et horror magnus et tenebrosus invasit eum.',
        13: 'Dictumque est ad eum: Scito praenoscens quod peregrinum futurum sit semen tuum in terra non sua, et subiicient eos servituti, et affligent quadringentis annis.',
        14: 'Verumtamen gentem, cui servituri sunt, ego iudicabo: et post haec egredientur cum magna substantia.',
        15: 'Tu autem ibis ad patres tuos in pace, sepultus in senectute bona.',
        16: 'Generatione autem quarta revertentur huc: necdum enim completae sunt iniquitates Amorrhaeorum usque ad praesens tempus.',
        17: 'Cum ergo occubuisset sol, facta est caligo tenebrosa, et apparuit clibanus fumans, et lampas ignis transiens inter divisiones illas.',
        18: 'In illo die pepigit Dominus foedus cum Abram, dicens: Semini tuo dabo terram hanc a fluvio Aegypti usque ad fluvium magnum Euphraten,',
        19: 'Cinaeos, et Cenezaeos, Cedmonaeos,',
        20: 'et Hethaeos, et Pherezaeos, Raphaim quoque,',
        21: 'et Amorrhaeos, et Chananaeos, et Gergesaeos, et Iebusaeos.',
    },
    16: {
        1: 'Igitur Sarai, uxor Abram, non genuerat sibi liberos: sed habens ancillam Aegyptiam nomine Agar,',
        2: 'dixit marito suo: Ecce, conclusit me Dominus, ne parerem: ingredere ad ancillam meam, si forte saltem ex illa suscipiam filios. Cumque ille acquiesceret deprecanti,',
        3: 'tulit Agar Aegyptiam ancillam suam post annos decem quam habitare coeperant in terra Chanaan: et dedit eam viro suo uxorem.',
        4: 'Qui ingressus est ad eam. At illa concepisse se videns, despexit dominam suam.',
        5: 'Dixitque Sarai ad Abram: Inique agis contra me: ego dedi ancillam meam in sinum tuum, quae videns quod conceperit, despectui me habet. iudicet Dominus inter me, et te.',
        6: 'Cui respondens Abram: Ecce, ait, ancilla tua in manu tua est, utere ea ut libet. Affligente igitur eam Sarai, fugam iniit.',
        7: 'Cumque invenisset eam angelus Domini iuxta fontem aquae in solitudine, quae est in via Sur in deserto,',
        8: 'dixit ad illam: Agar ancilla Sarai, unde venis? et quo vadis? quae respondit: A facie Sarai dominae meae ego fugio.',
        9: 'Dixitque ei angelus Domini: Revertere ad dominam tuam, et humiliare sub manu illius.',
        10: 'Et rursum: Multiplicans, inquit, multiplicabo semen tuum, et non numerabitur prae multitudine.',
        11: 'Ac deinceps: Ecce, ait, concepisti, et paries filium: vocabisque nomen eius Ismael, eo quod audierit Dominus afflictionem tuam.',
        12: 'Hic erit ferus homo: manus eius contra omnes, et manus omnium contra eum: et e regione universorum fratrum suorum figet tabernacula.',
        13: 'Vocavit autem nomen Domini qui loquebatur ad eam: Tu Deus qui vidisti me. Dixit enim: Profecto hic vidi posteriora videntis me.',
        14: 'Propterea appellavit puteum illum, Puteum viventis et videntis me. Ipse est inter Cades et Barad.',
        15: 'Peperitque Agar Abrae filium: qui vocavit nomen eius Ismael.',
        16: 'Octoginta et sex annorum erat Abram quando peperit ei Agar Ismaelem.',
    },
    17: {
        1: 'Postquam vero nonaginta et novem annorum esse coeperat, apparuit ei Dominus: dixitque ad eum: Ego Deus omnipotens: ambula coram me, et esto perfectus.',
        2: 'Ponamque foedus meum inter me et te, et multiplicabo te vehementer nimis.',
        3: 'Cecidit Abram pronus in faciem.',
        4: 'Dixitque ei Deus: Ego sum, et pactum meum tecum, erisque pater multarum gentium.',
        5: 'Nec ultra vocabitur nomen tuum Abram: sed appellaberis Abraham: quia patrem multarum gentium constitui te.',
        6: 'Faciamque te crescere vehementissime, et ponam te in gentibus, regesque ex te egredientur.',
        7: 'Et statuam pactum meum inter me et te, et inter semen tuum post te in generationibus suis foedere sempiterno: ut sim Deus tuus, et seminis tui post te.',
        8: 'Daboque tibi et semini tuo terram peregrinationis tuae, omnem terram Chanaan in possessionem aeternam, eroque Deus eorum.',
        9: 'Dixit iterum Deus ad Abraham: Et tu ergo custodies pactum meum, et semen tuum post te in generationibus suis.',
        10: 'Hoc est pactum meum quod observabitis inter me et vos, et semen tuum post te: Circumcidetur ex vobis omne masculinum:',
        11: 'et circumcidetis carnem praeputii vestri, ut sit in signum foederis inter me et vos.',
        12: 'Infans octo dierum circumcidetur in vobis, omne masculinum in generationibus vestris: tam vernaculus, quam emptitius circumcidetur, et quicumque non fuerit de stirpe vestra:',
        13: 'eritque pactum meum in carne vestra in foedus aeternum.',
        14: 'Masculus, cuius praeputii caro circumcisa non fuerit, delebitur anima illa de populo suo: quia pactum meum irritum fecit.',
        15: 'Dixit quoque Deus ad Abraham: Sarai uxorem tuam non vocabis Sarai, sed Saram.',
        16: 'Et benedicam ei, et ex illa dabo tibi filium cui benedicturus sum, eritque in nationes, et reges populorum orientur ex eo.',
        17: 'Cecidit Abraham in faciem suam, et risit, dicens in corde suo: Putasne centenario nascetur filius? et Sara nonagenaria pariet?',
        18: 'Dixitque ad Deum: Utinam Ismael vivat coram te.',
        19: 'Et ait Deus ad Abraham: Sara uxor tua pariet tibi filium, vocabisque nomen eius Isaac, et constituam pactum meum illi in foedus sempiternum, et semini eius post eum.',
        20: 'Super Ismael quoque exaudivi te. ecce, benedicam ei, et augebo, et multiplicabo eum valde: duodecim duces generabit, et faciam illum in gentem magnam.',
        21: 'Pactum vero meum statuam ad Isaac, quem pariet tibi Sara tempore isto in anno altero.',
        22: 'Cumque finitus esset sermo loquentis cum eo, ascendit Deus ad Abraham.',
        23: 'Tulit autem Abraham Ismael filium suum, et omnes vernaculos domus suae, universosque quos emerat, cunctos mares ex omnibus viris domus suae: et circumcidit carnem praeputii eorum statim in ipsa die, sicut praeceperat ei Deus.',
        24: 'Abraham nonaginta et novem erat annorum quando circumcidit carnem praeputii sui.',
        25: 'Et Ismael filius suus tredecim annos impleverat tempore circumcisionis suae.',
        26: 'Eadem die circumcisus est Abraham et Ismael filius eius.',
        27: 'Et omnes viri domus illius, tam vernaculi, quam emptitii et alienigenae pariter circumcisi sunt.',
    },
    18: {
        1: 'Apparuit autem ei Dominus in convalle Mambre sedenti in ostio tabernaculi sui in ipso fervore diei.',
        2: 'Cumque elevasset oculos, apparuerunt ei tres viri stantes prope eum: quos cum vidisset, cucurrit in occursum eorum de ostio tabernaculi sui, et adoravit in terram.',
        3: 'Et dixit: Domine, si inveni gratiam in oculis tuis, ne transeas servum tuum:',
        4: 'sed afferam pauxillum aquae, et laventur pedes vestri, et requiescite sub arbore.',
        5: 'Ponamque buccellam panis, et confortetur cor vestrum, postea transibitis: idcirco enim declinastis ad servum vestrum. Qui dixerunt: Fac ut locutus es.',
        6: 'Festinavit Abraham in tabernaculum ad Saram, dixitque ei: Accelera, tria sata similae commisce, et fac subcinericios panes.',
        7: 'Ipse vero ad armentum cucurrit, et tulit inde vitulum tenerrimum et optimum, deditque puero: qui festinavit, et coxit illum.',
        8: 'Tulit quoque butyrum et lac, et vitulum quem coxerat, et posuit coram eis: ipse vero stabat iuxta eos sub arbore.',
        9: 'Cumque comedissent, dixerunt ad eum: Ubi est Sara uxor tua? ille respondit: Ecce in tabernaculo est.',
        10: 'Cui dixit: Revertens veniam ad te tempore isto, vita comite, et habebit filium Sara uxor tua. Quo audito, Sara risit post ostium tabernaculi.',
        11: 'Erant autem ambo senes, provectaeque aetatis, et desierant Sarae fieri muliebria.',
        12: 'Quae risit occulte dicens: Postquam consenui, et dominus meus vetulus est, voluptati operam dabo?',
        13: 'Dixit autem Dominus ad Abraham: Quare risit Sara, dicens: Num vere paritura sum anus?',
        14: 'Numquid Deo quidquam est difficile? iuxta condictum revertar ad te hoc eodem tempore, vita comite, et habebit Sara filium.',
        15: 'Negavit Sara, dicens: Non risi, timore perterrita. Dominus autem: Non est, inquit, ita: sed risisti.',
        16: 'Cum ergo surrexissent inde viri, direxerunt oculos contra Sodomam: et Abraham simul gradiebatur, deducens eos.',
        17: 'Dixitque Dominus: Num celare potero Abraham quae gesturus sum:',
        18: 'cum futurus sit in gentem magnam, ac robustissimam, et BENEDICENDAe sint in illo omnes nationes terrae?',
        19: 'Scio enim quod praecepturus sit filiis suis, et domui suae post se ut custodiant viam Domini, et faciant iudicium et iustitiam: ut adducat Dominus propter Abraham omnia quae locutus est ad eum.',
        20: 'Dixit itaque Dominus: Clamor Sodomorum et Gomorrhaeorum multiplicatus est, et peccatum eorum aggravatum est nimis.',
        21: 'Descendam, et videbo utrum clamorem qui venit ad me, opere compleverint: an non est ita, ut sciam.',
        22: 'Converteruntque se inde, et abierunt Sodomam: Abraham vero adhuc stabat coram Domino.',
        23: 'Et appropinquans ait: Numquid perdes iustum cum impio?',
        24: 'Si fuerint quinquaginta iusti in civitate, peribunt simul? et non parces loco illi propter quinquaginta iustos, si fuerint in eo?',
        25: 'Absit a te, ut rem hanc facias, et occidas iustum cum impio, fiatque iustus sicut impius, non est hoc tuum: qui iudicas omnem terram, nequaquam facies iudicium hoc.',
        26: 'Dixitque Dominus ad eum: Si invenero Sodomis quinquaginta iustos in medio civitatis, dimittam omni loco propter eos.',
        27: 'Respondensque Abraham, ait: Quia semel coepi, loquar ad Dominum meum, cum sim pulvis et cinis.',
        28: 'Quid si minus quinquaginta iustis quinque fuerint? delebis, quia quadraginta quinque, universam urbem? Et ait: Non delebo, si invenero ibi quadraginta quinque.',
        29: 'Rursumque locutus est ad eum: Sin autem quadraginta ibi inventi fuerint, quid facies? Ait: Non percutiam propter quadraginta.',
        30: 'Ne quaeso, inquit, indigneris Domine, si loquar: Quid si ibi inventi fuerint triginta? Respondit: Non faciam, si invenero ibi triginta.',
        31: 'Quia semel, ait, coepi loquar ad Dominum meum: Quid si ibi inventi fuerint viginti? Ait: Non interficiam propter viginti.',
        32: 'Obsecro, inquit, ne irascaris Domine, si loquar adhuc semel: Quid si inventi fuerint ibi decem? Et dixit: Non delebo propter decem.',
        33: 'Abiitque Dominus, postquam cessavit loqui ad Abraham: et ille reversus est in locum suum.',
    },
    19: {
        1: 'Veneruntque duo Angeli Sodomam vespere, et sedente Lot in foribus civitatis. Qui cum vidisset eos, surrexit, et ivit obviam eis: adoravitque pronus in terram,',
        2: 'et dixit: Obsecro, domini, declinate in domum pueri vestri, et manete ibi: lavate pedes vestros, et mane proficiscemini in viam vestram. Qui dixerunt: Minime, sed in platea manebimus.',
        3: 'Compulit illos oppido ut diverterent ad eum: ingressisque domum illius fecit convivium, et coxit azyma: et comederunt.',
        4: 'Prius autem quam irent cubitum, viri civitatis vallaverunt domum a puero usque ad senem, omnis populus simul.',
        5: 'Vocaveruntque Lot, et dixerunt ei: Ubi sunt viri qui introierunt ad te nocte? educ illos huc, ut cognoscamus eos.',
        6: 'Egressus ad eos Lot, post tergum occludens ostium, ait:',
        7: 'Nolite, quaeso, fratres mei, nolite malum hoc facere.',
        8: 'Habeo duas filias, quae necdum cognoverunt virum: educam eas ad vos, et abutimini eis sicut vobis placuerit, dummodo viris istis nihil mali faciatis, quia ingressi sunt sub umbra culminis mei.',
        9: 'At illi dixerunt: Recede illuc. Et rursus: Ingressus es, inquiunt, ut advena; numquid ut iudices? te ergo ipsum magis quam hos affligemus. Vimque faciebant Lot vehementissime: iamque prope erat ut effringerent fores.',
        10: 'Et ecce miserunt manum viri, et introduxerunt ad se Lot, clauseruntque ostium:',
        11: 'et eos, qui foris erant, percusserunt caecitate a minimo usque ad maximum, ita ut ostium invenire non possent.',
        12: 'Dixerunt autem ad Lot: Habes hic quempiam tuorum? generum, aut filios, aut filias, omnes, qui tui sunt, educ de urbe hac:',
        13: 'delebimus enim locum istum, eo quod increverit clamor eorum coram Domino, qui misit nos ut perdamus illos.',
        14: 'Egressus itaque Lot, locutus est ad generos suos qui accepturi erant filias eius, et dixit: Surgite, et egredimini de loco isto: quia delebit Dominus civitatem hanc. Et visus est eis quasi ludens loqui.',
        15: 'Cumque esset mane, cogebant eum Angeli, dicentes: Surge, tolle uxorem tuam, et duas filias quas habes: ne et tu pariter pereas in scelere civitatis.',
        16: 'Dissimulante illo, apprehenderunt manum eius, et manum uxoris, ac duarum filiarum eius, eo quod parceret Dominus illi.',
        17: 'Eduxeruntque eum, et posuerunt extra civitatem: ibique locuti sunt ad eum, dicentes: Salva animam tuam: noli respicere post tergum, nec stes in omni circa regione: sed in monte salvum te fac, ne et tu simul pereas.',
        18: 'Dixitque Lot ad eos: Quaeso Domine mi,',
        19: 'quia invenit servus tuus gratiam coram te, et magnificasti misericordiam tuam quam fecisti mecum, ut salvares animam meam, nec possum in monte salvari, ne forte apprehendat me malum, et moriar:',
        20: 'Est civitas haec iuxta, ad quam possum fugere, parva, et salvabor in ea: numquid non modica est, et vivet anima mea?',
        21: 'Dixitque ad eum: Ecce etiam in hoc suscepi preces tuas, ut non subvertam urbem pro qua locutus es.',
        22: 'Festina, et salvare ibi: quia non potero facere quidquam donec ingrediaris illuc. Idcirco vocatum est nomen urbis illius Segor.',
        23: 'Sol egressus est super terram, et Lot ingressus est Segor.',
        24: 'Igitur Dominus pluit super Sodomam et Gomorrham sulphur et ignem a Domino de caelo:',
        25: 'et subvertit civitates has, et omnem circa regionem, universos habitatores urbium, et cuncta terrae virentia.',
        26: 'Respiciensque uxor eius post se, versa est in statuam salis.',
        27: 'Abraham autem consurgens mane, ubi steterat prius cum Domino,',
        28: 'intuitus est Sodomam et Gomorrham, et universam terram regionis illius: viditque ascendentem favillam de terra quasi fornacis fumum.',
        29: 'Cum autem subverteret Deus civitates regionis illius, recordatus Abrahae, liberavit Lot de subversione urbium in quibus habitaverat.',
        30: 'Ascenditque Lot de Segor, et mansit in monte, duae quoque filiae eius cum eo (timuerat enim manere in Segor) et mansit in spelunca ipse, et duae filiae eius cum eo.',
        31: 'Dixitque maior ad minorem: Pater noster senex est, et nullus virorum remansit in terra qui possit ingredi ad nos iuxta morem universae terrae.',
        32: 'Veni, inebriemus eum vino, dormiamusque cum eo, ut servare possimus ex patre nostro semen.',
        33: 'Dederunt itaque patri suo bibere vinum nocte illa: Et ingressa est maior, dormivitque cum patre: at ille non sensit, nec quando accubuit filia, nec quando surrexit.',
        34: 'Altera quoque die dixit maior ad minorem: Ecce dormivi heri cum patre meo, demus ei bibere vinum etiam hac nocte, et dormies cum eo, ut salvemus semen de patre nostro.',
        35: 'Dederunt etiam et illa nocte patri suo bibere vinum, ingressaque minor filia, dormivit cum eo: et ne tunc quidem sensit quando concubuerit, vel quando illa surrexerit.',
        36: 'Conceperunt ergo duae filiae Lot de patre suo.',
        37: 'Peperitque maior filium, et vocavit nomen eius Moab: ipse est pater Moabitarum usque in praesentem diem.',
        38: 'Minor quoque peperit filium, et vocavit nomen eius Ammon, idest filius populi mei: ipse est pater Ammonitarum usque hodie.',
    },
    20: {
        1: 'Profectus inde Abraham in terram australem, habitavit inter Cades, et Sur: et peregrinatus est in Geraris.',
        2: 'Dixitque de Sara uxore suo, Soror mea est. Misit ergo Abimelech rex Gerarae, et tulit eam.',
        3: 'Venit autem Deus ad Abimelech per somnium nocte, et ait illi: En morieris propter mulierem, quam tulisti: habet enim virum.',
        4: 'Abimelech vero non tetigerat eam, et ait: Domine, num gentem ignorantem et iustam interficies?',
        5: 'Nonne ipse dixit mihi: Soror mea est: et ipsa ait: Frater meus est? in simplicitate cordis mei, et munditia manuum mearum feci hoc.',
        6: 'Dixitque ad eum Deus: Et ego scio quod simplici corde feceris: et ideo custodivi te ne peccares in me, et non dimisi ut tangeres eam.',
        7: 'Nunc ergo redde viro suo uxorem, et orabit pro te; quia propheta est, et vives: si autem nolueris reddere, scito quod morte morieris tu, et omnia quae tua sunt.',
        8: 'Statimque de nocte consurgens Abimelech, vocavit omnes servos suos: et locutus est universa verba haec in auribus eorum, timueruntque omnes viri valde.',
        9: 'Vocavit autem Abimelech etiam Abraham, et dixit ei: Quid fecisti nobis? quid peccavimus in te, quia induxisti super me et super regnum meum peccatum grande? quae non debuisti facere, fecisti nobis.',
        10: 'Rursumque expostulans, ait: Quid vidisti, ut hoc faceres?',
        11: 'Respondit Abraham: Cogitavi mecum, dicens: Forsitan non est timor Dei in loco isto: et interficient me propter uxorem meam:',
        12: 'alias autem et vere soror mea est, filia patris mei, et non filia matris meae, et duxi eam in uxorem.',
        13: 'Postquam autem eduxit me Deus de domo patris mei, dixi ad eam: Hanc misericordiam facies mecum: In omni loco, ad quem ingrediemur, dices quod frater tuus sim.',
        14: 'Tulit igitur Abimelech oves et boves, et servos et ancillas, et dedit Abraham: reddiditque illi Saram uxorem suam,',
        15: 'et ait: Terra coram vobis est, ubicumque tibi placuerit habita.',
        16: 'Sarae autem dixit: Ecce mille argenteos dedi fratri tuo, hoc erit tibi in velamen oculorum ad omnes qui tecum sunt, et quocumque perrexeris: memento te deprehensam.',
        17: 'Orante autem Abraham, sanavit Deus Abimelech et uxorem, ancillasque eius, et pepererunt:',
        18: 'concluserat enim Dominus omnem vulvam domus Abimelech propter Saram uxorem Abrahae.',
    },
    21: {
        1: 'Visitavit autem Dominus Saram, sicut promiserat: et implevit quae locutus est.',
        2: 'Concepitque et peperit filium in senectute sua, tempore quo praedixerat ei Deus.',
        3: 'Vocavitque Abraham nomen filii sui, quem genuit ei Sara, Isaac:',
        4: 'et circumcidit eum octavo die, sicut praeceperat ei Deus,',
        5: 'cum centum esset annorum: hac quippe aetate patris, natus est Isaac.',
        6: 'Dixitque Sara: Risum fecit mihi Deus: quicumque audierit, corridebit mihi.',
        7: 'Rursumque ait: Quis auditurus crederet Abraham quod Sara lactaret filium, quem peperit ei iam seni?',
        8: 'Crevit igitur puer, et ablactatus est: fecitque Abraham grande convivium in die ablactationis eius.',
        9: 'Cumque vidisset Sara filium Agar Aegyptiae ludentem cum Isaac filio suo, dixit ad Abraham:',
        10: 'Eiice ancillam hanc, et filium eius: non enim erit heres filius ancillae cum filio meo Isaac.',
        11: 'Dure accepit hoc Abraham pro filio suo.',
        12: 'Cui dixit Deus: Non tibi videatur asperum super puero, et super ancilla tua: omnia quae dixerit tibi Sara, audi vocem eius: quia in Isaac vocabitur tibi semen.',
        13: 'Sed et filium ancillae faciam in gentem magnam, quia semen tuum est.',
        14: 'Surrexit itaque Abraham mane, et tollens panem et utrem aquae, imposuit scapulae eius, tradiditque puerum, et dimisit eam. Quae cum abiisset, errabat in solitudine Bersabee.',
        15: 'Cumque consumpta esset aqua in utre, abiecit puerum subter unam arborem, quae ibi erat.',
        16: 'Et abiit, seditque e regione procul quantum potest arcus iacere. dixit enim: Non videbo morientem puerum: et sedens contra, levavit vocem suam et flevit.',
        17: 'Exaudivit autem Deus vocem pueri: vocavitque Angelus Dei Agar de caelo, dicens: Quid agis Agar? noli timere: exaudivit enim Deus vocem pueri de loco in quo est.',
        18: 'Surge, tolle puerum, et tene manum illius: quia in gentem magnam faciam eum.',
        19: 'Aperuitque oculos eius Deus: quae videns puteum aquae, abiit, et implevit utrem, deditque puero bibere.',
        20: 'Et fuit cum eo: qui crevit, et moratus est in solitudine, factusque est iuvenis sagittarius.',
        21: 'Habitavitque in deserto Pharan, et accepit illi mater sua uxorem de terra Aegypti.',
        22: 'Eodem tempore dixit Abimelech, et Phicol princeps exercitus eius ad Abraham: Deus tecum est in universis quae agis.',
        23: 'Iura ergo per Deum, ne noceas mihi, et posteris meis, stirpique meae: sed iuxta misericordiam, quam feci tibi, facies mihi, et terrae in qua versatus es advena.',
        24: 'Dixitque Abraham: Ego iurabo.',
        25: 'Et increpavit Abimelech propter puteum aquae quem vi abstulerunt servi eius.',
        26: 'Responditque Abimelech: Nescivi quis fecerit hanc rem: sed et tu non indicasti mihi, et ego non audivi praeter hodie.',
        27: 'Tulit itaque Abraham oves et boves, et dedit Abimelech: percusseruntque ambo foedus.',
        28: 'Et statuit Abraham septem agnas gregis seorsum.',
        29: 'Cui dixit Abimelech: Quid sibi volunt septem agnae istae, quas stare fecisti seorsum?',
        30: 'At ille: Septem, inquit, agnas accipies de manu mea: ut sint mihi in testimonium, quoniam ego fodi puteum istum.',
        31: 'Idcirco vocatus est locus ille Bersabee: quia ibi uterque iuravit.',
        32: 'Et inierunt foedus pro puteo iuramenti.',
        33: 'Surrexit autem Abimelech, et Phicol princeps exercitus eius, reversique sunt in terram Palaestinorum. Abraham vero plantavit nemus in Bersabee, et invocavit ibi nomen Domini Dei aeterni.',
        34: 'Et fuit colonus terrae Palaestinorum diebus multis.',
    },
    22: {
        1: 'Quae postquam gesta sunt, tentavit Deus Abraham, et dixit ad eum: Abraham, Abraham. At ille respondit: Adsum.',
        2: 'Ait illi: Tolle filium tuum unigenitum, quem diligis, Isaac, et vade in terram visionis: atque ibi offeres eum in holocaustum super unum montium quem monstravero tibi.',
        3: 'Igitur Abraham de nocte consurgens, stravit asinum suum: ducens secum duos iuvenes, et Isaac filium suum: cumque concidisset ligna in holocaustum, abiit ad locum quem praeceperat ei Deus.',
        4: 'Die autem tertio, elevatis oculis, vidit locum procul:',
        5: 'dixitque ad pueros suos: Expectate hic cum asino: ego autem et puer illuc usque properantes, postquam adoraverimus, revertemur ad vos.',
        6: 'Tulit quoque ligna holocausti, et imposuit super Isaac filium suum: ipse vero portabat in manibus ignem et gladium. Cumque duo pergerent simul,',
        7: 'dixit Isaac patri suo: Pater mi. At ille respondit: Quid vis fili? Ecce, inquit, ignis et ligna: ubi est victima holocausti?',
        8: 'Dixit autem Abraham: Deus providebit sibi victimam holocausti, fili mi. Pergebant ergo pariter:',
        9: 'et venerunt ad locum quem ostenderat ei Deus, in quo aedificavit altare, et desuper ligna composuit: cumque alligasset Isaac filium suum, posuit eum in altare super struem lignorum.',
        10: 'Extenditque manum, et arripuit gladium, ut immolaret filium suum.',
        11: 'Et ecce Angelus Domini de caelo clamavit, dicens: Abraham, Abraham. Qui respondit: Adsum.',
        12: 'Dixitque ei: Non extendas manum tuam super puerum, neque facias illi quidquam: nunc cognovi quod timeas Dominum, et non pepercisti unigenito filio tuo propter me.',
        13: 'Levavit Abraham oculos suos, viditque post tergum arietem inter vepres haerentem cornibus, quem assumens obtulit holocaustum pro filio.',
        14: 'Appellavitque nomen loci illius, Dominus videt. Unde usque hodie dicitur: In monte Dominus videbit.',
        15: 'Vocavit autem Angelus Domini Abraham secundo de caelo, dicens:',
        16: 'Per memetipsum iuravi, dicit Dominus: quia fecisti hanc rem, et non pepercisti filio tuo unigenito propter me:',
        17: 'benedicam tibi, et multiplicabo semen tuum sicut stellas caeli, et velut arenam quae est in littore maris: possidebit semen tuum portas inimicorum suorum,',
        18: 'et BENEDICENTUR in semine tuo omnes gentes terrae, quia obedisti voci meae.',
        19: 'Reversus est Abraham ad pueros suos, abieruntque Bersabee simul, et habitavit ibi.',
        20: 'His itaque gestis, nunciatum est Abrahae quod Melcha quoque genuisset filios Nachor fratri suo,',
        21: 'Hus primogenitum, et Buz fratrem eius, et Camuel patrem Syrorum,',
        22: 'et Cased, et Azau, Pheldas quoque et Iedlaph,',
        23: 'ac Bathuel, de quo nata est Rebecca: octo istos genuit Melcha, Nachor fratri Abrahae.',
        24: 'Concubina vero illius, nomine Roma, peperit Tabee, et Gaham, et Thahas, et Maacha.',
    },
    23: {
        1: 'Vixit autem Sara centum vigintiseptem annis.',
        2: 'Et mortua est in civitate Arbee, quae est Hebron, in terra Chanaan: venitque Abraham ut plangeret, et fleret eam.',
        3: 'Cumque surrexisset ab officio funeris, locutus est ad filios Heth, dicens:',
        4: 'Advena sum et peregrinus apud vos: date mihi ius sepulchri vobiscum, ut sepeliam mortuum meum.',
        5: 'Responderunt filii Heth, dicentes:',
        6: 'Audi nos domine, princeps Dei es apud nos: in electis sepulchris nostris sepeli mortuum tuum: nullusque te prohibere poterit quin in monumento eius sepelias mortuum tuum.',
        7: 'Surrexit Abraham, et adoravit populum terrae, filios videlicet Heth:',
        8: 'dixitque ad eos: Si placet animae vestrae ut sepeliam mortuum meum, audite me, et intercedite pro me apud Ephron filium Seor:',
        9: 'ut det mihi speluncam duplicem, quam habet in extrema parte agri sui: pecunia digna tradat eam mihi coram vobis in possessionem sepulchri.',
        10: 'Habitabat autem Ephron in medio filiorum Heth. Responditque Ephron ad Abraham cunctis audientibus qui ingrediebantur portam civitatis illius, dicens:',
        11: 'Nequaquam ita fiat, domine mi, sed tu magis ausculta quod loquor: Agrum trado tibi, et speluncam, quae in eo est, praesentibus filiis populi mei, sepeli mortuum tuum.',
        12: 'Adoravit Abraham coram populo terrae.',
        13: 'Et locutus est ad Ephron circumstante plebe eius: Quaeso, ut audias me: Dabo pecuniam pro agro: suscipe eam, et sic sepeliam mortuum meum in agro.',
        14: 'Responditque Ephron:',
        15: 'Domine mi, audi me: Terra, quam postulas, quadringentos siclos argenti valet: istud est pretium inter me et te: sed quantum est hoc? sepeli mortuum tuum.',
        16: 'Quod cum audisset Abraham, appendit pecuniam, quam Ephron postulaverat, audientibus filiis Heth, quadringentos siclos argenti probatae monetae publicae.',
        17: 'Confirmatusque est ager quondam Ephronis, in quo erat spelunca duplex, respiciens Mambre, tam ipse, quam spelunca, et omnes arbores eius in cunctis terminis eius per circuitum,',
        18: 'Abrahae in possessionem, videntibus filiis Heth, et cunctis qui intrabant portam civitatis illius.',
        19: 'Atque ita sepelivit Abraham Saram uxorem suam in spelunca agri duplici, quae respiciebat Mambre. Haec est Hebron in terra Chanaan.',
        20: 'Et confirmatus est ager, et antrum, quod erat in eo, Abrahae in possessionem monumenti a filiis Heth.',
    },
    24: {
        1: 'Erat autem Abraham senex, dierumque multorum: et Dominus in cunctis benedixerat ei.',
        2: 'Dixitque ad servum seniorem domus suae, qui praeerat omnibus quae habebat: Pone manum tuam subter femur meum,',
        3: 'ut adiurem te per Dominum, Deum caeli et terrae, ut non accipias uxorem filio meo de filiabus Chananaeorum, inter quos habito:',
        4: 'sed ad terram et cognationem meam proficiscaris, et inde accipias uxorem filio meo Isaac.',
        5: 'Respondit servus: Si noluerit mulier venire mecum in terram hanc, numquid reducere debeo filium tuum ad locum, de quo egressus es?',
        6: 'Dixitque Abraham: Cave nequando reducas filium meum illuc.',
        7: 'Dominus Deus caeli, qui tulit me de domo patris mei, et de terra nativitatis meae, qui locutus est mihi, et iuravit mihi, dicens: Semini tuo dabo terram hanc: ipse mittet Angelum suum coram te, et accipies inde uxorem filio meo:',
        8: 'sin autem mulier noluerit sequi te, non teneberis iuramento: filium meum tantum ne reducas illuc.',
        9: 'Posuit ergo servus manum sub femore Abraham domini sui, et iuravit illi super sermone hoc.',
        10: 'Tulitque decem camelos de grege domini sui, et abiit, ex omnibus bonis eius portans secum, profectusque perrexit in Mesopotamiam ad urbem Nachor.',
        11: 'Cumque camelos fecisset accumbere extra oppidum iuxta puteum aquae vespere, tempore quo solent mulieres egredi ad hauriendam aquam, dixit:',
        12: 'Domine Deus domini mei Abraham, occurre, obsecro, mihi hodie, et fac misericordiam cum domino meo Abraham.',
        13: 'Ecce ego sto prope fontem aquae, et filiae habitatorum huius civitatis egredientur ad hauriendam aquam.',
        14: 'Igitur puella, cui ego dixero: Inclina hydriam tuam ut bibam: et illa responderit, Bibe, quin et camelis tuis dabo potum: ipsa est, quam praeparasti servo tuo Isaac: et per hoc intelligam quod feceris misericordiam cum domino meo.',
        15: 'Necdum intra se verba compleverat, et ecce Rebecca egrediebatur, filia Bathuel, filii Melchae uxoris Nachor fratris Abraham, habens hydriam in scapula sua:',
        16: 'puella decora nimis, virgoque pulcherrima, et incognita viro: descenderat autem ad fontem, et impleverat hydriam, ac revertebatur.',
        17: 'Occurritque ei servus, et ait: Pauxillum aquae mihi ad bibendum praebe de hydria tua.',
        18: 'Quae respondit: Bibe domine mi. celeriterque deposuit hydriam super ulnam suam, et dedit ei potum.',
        19: 'Cumque ille bibisset, adiecit: Quin et camelis tuis hauriam aquam, donec cuncti bibant.',
        20: 'Effundensque hydriam in canalibus, recurrit ad puteum ut hauriret aquam: et haustam omnibus camelis dedit.',
        21: 'Ipse autem contemplabatur eam tacitus, scire volens utrum prosperum iter suum fecisset Deus, an non.',
        22: 'Postquam autem biberunt cameli, protulit vir inaures aureas, appendentes siclos duos, et armillas totidem pondo siclorum decem.',
        23: 'Dixitque ad eam: Cuius es filia? indica mihi: est in domo patris tui locus ad manendum?',
        24: 'Quae respondit: Filia sum Bathuelis, filii Nachor, quem peperit ei Melcha..',
        25: 'Et addidit, dicens: Palearum quoque et foeni plurimum est apud nos, et locus spatiosus ad manendum.',
        26: 'Inclinavit se homo, et adoravit Dominum,',
        27: 'dicens: Benedictus Dominus Deus domini mei Abraham, qui non abstulit misericordiam et veritatem suam a domino meo, et recto itinere me perduxit in domum fratris domini mei.',
        28: 'Cucurrit itaque puella, et nunciavit in domum matris suae omnia quae audierat.',
        29: 'Habebat autem Rebecca fratrem nomine Laban, qui festinus egressus est ad hominem, ubi erat fons.',
        30: 'Cumque vidisset inaures et armillas in manibus sororis suae, et audisset cuncta verba referentis: Haec locutus est mihi homo: venit ad virum, qui stabat iuxta camelos, et prope fontem aquae:',
        31: 'dixitque ad eum: Ingredere, benedicte Domini: cur foris stas? praeparavi domum, et locum camelis.',
        32: 'Et introduxit eum in hospitium: ac destravit camelos, deditque paleas et foenum, et aquam ad lavandos pedes eius, et virorum qui venerant cum eo.',
        33: 'Et appositus est in conspectu eius panis. Qui ait: Non comedam, donec loquar sermones meos. Respondit ei: Loquere.',
        34: 'At ille: Servus, inquit, Abraham sum:',
        35: 'et Dominus benedixit domino meo valde, magnificatusque est: et dedit ei oves et boves, argentum et aurum, servos et ancillas, camelos et asinos.',
        36: 'Et peperit Sara uxor domini mei filium domino meo in senectute sua, deditque illi omnia quae habuerat.',
        37: 'Et adiuravit me dominus meus, dicens: Non accipies uxorem filio meo de filiabus Chananaeorum, in quorum terra habito:',
        38: 'sed ad domum patris mei perges, et de cognatione mea accipies uxorem filio meo:',
        39: 'ego vero respondi domino meo: Quid si noluerit venire mecum mulier?',
        40: 'Dominus, ait, in cuius conspectu ambulo, mittet angelum suum tecum, et diriget viam tuam: accipiesque uxorem filio meo de cognatione mea, et de domo patris mei.',
        41: 'Innocens eris a maledictione mea, cum veneris ad propinquos meos, et non dederit tibi.',
        42: 'Veni ergo hodie ad fontem aquae, et dixi: Domine Deus domini mei Abraham, si direxisti viam meam, in qua nunc ambulo,',
        43: 'ecce sto iuxta fontem aquae, et virgo, quae egredietur ad hauriendam aquam, audierit a me: Da mihi pauxillum aquae ad bibendum de hydria tua:',
        44: 'et dixerit mihi: Et tu bibe, et camelis tuis hauriam: ipsa est mulier quam praeparavit Dominus filio domini mei.',
        45: 'Dumque haec tacitus mecum volverem, apparuit Rebecca veniens cum hydria, quam portabat in scapula: descenditque ad fontem, et hausit aquam. Et aio ad eam: Da mihi paululum bibere.',
        46: 'Quae festinans deposuit hydriam de humero, et dixit mihi: Et tu bibe, et camelis tuis tribuam potum. Bibi, et adaquavit camelos.',
        47: 'Interrogavique eam, et dixi: Cuius es filia? Quae respondit: Filia Bathuelis sum, filii Nachor, quem peperit ei Melcha. Suspendi itaque inaures ad ornandam faciem eius, et armillas posui in manibus eius.',
        48: 'Pronusque adoravi Dominum, benedicens Domino Deo domini mei Abraham, qui perduxit me recto itinere, ut sumerem filiam fratris domini mei filio eius.',
        49: 'Quamobrem si facitis misericordiam et veritatem cum domino meo, indicate mihi: sin autem aliud placet, et hoc dicite mihi, ut vadam ad dextram, sive ad sinistram.',
        50: 'Responderuntque Laban et Bathuel: A Domino egressus est sermo: non possumus extra placitum eius quidquam aliud loqui tecum.',
        51: 'En Rebecca coram te est, tolle eam, et proficiscere, et sit uxor filii domini tui, sicut locutus est Dominus.',
        52: 'Quod cum audisset puer Abraham, procidens adoravit in terra Dominum.',
        53: 'Prolatisque vasis argenteis, et aureis, ac vestibus, dedit ea Rebeccae pro munere: fratribus quoque eius, et matri dona obtulit.',
        54: 'Inito convivio, vescentes pariter et bibentes manserunt ibi. Surgens autem mane, locutus est puer: Dimitte me, ut vadam ad dominum meum.',
        55: 'Responderuntque fratres eius, et mater: Maneat puella saltem decem dies apud nos, et postea proficiscetur.',
        56: 'Nolite, ait, me retinere, quia Dominus direxit viam meam: dimittite me ut pergam ad dominum meum.',
        57: 'Et dixerunt: Vocemus puellam, et quaeramus ipsius voluntatem.',
        58: 'Cumque vocata venisset, sciscitati sunt: Vis ire cum homine isto? Quae ait: Vadam.',
        59: 'Dimiserunt ergo eam, et nutricem illius, servumque Abraham, et comites eius,',
        60: 'imprecantes prospera sorori suae, atque dicentes: Soror nostra es, crescas in mille millia, et possideat semen tuum portas inimicorum suorum.',
        61: 'Igitur Rebecca, et puellae illius, ascensis camelis, secutae sunt virum: qui festinus revertebatur ad dominum suum:',
        62: 'eo autem tempore deambulabat Isaac per viam quae ducit ad Puteum, cuius nomen est Viventis, et videntis: habitabat enim in terra australi:',
        63: 'et egressus fuerat ad meditandum in agro, inclinata iam die: cumque elevasset oculos, vidit camelos venientes procul.',
        64: 'Rebecca quoque, conspecto Isaac, descendit de camelo,',
        65: 'et ait ad puerum: Quis est ille homo qui venit per agrum in occursum nobis? Dixitque ei: Ipse est dominus meus. At illa tollens cito pallium suum, operuit se.',
        66: 'Servus autem cuncta, quae gesserat, narravit domino suo Isaac.',
        67: 'Qui introduxit eam in tabernaculum Sarae matris suae, et accepit eam uxorem: et in tantum dilexit eam, ut dolorem, qui ex morte matris eius acciderat, temperaret.',
    },
    25: {
        1: 'Abraham vero aliam duxit uxorem nomine Ceturam:',
        2: 'quae peperit ei Zamran et Iecsan, et Madan, et Madian, et Iesboc, et Sue.',
        3: 'Iecsan quoque genuit Saba, et Dadan. Filii Dadan fuerunt Assurim, et Latusim, et Loomin.',
        4: 'At vero ex Madian ortus est Epha, et Opher, et Henoch, et Abida, et Eldaa: omnes hi filii Ceturae.',
        5: 'Deditque Abraham cuncta quae possederat, Isaac:',
        6: 'filiis autem concubinarum largitus est munera, et separavit eos ab Isaac filio suo, dum adhuc ipse viveret, ad plagam orientalem.',
        7: 'Fuerunt autem dies vitae Abrahae, centum septuaginta quinque anni.',
        8: 'Et deficiens mortuus est in senectute bona, provectaeque aetatis, et plenus dierum: congregatusque est ad populum suum.',
        9: 'Et sepelierunt eum Isaac et Ismael filii sui in spelunca duplici, quae sita est in agro Ephron filii Seor Hethaei, e regione Mambre,',
        10: 'quam emerat a filiis Heth: ibi sepultus est ipse, et Sara uxor eius.',
        11: 'Et post obitum illius benedixit Deus Isaac filio eius, qui habitabat iuxta puteum nomine Viventis et videntis.',
        12: 'Hae sunt generationes Ismael filii Abrahae, quem peperit ei Agar Aegyptia, famula Sarae: et',
        13: 'haec nomina filiorum eius in vocabulis et generationibus suis. Primogenitus Ismaelis Nabaioth, deinde Cedar, et Adbeel, et Mabsam,',
        14: 'Masma quoque, et Duma, et Massa,',
        15: 'Hadar, et Thema, et Itur, et Naphis, et Cedma.',
        16: 'Isti sunt filii Ismaelis: et haec nomina per castella et oppida eorum, duodecim principes tribuum suarum.',
        17: 'Et facti sunt anni vitae Ismaelis centum triginta septem, deficiensque mortuus est, et appositus ad populum suum.',
        18: 'Habitavit autem ab Hevila usque Sur, quae respicit Aegyptum introeuntibus Assyrios. coram cunctis fratribus suis obiit.',
        19: 'Hae quoque sunt generationes Isaac filii Abraham: Abraham genuit Isaac:',
        20: 'qui cum quadraginta esset annorum, duxit uxorem Rebeccam filiam Bathuelis Syri de Mesopotamia, sororem Laban.',
        21: 'Deprecatusque est Isaac Dominum pro uxore sua, eo quod esset sterilis: qui exaudivit eum, et dedit conceptum Rebeccae.',
        22: 'Sed collidebantur in utero eius parvuli; quae ait: Si sic mihi futurum erat, quid necesse fuit concipere? Perrexitque ut consuleret Dominum.',
        23: 'Qui respondens, ait: Duae gentes sunt in utero tuo, et duo populi ex ventre tuo dividentur, populusque populum superabit, et maior serviet minori.',
        24: 'Iam tempus pariendi advenerat, et ecce gemini in utero eius reperti sunt.',
        25: 'Qui prior egressus est, rufus erat, et totus in morem pellis hispidus: vocatumque est nomen eius Esau. Protinus alter egrediens, plantam fratris tenebat manu: et idcirco appellavit eum Iacob.',
        26: 'Sexagenarius erat Isaac quando nati sunt ei parvuli.',
        27: 'Quibus adultis, factus est Esau vir gnarus venandi, et homo agricola: Iacob autem vir simplex habitabat in tabernaculis.',
        28: 'Isaac amabat Esau, eo quod de venationibus illius vesceretur: et Rebecca diligebat Iacob.',
        29: 'Coxit autem Iacob pulmentum: ad quem cum venisset Esau de agro lassus,',
        30: 'ait: Da mihi de coctione hac rufa, quia oppido lassus sum. Quam ob causam vocatum est nomen eius Edom.',
        31: 'Cui dixit Iacob: Vende mihi primogenita tua.',
        32: 'Ille respondit: En morior, quid mihi proderunt primogenita?',
        33: 'Ait Iacob: Iura ergo mihi. Iuravit ei Esau, et vendidit primogenita.',
        34: 'Et sic accepto pane et lentis edulio, comedit, et bibit, et abiit; parvipendens quod primogenita vendidisset.',
    },
    26: {
        1: 'Orta autem fame super terram post eam sterilitatem, quae acciderat in diebus Abraham, abiit Isaac ad Abimelech regem Palaestinorum in Gerara.',
        2: 'Apparuitque ei Dominus, et ait: Ne descendas in Aegyptum, sed quiesce in terra, quam dixero tibi.',
        3: 'Et peregrinare in ea, eroque tecum, et benedicam tibi: tibi enim et semini tuo dabo universas regiones has, complens iuramentum quod spopondi Abraham patri tuo.',
        4: 'Et multiplicabo semen tuum sicut stellas caeli: daboque posteris tuis universas regiones has: et BENEDICENTUR in semine tuo omnes gentes terrae,',
        5: 'eo quod obedierit Abraham voci meae, et custodierit praecepta et mandata mea, et ceremonias legesque servaverit.',
        6: 'Mansit itaque Isaac in Geraris.',
        7: 'Qui cum interrogaretur a viris loci illius super uxore sua, respondit: Soror mea est. timuerat enim confiteri quod sibi esset sociata coniugio, reputans ne forte interficerent eum propter illius pulchritudinem.',
        8: 'Cumque pertransissent dies plurimi, et ibidem moraretur, prospiciens Abimelech rex Palaestinorum per fenestram, vidit eum iocantem cum Rebecca uxore sua.',
        9: 'Et accersito eo, ait: Perspicuum est quod uxor tua sit: cur mentitus es eam sororem tuam esse? Respondit: Timui ne morerer propter eam.',
        10: 'Dixitque Abimelech: Quare imposuisti nobis? potuit coire quispiam de populo cum uxore tua, et induxeras super nos grande peccatum. Praecepitque omni populo, dicens:',
        11: 'Qui tetigerit hominis huius uxorem, morte morietur.',
        12: 'Sevit autem Isaac in terra illa, et invenit in ipso anno centuplum: benedixitque ei Dominus.',
        13: 'Et locupletatus est homo, et ibat proficiens atque succrescens, donec magnus vehementer effectus est:',
        14: 'habuitque possessiones ovium et armentorum, et familiae plurimum. Ob hoc invidentes ei Palaestini,',
        15: 'omnes puteos, quos foderant servi patris illius Abraham, illo tempore obstruxerunt, implentes humo:',
        16: 'in tantum, ut ipse Abimelech diceret ad Isaac: Recede a nobis, quoniam potentior nobis factus es valde.',
        17: 'Et ille discedens, ut veniret ad torrentem Gerarae, habitaretque ibi:',
        18: 'rursum fodit alios puteos, quos foderant servi patris sui Abraham, et quos, illo mortuo, olim obstruxerant Philisthiim: appellavitque eos eisdem nominibus quibus ante pater vocaverat.',
        19: 'Foderuntque in Torrente, et repererunt aquam vivam.',
        20: 'Sed et ibi iurgium fuit pastorum Gerarae adversus pastores Isaac, dicentium: Nostra est aqua. quam ob rem nomen putei ex eo, quod acciderat, vocavit Calumniam.',
        21: 'Foderunt autem et alium: et pro illo quoque rixati sunt, appellavitque eum, Inimicitias.',
        22: 'Profectus inde fodit alium puteum, pro quo non contenderunt: itaque vocavit nomen eius, Latitudo, dicens: Nunc dilatavit nos Dominus, et fecit crescere super terram.',
        23: 'Ascendit autem ex illo loco in Bersabee,',
        24: 'ubi apparuit ei Dominus in ipsa nocte, dicens: Ego sum Deus Abraham patris tui, noli timere, quia ego tecum sum: benedicam tibi, et multiplicabo semen tuum propter servum meum Abraham.',
        25: 'Itaque aedificavit ibi altare: et invocato nomine Domini, extendit tabernaculum: praecepitque servis suis ut foderent puteum.',
        26: 'Ad quem locum cum venissent de Geraris Abimelech, et Ochozath amicus illius, et Phicol dux militum,',
        27: 'locutus est eis Isaac: Quid venistis ad me hominem quem odistis, et expulistis a vobis?',
        28: 'Qui responderunt: Vidimus tecum esse Dominum, et idcirco nos diximus: Sit iuramentum inter nos, et ineamus foedus,',
        29: 'ut non facias nobis quidquam mali, sicut et nos nihil tuorum attigimus, nec fecimus quod te laederet: sed cum pace dimisimus auctum benedictione Domini.',
        30: 'Fecit ergo eis convivium, et post cibum et potum',
        31: 'surgentes mane, iuraverunt sibi mutuo: dimisitque eos Isaac pacifice in locum suum.',
        32: 'Ecce autem venerunt in ipso die servi Isaac annunciantes ei de puteo, quem foderant, atque dicentes: Invenimus aquam.',
        33: 'Unde appellavit eum, Abundantiam: et nomen urbi impositum est Bersabee, usque in praesentem diem.',
        34: 'Esau vero quadragenarius duxit uxores duas, Iudith filiam Beeri Hethaei, et Basemath filiam Elon eiusdem loci:',
        35: 'quae ambae offenderant animum Isaac et Rebeccae.',
    },
    27: {
        1: 'Senuit autem Isaac, et caligaverunt oculi eius, et videre non poterat: vocavitque Esau filium suum maiorem, et dixit ei: Fili mi? Qui respondit: Adsum.',
        2: 'Cui pater: Vides, inquit, quod senuerim, et ignorem diem mortis meae.',
        3: 'Sume arma tua, pharetram, et arcum, et egredere foras: cumque venatu aliquid apprehenderis,',
        4: 'fac mihi inde pulmentum sicut velle me nosti, et affer ut comedam: et benedicat tibi anima mea antequam moriar.',
        5: 'Quod cum audisset Rebecca, et ille abiisset in agrum ut iussionem patris impleret,',
        6: 'dixit filio suo Iacob: Audivi patrem tuum loquentem cum Esau fratre tuo, et dicentem ei:',
        7: 'Affer mihi de venatione tua, et fac cibos ut comedam, et benedicam tibi coram Domino antequam moriar.',
        8: 'Nunc ergo fili mi, acquiesce consiliis meis:',
        9: 'et pergens ad gregem, affer mihi duos hoedos optimos, ut faciam ex eis escas patri tuo, quibus libenter vescitur:',
        10: 'quas cum intuleris, et comederit, benedicat tibi priusquam moriatur.',
        11: 'Cui ille respondit: Nosti quod Esau frater meus homo pilosus sit, et ego lenis:',
        12: 'si attrectaverit me pater meus, et senserit, timeo ne putet me sibi voluisse illudere, et inducat super me maledictionem pro benedictione.',
        13: 'Ad quem mater: In me sit, ait, ista maledictio, fili mi: tantum audi vocem meam, et pergens affer quae dixi.',
        14: 'Abiit, et attulit, deditque matri. Paravit illa cibos, sicut velle noverat patrem illius.',
        15: 'Et vestibus Esau valde bonis, quas apud se habebat domi, induit eum:',
        16: 'pelliculasque hoedorum circumdedit manibus, et colli nuda protexit.',
        17: 'Deditque pulmentum, et panes, quos coxerat, tradidit.',
        18: 'Quibus illatis, dixit: Pater mi? At ille respondit: Audio. Quis es tu fili mi?',
        19: 'Dixitque Iacob: Ego sum primogenitus tuus Esau: feci sicut praecepisti mihi: surge, sede, et comede de venatione mea, ut benedicat mihi anima tua.',
        20: 'Rursumque Isaac ad filium suum: Quo modo, inquit, tam cito invenire potuisti, fili mi? Qui respondit: Voluntas Dei fuit ut cito occurreret mihi quod volebam:',
        21: 'Dixitque Isaac: Accede ad me, ut tangam te fili mi, et probem utrum tu sis filius meus Esau, an non.',
        22: 'Accessit ille ad patrem, et palpato eo, dixit Isaac: Vox quidem, vox Iacob est: sed manus, manus sunt Esau.',
        23: 'Et non cognovit eum, quia pilosae manus similitudinem maioris expresserant. Benedicens ergo illi,',
        24: 'ait: Tu es filius meus Esau? Respondit: Ego sum.',
        25: 'At ille: Affer mihi, inquit, cibos de venatione tua, fili mi, ut benedicat tibi anima mea. Quos cum oblatos comedisset, obtulit ei etiam vinum. quo hausto,',
        26: 'dixit ad eum: Accede ad me, et da mihi osculum, fili mi.',
        27: 'Accessit, et osculatus est eum. Statimque ut sensit vestimentorum illius fragrantiam, benedicens illi, ait: Ecce odor filii mei sicut odor agri pleni, cui benedixit Dominus.',
        28: 'Det tibi Deus de rore caeli, et de pinguedine terrae abundantiam frumenti et vini.',
        29: 'Et serviant tibi populi, et adorent te tribus: esto dominus fratrum tuorum, et incurventur ante te filii matris tuae. qui maledixerit tibi, sit ille maledictus: et qui benedixerit tibi, benedictionibus repleatur.',
        30: 'Vix Isaac sermonem impleverat: et egresso Iacob foras, venit Esau,',
        31: 'coctosque de venatione cibos intulit patri, dicens: Surge pater mi, et comede de venatione filii tui: ut benedicat mihi anima tua.',
        32: 'Dixitque illi Isaac: Quis enim es tu? Qui respondit: Ego sum filius tuus primogenitus Esau.',
        33: 'Expavit Isaac stupore vehementi: et ultra quam credi potest, admirans, ait: Quis igitur ille est qui dudum captam venationem attulit mihi, et comedi ex omnibus priusquam tu venires? benedixique ei, et erit benedictus.',
        34: 'Auditis Esau sermonibus patris, irrugiit clamore magno: et consternatus, ait: Benedic etiam et mihi, pater mi.',
        35: 'Qui ait: Venit germanus tuus fraudulenter, et accepit benedictionem tuam.',
        36: 'At ille subiunxit: Iuste vocatum est nomen eius Iacob: supplantavit enim me en altera vice: primogenita mea ante tulit, et nunc secundo surripuit benedictionem meam. Rursumque ad patrem: Numquid non reservasti, ait, et mihi benedictionem?',
        37: 'Respondit Isaac: Dominum tuum illum constitui, et omnes fratres eius servituti illius subiugavi: frumento et vino stabilivi eum, et tibi post haec, fili mi, ultra quid faciam?',
        38: 'Cui Esau: Num unam, inquit, tantum benedictionem habes, pater? mihi quoque obsecro ut benedicas. Cumque eiulatu magno fleret,',
        39: 'motus Isaac, dixit ad eum: In pinguedine terrae, et in rore caeli desuper',
        40: 'erit benedictio tua. Vives in gladio, et fratri tuo servies: tempusque veniet, cum excutias, et solvas iugum eius de cervicibus tuis.',
        41: 'Oderat ergo semper Esau Iacob pro benedictione qua benedixerat ei pater: dixitque in corde suo: Venient dies luctus patris mei, et occidam Iacob fratrem meum.',
        42: 'Nunciata sunt haec Rebeccae: quae mittens et vocans Iacob filium suum, dixit ad eum: Ecce Esau frater tuus minatur ut occidat te.',
        43: 'Nunc ergo, fili mi, audi vocem meam, et consurgens fuge ad Laban fratrem meum in Haran:',
        44: 'habitabisque cum eo dies paucos, donec requiescat furor fratris tui,',
        45: 'et cesset indignatio eius, obliviscaturque eorum quae fecisti in eum: postea mittam, et adducam te inde huc. cur utroque orbabor filio in uno die?',
        46: 'Dixitque Rebecca ad Isaac: Taedet me vitae meae propter filias Heth: si acceperit Iacob uxorem de stirpe huius terrae, nolo vivere.',
    },
    28: {
        1: 'Vocavit itaque Isaac Iacob, et benedixit eum, praecepitque ei dicens: Noli accipere coniugem de genere Chanaan:',
        2: 'sed vade, et proficiscere in Mesopotamiam Syriae, ad domum Bathuel patris matris tuae, et accipe tibi inde uxorem de filiabus Laban avunculi tui.',
        3: 'Deus autem omnipotens benedicat tibi, et crescere te faciat, atque multiplicet: ut sis in turbas populorum.',
        4: 'Et det tibi benedictiones Abrahae, et semini tuo post te: ut possideas terram peregrinationis tuae, quam pollicitus est avo tuo.',
        5: 'Cumque dimisisset eum Isaac, profectus pervenit in Mesopotamiam Syriae ad Laban filium Bathuel Syri, fratrem Rebeccae matris suae.',
        6: 'Videns autem Esau quod benedixisset pater suus Iacob, et misisset eum in Mesopotamiam Syriae, ut inde uxorem duceret; et quod post benedictionem praecepisset ei, dicens: Non accipies uxorem de filiabus Chanaan:',
        7: 'quodque obediens Iacob parentibus suis isset in Syriam:',
        8: 'probans quoque quod non libenter aspiceret filias Chanaan pater suus:',
        9: 'ivit ad Ismaelem, et duxit uxorem absque iis, quas prius habebat, Maheleth filiam Ismael filii Abraham, sororem Nabaioth.',
        10: 'Igitur egressus Iacob de Bersabee, pergebat Haran.',
        11: 'Cumque venisset ad quemdam locum, et vellet in eo requiescere post solis occubitum, tulit de lapidibus qui iacebant, et supponens capiti suo, dormivit in eodem loco.',
        12: 'Viditque in somnis scalam stantem super terram, et cacumen illius tangens caelum: Angelos quoque Dei ascendentes et descendentes per eam,',
        13: 'et Dominum innixum scalae dicentem sibi: Ego sum Dominus Deus Abraham patris tui, et Deus Isaac: Terram, in qua dormis, tibi dabo et semini tuo.',
        14: 'Eritque semen tuum quasi pulvis terrae: dilataberis ad Orientem, et Occidentem, et Septentrionem, et Meridiem: et BENEDICENTUR IN TE et in semine tuo cunctae tribus terrae.',
        15: 'Et ero custos tuus quocumque perrexeris, et reducam te in terram hanc: nec dimittam nisi complevero universa quae dixi.',
        16: 'Cumque evigilasset Iacob de somno, ait: Vere Dominus est in loco isto, et ego nesciebam.',
        17: 'Pavensque: Quam terribilis est, inquit, locus iste! non est hic aliud nisi domus Dei, et porta caeli.',
        18: 'Surgens ergo Iacob mane, tulit lapidem quem supposuerat capiti suo, et erexit in titulum, fundens oleum desuper.',
        19: 'Appellavitque nomen urbis Bethel, quae prius Luza vocabatur.',
        20: 'Vovit etiam votum, dicens: Si fuerit Dominus mecum, et custodierit me in via, per quam ego ambulo, et dederit mihi panem ad vescendum, et vestimentum ad induendum,',
        21: 'reversusque fuero prospere ad domum patris mei: erit mihi Dominus in Deum,',
        22: 'et lapis iste, quem erexi in titulum, vocabitur Domus Dei: cunctorumque quae dederis mihi, decimas offeram tibi.',
    },
    29: {
        1: 'Profectus ergo Iacob venit in terram Orientalem.',
        2: 'Et vidit puteum in agro, tres quoque greges ovium accubantes iuxta eum: nam ex illo adaquabantur pecora, et os eius grandi lapide claudebatur.',
        3: 'Morisque erat ut cunctis ovibus congregatis devolverent lapidem, et refectis gregibus rursum super os putei ponerent.',
        4: 'Dixitque ad pastores: Fratres, unde estis? Qui responderunt: De Haran.',
        5: 'Quos interrogans, Numquid, ait, nostis Laban filium Nachor? Dixerunt: Novimus.',
        6: 'Sanusne est? inquit: Valet, inquiunt: et ecce Rachel filia eius venit cum grege suo.',
        7: 'Dixitque Iacob: Adhuc multum diei superest, nec est tempus ut reducantur ad caulas greges: date ante potum ovibus, et sic eas ad pastum reducite.',
        8: 'Qui responderunt: Non possumus, donec omnia pecora congregentur, et amoveamus lapidem de ore putei, ut adaquemus greges.',
        9: 'Adhuc loquebantur, et ecce Rachel veniebat cum ovibus patris sui: nam gregem ipsa pascebat.',
        10: 'Quam cum vidisset Iacob, et sciret consobrinam suam, ovesque Laban avunculi sui: amovit lapidem quo puteus claudebatur.',
        11: 'Et adaquato grege, osculatus est eam: et elevata voce flevit,',
        12: 'et indicavit ei quod frater esset patris sui, et filius Rebeccae: at illa festinans nunciavit patri suo.',
        13: 'Qui cum audisset venisse Iacob filium sororis suae, occurrit obviam ei: complexusque eum, et in oscula ruens, duxit in domum suam. Auditis autem causis itineris,',
        14: 'respondit: Os meum es, et caro mea. Et postquam impleti sunt dies mensis unius,',
        15: 'dixit ei: Num quia frater meus es, gratis servies mihi? dic quid mercedis accipias.',
        16: 'Habebat vero duas filias, nomen maioris Lia: minor vero appellabatur Rachel.',
        17: 'Sed Lia lippis erat oculis: Rachel decora facie, et venusto aspectu.',
        18: 'Quam diligens Iacob, ait: Serviam tibi pro Rachel filia tua minore, septem annis.',
        19: 'Respondit Laban: Melius est ut tibi eam dem quam alteri viro, mane apud me.',
        20: 'Servivit ergo Iacob pro Rachel septem annis: et videbantur illi pauci dies prae amoris magnitudine.',
        21: 'Dixitque ad Laban: Da mihi uxorem meam: quia iam tempus impletum est, ut ingrediar ad illam.',
        22: 'Qui vocatis multis amicorum turbis ad convivium, fecit nuptias.',
        23: 'Et vespere Liam filiam suam introduxit ad eum,',
        24: 'dans ancillam filiae, Zelpham nomine. Ad quam cum ex more Iacob fuisset ingressus, facto mane vidit Lian:',
        25: 'et dixit ad socerum suum: Quid est quod facere voluisti? nonne pro Rachel servivi tibi? quare imposuisti mihi?',
        26: 'Respondit Laban: Non est in loco nostro consuetudinis, ut minores ante tradamus ad nuptias.',
        27: 'Imple hebdomadam dierum huius copulae: et hanc quoque dabo tibi pro opere quo serviturus es mihi septem annis aliis.',
        28: 'Acquievit placito: et hebdomada transacta, Rachel duxit uxorem:',
        29: 'cui pater servam Balam tradiderat.',
        30: 'Tandemque potitus optatis nuptiis, amorem sequentis priori praetulit, serviens apud eum septem annis aliis.',
        31: 'Videns autem Dominus quod despiceret Liam, aperuit vulvam eius, sorore sterili permanente.',
        32: 'Quae conceptum genuit filium, vocavitque nomen eius Ruben, dicens: Vidit Dominus humilitatem meam, nunc amabit me vir meus.',
        33: 'Rursumque concepit et peperit filium, et ait: Quoniam audivit me Dominus haberi contemptui, dedit etiam istum mihi. vocavitque nomen eius Simeon.',
        34: 'Concepitque tertio, et genuit alium filium: dixitque: Nunc quoque copulabitur mihi maritus meus, eo quod pepererim ei tres filios: et idcirco appellavit nomen eius, Levi.',
        35: 'Quarto concepit, et peperit filium, et ait: Modo confitebor Domino. et ob hoc vocavit eum, Iudam: cessavitque parere.',
    },
    30: {
        1: 'Cernens autem Rachel quod infecunda esset, invidit sorori suae, et ait marito suo: Da mihi liberos, alioquin moriar.',
        2: 'Cui iratus respondit Iacob: Num pro Deo ego sum, qui privavit te fructu ventris tui?',
        3: 'At illa: Habeo, inquit, famulam Balam: ingredere ad illam, ut pariat super genua mea, et habeam ex illa filios.',
        4: 'Deditque illi Balam in coniugium: quae,',
        5: 'ingresso ad se viro, concepit, et peperit filium.',
        6: 'Dixitque Rachel: Iudicavit mihi Dominus, et exaudivit vocem meam, dans mihi filium. et idcirco appellavit nomen eius, Dan.',
        7: 'Rursumque Bala concipiens, peperit alterum,',
        8: 'pro quo ait Rachel: Comparavit me Dominus cum sorore mea, et invalui: vocavitque eum, Nephthali.',
        9: 'Sentiens Lia quod parere desiisset, Zelpham ancillam suam marito tradidit.',
        10: 'Qua post conceptum edente filium,',
        11: 'dixit: Feliciter. et idcirco vocavit nomen eius, Gad.',
        12: 'Peperit quoque Zelpha alterum.',
        13: 'Dixitque Lia: Hoc pro beatitudine mea: Beatam quippe me dicent mulieres. propterea appellavit eum, Aser.',
        14: 'Egressus autem Ruben tempore messis triticeae in agrum, reperit mandragoras: quas matri Liae detulit. Dixitque Rachel: Da mihi partem de mandragoris filii tui.',
        15: 'Illa respondit: Parumne tibi videtur quod praeripueris maritum mihi, nisi etiam mandragoras filii mei tuleris? Ait Rachel: Dormiat tecum hac nocte pro mandragoris filii tui.',
        16: 'Redeuntique ad vesperam Iacob de agro, egressa est in occursum eius Lia, et ait: Ad me, inquit, intrabis: quia mercede conduxi te pro mandragoris filii mei. Dormivitque cum ea nocte illa.',
        17: 'Et exaudivit Deus preces eius: concepitque et peperit filium quintum,',
        18: 'et ait: Dedit Deus mercedem mihi, quia dedi ancillam meam viro meo. appellavitque nomen eius, Issachar.',
        19: 'Rursum Lia concipiens, peperit sextum filium,',
        20: 'et ait: Dotavit me Deus dote bona: etiam hac vice mecum erit maritus meus, eo quod genuerim ei sex filios: et idcirco appellavit nomen eius, Zabulon.',
        21: 'Post quem peperit filiam, nomine Dinam.',
        22: 'Recordatus quoque Dominus Rachelis, exaudivit eam, et aperuit vulvam eius.',
        23: 'Quae concepit, et peperit filium, dicens: Abstulit Deus opprobrium meum.',
        24: 'Et vocavit nomen eius, Ioseph, dicens: Addat mihi Dominus filium alterum.',
        25: 'Nato autem Ioseph, dixit Iacob socero suo: Dimitte me ut revertar in patriam meam, et ad terram meam.',
        26: 'Da mihi uxores, et liberos meos, pro quibus servivi tibi, ut abeam: tu vero nosti servitutem qua servivi tibi.',
        27: 'Ait illi Laban: Inveniam gratiam in conspectu tuo: experimento didici, quia benedixerit mihi Deus propter te:',
        28: 'constitue mercedem tuam quam dem tibi.',
        29: 'At ille respondit: Tu nosti quo modo servierim tibi, et quanta in manibus meis fuerit possessio tua.',
        30: 'Modicum habuisti antequam venirem ad te, et nunc dives effectus es: benedixitque tibi Deus ad introitum meum. iustum est igitur ut aliquando provideam etiam domui meae.',
        31: 'Dixitque Laban: Quid tibi dabo? At ille ait: Nihil volo: sed si feceris quod postulo, iterum pascam, et custodiam pecora tua.',
        32: 'Gyra omnes greges tuos, et separa cunctas oves varias, et sparso vellere; quodcumque furvum, et maculosum, variumque fuerit, tam in ovibus quam in capris, erit merces mea.',
        33: 'Respondebitque mihi cras iustitia mea, quando placiti tempus advenerit coram te: et omnia quae non fuerint varia, et maculosa, et furva, tam in ovibus quam in capris, furti me argues.',
        34: 'Dixitque Laban: Gratum habeo quod petis.',
        35: 'Et separavit in die illa capras, et oves, et hircos, et arietes varios, atque maculosos: cunctum autem gregem unicolorem, id est albi, et nigri velleris, tradidit in manu filiorum suorum.',
        36: 'Et posuit spatium itineris trium dierum inter se et generum, qui pascebat reliquos greges eius.',
        37: 'Tollens ergo Iacob virgas populeas virides, et amygdalinas, et ex platanis, ex parte decorticavit eas: detractisque corticibus, in his, quae spoliata fuerant, candor apparuit: illa vero quae integra fuerant, viridia permanserunt: atque in hunc modum color effectus est varius.',
        38: 'Posuitque eas in canalibus, ubi effundebatur aqua: ut cum venissent greges ad bibendum, ante oculos haberent virgas, et in aspectu earum conciperent.',
        39: 'Factumque est ut in ipso calore coitus, oves intuerentur virgas, et parerent maculosa, et varia, et diverso colore respersa.',
        40: 'Divisitque gregem Iacob, et posuit virgas in canalibus ante oculos arietum: erant autem alba et nigra quaeque, Laban: cetera vero, Iacob, separatis inter se gregibus.',
        41: 'Igitur quando primo tempore ascendebantur oves, ponebat Iacob virgas in canalibus aquarum ante oculos arietum et ovium, ut in earum contemplatione conciperent:',
        42: 'quando vero serotina admissura erat, et conceptus extremus, non ponebat eas. Factaque sunt ea quae erant serotina, Laban: et quae primi temporis, Iacob.',
        43: 'Ditatusque est homo ultra modum, et habuit greges multos, ancillas et servos, camelos et asinos.',
    },
    31: {
        1: 'Postquam autem audivit verba filiorum Laban dicentium: Tulit Iacob omnia quae fuerunt patris nostri, et de illius facultate ditatus, factus est inclytus:',
        2: 'animadvertit quoque faciem Laban, quod non esset erga se sicut heri et nudiustertius,',
        3: 'maxime dicente sibi Domino: Revertere in terram patrum tuorum, et ad generationem tuam, eroque tecum.',
        4: 'Misit, et vocavit Rachel et Liam in agrum, ubi pascebat greges,',
        5: 'dixitque eis: Video faciem patris vestri quod non sit erga me sicut heri, et nudiustertius: Deus autem patris mei fuit mecum.',
        6: 'Et ipsae nostis quod totis viribus meis servierim patri vestro.',
        7: 'Sed et pater vester circumvenit me, et mutavit mercedem meam decem vicibus: et tamen non dimisit eum Deus ut noceret mihi.',
        8: 'Si quando dixit: Variae erunt mercedes tuae: pariebant omnes oves varios foetus. quando vero econtrario ait: Alba quaeque accipies pro mercede: omnes greges alba pepererunt.',
        9: 'Tulitque Deus substantiam patris vestri, et dedit mihi.',
        10: 'Postquam enim conceptus ovium tempus advenerat, levavi oculos meos, et vidi in somnis ascendentes mares super feminas, varios et maculosos, et diversorum colorum.',
        11: 'Dixitque angelus Dei ad me in somnis: Iacob? Et ego respondi: Adsum.',
        12: 'Qui ait: Leva oculos tuos, et vide universos masculos ascendentes super feminas, varios, maculosos, atque respersos. Vidi enim omnia quae fecit tibi Laban.',
        13: 'Ego sum Deus Bethel, ubi unxisti lapidem, et votum vovisti mihi. Nunc ergo surge, et egredere de terra hac, revertens in terram nativitatis tuae.',
        14: 'Responderuntque Rachel et Lia: Numquid habemus residui quidquam in facultatibus, et hereditate domus patris nostri?',
        15: 'Nonne quasi alienas reputavit nos, et vendidit, comeditque pretium nostrum?',
        16: 'Sed Deus tulit opes patris nostri, et eas tradidit nobis, ac filiis nostris: unde omnia quae praecepit tibi Deus, fac.',
        17: 'Surrexit itaque Iacob, et impositis liberis, ac coniugibus suis super camelos, abiit.',
        18: 'Tulitque omnem substantiam suam, et greges, et quidquid in Mesopotamia acquisierat, pergens ad Isaac patrem suum in terram Chanaan.',
        19: 'Eo tempore ierat Laban ad tondendas oves, et Rachel furata est idola patris sui.',
        20: 'Noluitque Iacob confiteri socero suo quod fugeret.',
        21: 'Cumque abiisset tam ipse quam omnia quae iuris sui erant, et amne transmisso pergeret contra montem Galaad,',
        22: 'nunciatum est Laban die tertio quod fugeret Iacob.',
        23: 'Qui, assumptis fratribus suis, persecutus est eum diebus septem: et comprehendit eum in Monte Galaad.',
        24: 'Viditque in somnis dicentem sibi Deum: Cave ne quidquam aspere loquaris contra Iacob.',
        25: 'Iamque Iacob extenderat in monte tabernaculum: cumque ille consecutus fuisset eum cum fratribus suis, in eodem Monte Galaad fixit tentorium.',
        26: 'Et dixit ad Iacob: Quare ita egisti, ut clam me abigeres filias meas quasi captivas gladio?',
        27: 'Cur ignorante me fugere voluisti, nec indicare mihi, ut prosequerer te cum gaudio, et canticis, et tympanis, et citharis?',
        28: 'Non es passus ut oscularer filios meos et filias: stulte operatus es: et nunc quidem',
        29: 'valet manus mea reddere tibi malum: sed Deus patris tui heri dixit mihi: Cave ne loquaris contra Iacob quidquam durius.',
        30: 'Esto, ad tuos ire cupiebas, et desiderio erat tibi domus patris tui: cur furatus es deos meos?',
        31: 'Respondit Iacob: Quod inscio te profectus sum, timui ne violenter auferres filias tuas.',
        32: 'Quod autem furti me arguis: apud quemcumque inveneris deos tuos, necetur coram fratribus nostris. scrutare, quidquid tuorum apud me inveneris, et aufer. haec dicens, ignorabat quod Rachel furata esset idola.',
        33: 'Ingressus itaque Laban tabernaculum Iacob et Liae, et utriusque famulae, non invenit. Cumque intrasset tentorium Rachelis,',
        34: 'illa festinans abscondit idola subter stramenta cameli, et sedit desuper: scrutantique omne tentorium, et nihil invenienti,',
        35: 'ait: Ne irascatur dominus meus quod coram te assurgere nequeo: quia iuxta consuetudinem feminarum nunc accidit mihi. sic delusa solicitudo quaerentis est.',
        36: 'Tumensque Iacob, cum iurgio ait: Quam ob culpam meam, et ob quod peccatum meum sic exarsisti post me,',
        37: 'et scrutatus es omnem supellectilem meam? Quid invenisti de cuncta substantia domus tuae? pone hic coram fratribus meis, et fratribus tuis, et iudicent inter me, et te.',
        38: 'Idcirco viginti annis fui tecum? oves tuae et caprae steriles non fuerunt, arietes gregis tui non comedi:',
        39: 'nec captum a bestia ostendi tibi, ego damnum omne reddebam: quidquid furto peribat, a me exigebas:',
        40: 'die noctuque aestu urebar, et gelu, fugiebatque somnus ab oculis meis.',
        41: 'Sicque per viginti annos in domo tua servivi tibi, quattuordecim pro filiabus, et sex pro gregibus tuis: immutasti quoque mercedem meam decem vicibus.',
        42: 'Nisi Deus patris mei Abraham, et timor Isaac affuisset mihi, forsitan modo nudum me dimisisses: afflictionem meam et laborem manuum mearum respexit Deus, et arguit te heri.',
        43: 'Respondit ei Laban: Filiae meae et filii, et greges tui, et omnia quae cernis, mea sunt: quid possum facere filiis et nepotibus meis?',
        44: 'Veni ergo, et ineamus foedus: ut sit in testimonium inter me et te.',
        45: 'Tulit itaque Iacob lapidem, et erexit illum in titulum:',
        46: 'dixitque fratribus suis: Afferte lapides. Qui congregantes fecerunt tumulum, comederuntque super eum:',
        47: 'quem vocavit Laban Tumulum testis: et Iacob, Acervum testimonii, uterque iuxta proprietatem linguae suae.',
        48: 'Dixitque Laban: Tumulus iste erit testis inter me et te hodie, et idcirco appellatum est nomen eius Galaad, id est, Tumulus testis.',
        49: 'Intueatur et iudicet Dominus inter nos quando recesserimus a nobis,',
        50: 'si afflixeris filias meas, et si introduxeris alias uxores super eas: nullus sermonis nostri testis est absque Deo, qui praesens respicit.',
        51: 'Dixitque rursus ad Iacob: En tumulus hic, et lapis quem erexi inter me et te,',
        52: 'testis erit: tumulus, inquam, iste et lapis sint in testimonium, si aut ego transiero illum pergens ad te, aut tu praeterieris, malum mihi cogitans.',
        53: 'Deus Abraham, et Deus Nachor iudicet inter nos, Deus patris eorum. Iuravit ergo Iacob per timorem patris sui Isaac:',
        54: 'immolatisque victimis in monte, vocavit fratres suos ut ederent panem. Qui cum comedissent, manserunt ibi.',
        55: 'Laban vero de nocte consurgens, osculatus est filios, et filias suas, et benedixit illis: reversusque est in locum suum.',
    },
    32: {
        1: 'Iacob autem abiit in itinere quod coeperat: fueruntque ei obviam Angeli Dei.',
        2: 'Quos cum vidisset, ait: Castra Dei sunt haec. et appellavit nomen loci illius Mahanaim, id est, Castra.',
        3: 'Misit autem et nuncios ante se ad Esau fratrem suum in terram Seir, in regionem Edom:',
        4: 'praecepitque eis, dicens: Sic loquimini domino meo Esau: Haec dicit frater tuus Iacob: Apud Laban peregrinatus sum, et fui usque in praesentem diem.',
        5: 'Habeo boves, et asinos, et oves, et servos, et ancillas: mittoque nunc legationem ad dominum meum, ut inveniam gratiam in conspectu tuo.',
        6: 'Reversique sunt nuncii ad Iacob, dicentes: Venimus ad Esau fratrem tuum, et ecce properat tibi in occursum cum quadringentis viris.',
        7: 'Timuit Iacob valde: et perterritus divisit populum qui secum erat, greges quoque et oves et boves, et camelos in duas turmas,',
        8: 'dicens: Si venerit Esau ad unam turmam, et percusserit eam, alia turma, quae relicta est, salvabitur.',
        9: 'Dixitque Iacob: Deus patris mei Abraham, et Deus patris mei Isaac: Domine qui dixisti mihi: Revertere in terram tuam, et in locum nativitatis tuae, et benefaciam tibi:',
        10: 'minor sum cunctis miserationibus tuis, et veritate tua quam explevisti servo tuo. In baculo meo transivi Iordanem istum: et nunc cum duabus turmis regredior.',
        11: 'Erue me de manu fratris mei Esau, quia valde eum timeo: ne forte veniens percutiat matrem cum filiis.',
        12: 'Tu locutus es quod benefaceres mihi, et dilatares semen meum sicut arenam maris, quae prae multitudine numerari non potest.',
        13: 'Cumque dormisset ibi nocte illa, separavit de his quae habebat, munera Esau fratri suo,',
        14: 'capras ducentas, hircos viginti, oves ducentas, et arietes viginti,',
        15: 'camelos foetas cum pullis suis triginta, vaccas quadraginta, et tauros viginti, asinas viginti, et pullos earum decem.',
        16: 'Et misit per manus servorum suorum singulos seorsum greges, dixitque pueris suis: Antecedite me, et sit spatium inter gregem et gregem.',
        17: 'Et praecepit priori, dicens: Si obvium habueris fratrem meum Esau, et interrogaverit te, Cuius es? aut, Quo vadis? aut, Cuius sunt ista quae sequeris?',
        18: 'respondebis: Servi tui Iacob, munera misit domino suo Esau: ipse quoque post nos venit.',
        19: 'Similiter dedit mandata secundo, et tertio, et cunctis qui sequebantur greges, dicens: Iisdem verbis loquimini ad Esau, cum inveneritis eum.',
        20: 'Et addetis: Ipse quoque servus tuus Iacob iter nostrum insequitur: dixit enim: Placabo illum muneribus quae praecedunt, et postea videbo illum, forsitan propitiabitur mihi.',
        21: 'Praecesserunt itaque munera ante eum, ipse vero mansit nocte illa in castris.',
        22: 'Cumque mature surrexisset, tulit duas uxores suas, et totidem famulas cum undecim filiis, et transivit vadum Iaboc.',
        23: 'Traductisque omnibus quae ad se pertinebant,',
        24: 'mansit solus: et ecce vir luctabatur cum eo usque mane.',
        25: 'Qui cum videret quod eum superare non posset, tetigit nervum femoris eius, et statim emarcuit.',
        26: 'Dixitque ad eum: Dimitte me, iam enim ascendit aurora. Respondit: Non dimittam te, nisi benedixeris mihi.',
        27: 'Ait ergo: Quod nomen est tibi? Respondit: Iacob.',
        28: 'At ille, Nequaquam, inquit, Iacob appellabitur nomen tuum, sed Israel: quoniam si contra Deum fortis fuisti, quanto magis contra homines praevalebis?',
        29: 'Interrogavit eum Iacob: Dic mihi, quo appellaris nomine? Respondit: Cur quaeris nomen meum? Et benedixit ei in eodem loco.',
        30: 'Vocavitque Iacob nomen loci illius Phanuel, dicens: Vidi Dominum facie ad faciem, et salva facta est anima mea.',
        31: 'Ortusque est ei statim sol, postquam transgressus est Phanuel: ipse vero claudicabat pede.',
        32: 'Quam ob causam non comedunt nervum filii Israel, qui emarcuit in femore Iacob, usque in praesentem diem: eo quod tetigerit nervum femoris eius, et obstupuerit.',
    },
    33: {
        1: 'Elevans autem Iacob oculos suos, vidit venientem Esau, et cum eo quadringentos viros: divisitque filios Liae et Rachel, ambarumque famularum:',
        2: 'et posuit utramque ancillam, et liberos earum in principio: Liam vero, et filios eius in secundo loco: Rachel autem, et Ioseph novissimos.',
        3: 'Et ipse progrediens adoravit pronus in terram septies, donec appropinquaret frater eius.',
        4: 'Currens itaque Esau obviam fratri suo, amplexatus est eum: stringensque collum eius, et osculans flevit.',
        5: 'Levatisque oculis, vidit mulieres et parvulos earum, et ait: Quid sibi volunt isti? et si ad te pertinent? Respondit: Parvuli sunt, quos donavit mihi Deus servo tuo.',
        6: 'Et appropinquantes ancillae et filii earum, incurvati sunt.',
        7: 'Accessit quoque Lia cum pueris suis: et cum similiter adorassent, extremi Ioseph et Rachel adoraverunt.',
        8: 'Dixitque Esau: Quaenam sunt istae turmae quas obviam habui? Respondit: Ut invenirem gratiam coram domino meo.',
        9: 'At ille ait: Habeo plurima, frater mi, sint tua tibi.',
        10: 'Dixitque Iacob: Noli ita, obsecro: sed si inveni gratiam in oculis tuis, accipe munusculum de manibus meis: sic enim vidi faciem tuam, quasi viderim vultum Dei: esto mihi propitius,',
        11: 'et suscipe benedictionem quam attuli tibi, et quam donavit mihi Deus tribuens omnia. Vix fratre compellente, suscipiens,',
        12: 'ait: Gradiamur simul, eroque socius itineris tui.',
        13: 'Dixitque Iacob: Nosti domine mi quod parvulos habeam teneros, et oves, et boves foetas mecum: quas si plus in ambulando fecero laborare, morientur una die cuncti greges.',
        14: 'Praecedat dominus meus ante servum suum: et ego sequar paulatim vestigia eius, sicut videro parvulos meos posse, donec veniam ad dominum meum in Seir.',
        15: 'Respondit Esau: Oro te, ut de populo qui mecum est, saltem socri remaneant viae tuae. Non est, inquit, necesse: hoc uno tantum indigeo, ut inveniam gratiam in conspectu tuo domine mi.',
        16: 'Reversus est itaque illo die Esau itinere quo venerat in Seir.',
        17: 'Et Iacob venit in Socoth: ubi aedificata domo et fixis tentoriis appellavit nomen loci illius Socoth, id est, tabernacula.',
        18: 'Transivitque in Salem urbem Sichimorum, quae est in terra Chanaan, postquam reversus est de Mesopotamia Syriae: et habitavit iuxta oppidum.',
        19: 'Emitque partem agri in qua fixerat tabernacula, a filiis Hemor patris Sichem centum agnis.',
        20: 'Et erecto ibi altari, invocavit super illud fortissimum Deum Israel.',
    },
    34: {
        1: 'Egressa est autem Dina filia Liae ut videret mulieres regionis illius.',
        2: 'Quam cum vidisset Sichem filius Hemor Hevaei, princeps terrae illius, adamavit eam: et rapuit, et dormivit cum illa, vi opprimens virginem.',
        3: 'Et conglutinata est anima eius cum ea, tristemque delinivit blanditiis.',
        4: 'Et pergens ad Hemor patrem suum, Accipe, inquit, mihi puellam hanc coniugem.',
        5: 'Quod cum audisset Iacob, absentibus filiis, et in pastu pecorum occupatis, siluit donec redirent.',
        6: 'Egresso autem Hemor patre Sichem ut loqueretur ad Iacob,',
        7: 'ecce filii eius veniebant de agro: auditoque quod acciderat, irati sunt valde, eo quod foedam rem operatus esset in Israel et, violata filia Iacob, rem illicitam perpetrasset.',
        8: 'Locutus est itaque Hemor ad eos: Sichem filii mei adhaesit anima filiae vestrae: date eam illi uxorem:',
        9: 'et iungamus vicissim connubia: filias vestras tradite nobis, et filias nostras accipite.',
        10: 'Et habitate nobiscum: terra in potestate vestra est, exercete, negotiamini, et possidete eam.',
        11: 'Sed et Sichem ad patrem et ad fratres eius ait: Inveniam gratiam coram vobis: et quaecumque statueritis, dabo:',
        12: 'augete dotem, et munera postulate, et libenter tribuam quod petieritis: tantum date mihi puellam hanc uxorem.',
        13: 'Responderunt filii Iacob Sichem et patri eius in dolo, saevientes ob stuprum sororis:',
        14: 'Non possumus facere quod petitis, nec dare sororem nostram homini incircumciso: quod illicitum et nefarium est apud nos.',
        15: 'Sed in hoc valebimus foederari, si volueritis esse similes nostri, et circumcidatur in vobis omnis masculini sexus;',
        16: 'tunc dabimus et accipiemus mutuo filias vestras, ac nostras: et habitabimus vobiscum, erimusque unus populus:',
        17: 'si autem circumcidi nolueritis, tollemus filiam nostram, et recedemus.',
        18: 'Placuit oblatio eorum Hemor, et Sichem filio eius:',
        19: 'nec distulit adolescens quin statim quod petebatur expleret: amabat enim puellam valde, et ipse erat inclytus in omni domo patris sui.',
        20: 'Ingressique portam urbis, locuti sunt ad populum:',
        21: 'Viri isti pacifici sunt, et volunt habitare nobiscum: negotientur in terra, et exerceant eam, quae spatiosa et lata cultoribus indiget: filias eorum accipiemus uxores, et nostras illis dabimus.',
        22: 'Unum est quo differtur tantum bonum: Si circumcidamus masculos nostros, ritum gentis imitantes.',
        23: 'Et substantia eorum, et pecora, et cuncta quae possident, nostra erunt: tantum in hoc acquiescamus, et habitantes simul, unum efficiamus populum.',
        24: 'Assensique sunt omnes, circumcisis cunctis maribus.',
        25: 'Et ecce, die tertio quando gravissimus vulnerum dolor est: arreptis, duo filii Iacob, Simeon et Levi fratres Dinae, gladiis, ingressi sunt urbem confidenter: interfectisque omnibus masculis,',
        26: 'Hemor et Sichem pariter necaverunt, tollentes Dinam de domo Sichem sororem suam.',
        27: 'Quibus egressis, irruerunt super occisos ceteri filii Iacob: et depopulati sunt urbem in ultionem stupri.',
        28: 'Oves eorum, et armenta, et asinos, cunctaque vastantes quae in domibus et in agris erant,',
        29: 'parvulos quoque eorum et uxores duxerunt captivas.',
        30: 'Quibus patratis audacter, Iacob dixit ad Simeon et Levi: Turbastis me, et odiosum fecistis me Chananaeis, et Pherezaeis habitatoribus terrae huius. nos pauci sumus: illi congregati percutient me, et delebor ego, et domus mea.',
        31: 'Responderunt: Numquid ut scorto abuti debuere sorore nostra?',
    },
    35: {
        1: 'Interea locutus est Deus ad Iacob: Surge, et ascende Bethel, et habita ibi, facque altare Deo qui apparuit tibi quando fugiebas Esau fratrem tuum.',
        2: 'Iacob vero convocata omni domo sua, ait: Abiicite deos alienos qui in medio vestri sunt, et mundamini, ac mutate vestimenta vestra.',
        3: 'Surgite, et ascendamus in Bethel, ut faciamus ibi altare Deo: qui exaudivit me in die tribulationis meae, et socius fuit itineris mei.',
        4: 'Dederunt ergo ei omnes deos alienos quos habebant, et inaures quae erant in auribus eorum: at ille infodit eas subter terebinthum, quae est post urbem Sichem.',
        5: 'Cumque profecti essent, terror Dei invasit omnes per circuitum civitates, et non sunt ausi persequi recedentes.',
        6: 'Venit igitur Iacob Luzam, quae est in terra Chanaan, cognomento Bethel: ipse et omnis populus cum eo.',
        7: 'Aedificavitque ibi altare, et appellavit nomen loci illius, Domus Dei: ibi enim apparuit ei Deus cum fugeret fratrem suum.',
        8: 'Eodem tempore mortua est Debora nutrix Rebeccae, et sepulta est ad radices Bethel subter quercum: vocatumque est nomen loci illius, Quercus fletus.',
        9: 'Apparuit autem iterum Deus Iacob postquam reversus est de Mesopotamia Syriae, benedixitque ei,',
        10: 'dicens: Non vocaberis ultra Iacob, sed Israel erit nomen tuum. Et appellavit eum Israel,',
        11: 'dixitque ei: Ego Deus omnipotens, cresce, et multiplicare: gentes, et populi nationum ex te erunt, reges de lumbis tuis egredientur.',
        12: 'Terramque quam dedi Abraham et Isaac, dabo tibi et semini tuo post te.',
        13: 'Et recessit ab eo.',
        14: 'Ille vero erexit titulum lapideum in loco quo locutus fuerat ei Deus: libans super eum libamina, et effundens oleum:',
        15: 'vocansque nomen loci illius, Bethel.',
        16: 'Egressus autem inde, venit verno tempore ad terram quae ducit Ephratam: in qua cum parturiret Rachel,',
        17: 'ob difficultatem partus periclitari coepit. Dixitque ei obstetrix: Noli timere, quia et hunc habebis filium.',
        18: 'Egrediente autem anima prae dolore, et imminente iam morte, vocavit nomen filii sui Benomi, id est filius doloris mei: pater vero appellavit eum Beniamin, id est filius dextrae.',
        19: 'Mortua est ergo Rachel, et sepulta est in via quae ducit Ephratam, haec est Bethlehem.',
        20: 'Erexitque Iacob titulum super sepulchrum eius: hic est titulus monumenti Rachel, usque in praesentem diem.',
        21: 'Egressus inde, fixit tabernaculum trans Turrem gregis.',
        22: 'Cumque habitaret in illa regione, abiit Ruben, et dormivit cum Bala concubina patris sui: quod illum minime latuit. Erant autem filii Iacob duodecim.',
        23: 'Filii Liae: primogenitus Ruben, et Simeon, et Levi, et Iudas, et Issachar, et Zabulon.',
        24: 'Filii Rachel: Ioseph et Beniamin.',
        25: 'Filii Balae ancillae Rachelis: Dan et Nephthali.',
        26: 'Filii Zelphae ancillae Liae: Gad et Aser: hi sunt filii Iacob, qui nati sunt ei in Mesopotamia Syriae.',
        27: 'Venit etiam ad Isaac patrem suum in Mambre, Civitatem Arbee, haec est Hebron: in qua peregrinatus est Abraham et Isaac.',
        28: 'Et completi sunt dies Isaac centum octoginta annorum.',
        29: 'Consumptusque aetate mortuus est: et appositus est populo suo senex et plenus dierum: et sepelierunt eum Esau et Iacob filii sui.',
    },
    36: {
        1: 'Hae sunt autem generationes Esau, ipse est Edom.',
        2: 'Esau accepit uxores de filiabus Chanaan: Ada filiam Elon Hethaei, et Oolibama filiam Anae filiae Sebeon Hevaei:',
        3: 'Basemath quoque filiam Ismael sororem Nabaioth.',
        4: 'Peperit autem Ada, Eliphaz: Basemath genuit Rahuel:',
        5: 'Oolibama genuit Iehus et Ihelon et Core. hi filii Esau qui nati sunt ei in terra Chanaan.',
        6: 'Tulit autem Esau uxores suas et filios et filias, et omnem animam domus suae, et substantiam, et pecora, et cuncta quae habere poterat in terra Chanaan: et abiit in alteram regionem, recessitque a fratre suo Iacob.',
        7: 'Divites enim erant valde, et simul habitare non poterant: nec sustinebat eos terra peregrinationis eorum prae multitudine gregum.',
        8: 'Habitavitque Esau in monte Seir, ipse est Edom.',
        9: 'Hae autem sunt generationes Esau patris Edom in monte Seir,',
        10: 'et haec nomina filiorum eius: Eliphaz filius Ada uxoris Esau: Rahuel quoque filius Basemath uxoris eius.',
        11: 'Fueruntque Eliphaz filii: Theman, Omar, Sepho, et Gatham, et Cenez.',
        12: 'Erat autem Thamna, concubina Eliphaz filii Esau: quae peperit ei Amalech. hi sunt filii Ada uxoris Esau.',
        13: 'Filii autem Rahuel: Nahath et Zara, Samma et Meza. hi filii Basemath uxoris Esau.',
        14: 'Isti quoque erant filii Oolibama filiae Anae filiae Sebeon, uxoris Esau, quos genuit ei Iehus et Ihelon et Core.',
        15: 'Hi duces filiorum Esau: Filii Eliphaz primogeniti Esau: dux Theman, dux Omra, dux Sepho, dux Cenez,',
        16: 'dux Core, dux Gathan, dux Amalech. hi filii Eliphaz in terra Edom, et hi filii Ada.',
        17: 'Hi quoque filii Rahuel filii Esau: dux Nahath, dux Zara, dux Samma, dux Meza. hi autem duces Rahuel in terra Edom: isti filii Basemath uxoris Esau.',
        18: 'Hi autem filii Oolibama uxoris Esau: dux Iehus, dux Ihelon, dux Core. hi duces Oolibama filiae Anae uxoris Esau.',
        19: 'Isti sunt filii Esau, et hi duces eorum: ipse est Edom.',
        20: 'Isti sunt filii Seir Horraei, habitatores terrae: Lotan, et Sobal, et Sebeon, et Ana,',
        21: 'et Dison, et Eser, et Disan. hi duces Horraei, filii Seir in Terra Edom.',
        22: 'Facti sunt autem filii Lotan: Hori et Heman. erat autem soror Lotan, Thamna.',
        23: 'Et isti filii Sobal: Alvan et Manahat et Ebal, et Sepho et Onam.',
        24: 'Et hi filii Sebeon: Aia et Ana. Iste est Ana qui invenit aquas calidas in solitudine, cum pasceret asinas Sebeon patris sui:',
        25: 'habuitque filium Dison, et filiam Oolibama.',
        26: 'Et isti filii Dison: Hamdan, et Eseban, et Iethram, et Charan.',
        27: 'Hi quoque filii Eser: Balaan, et Zavan, et Acan.',
        28: 'Habuit autem filios Disan: Hus, et Aram.',
        29: 'Hi duces Horraeorum: dux Lotan, dux Sobal, dux Sebeon, dux Ana,',
        30: 'dux Dison, dux Eser, dux Disan: isti duces Horraeorum qui imperaverunt in Terra Seir.',
        31: 'Reges autem qui regnaverunt in Terra Edom antequam haberent regem filii Israel, fuerunt hi:',
        32: 'Bela filius Beor, nomenque urbis eius Denaba.',
        33: 'Mortuus est autem Bela, et regnavit pro eo Iobab filius Zarae de Bosra.',
        34: 'Cumque mortuus esset Iobab, regnavit pro eo Husam de terra Themanorum.',
        35: 'Hoc quoque mortuo, regnavit pro eo Adad filius Badad, qui percussit Madian in regione Moab: et nomen urbis eius Avith.',
        36: 'Cumque mortuus esset Adad, regnavit pro eo Semla de Masreca.',
        37: 'Hoc quoque mortuo regnavit pro eo Saul de fluvio Rohoboth.',
        38: 'Cumque et hic obiisset, successit in regnum Balanan filius Achobor.',
        39: 'Isto quoque mortuo regnavit pro eo Adar, nomenque urbis eius Phau: et appellabatur uxor eius Meetabel, filia Matred filiae Mezaab.',
        40: 'Haec ergo nomina ducum Esau in cognationibus, et locis, et vocabulis suis: dux Thamna, dux Alva, dux Ietheth,',
        41: 'dux Oolibama, dux Ela, dux Phinon,',
        42: 'dux Cenez, dux Theman, dux Mabsar,',
        43: 'dux Magdiel, dux Hiram: hi duces Edom habitantes in terra imperii sui, ipse est Esau pater Idumaeorum.',
    },
    37: {
        1: 'Habitavit autem Iacob in terra Chanaan, in qua pater suus peregrinatus est.',
        2: 'Et hae sunt generationes eius: Ioseph cum sedecim esset annorum, pascebat gregem cum fratribus suis adhuc puer: et erat cum filiis Balae et Zelphae uxorum patris sui: accusavitque fratres suos apud patrem crimine pessimo.',
        3: 'Israel autem diligebat Ioseph super omnes filios, eo quod in senectute genuisset eum: fecitque ei tunicam polymitam.',
        4: 'Videntes autem fratres eius quod a patre plus cunctis filiis amaretur, oderant eum, nec poterant ei quidquam pacifice loqui.',
        5: 'Accidit quoque ut visum somnium referret fratribus suis: quae causa maioris odii seminarium fuit.',
        6: 'Dixitque ad eos: Audite somnium meum quod vidi:',
        7: 'Putabam nos ligare manipulos in agro: et quasi consurgere manipulum meum, et stare, vestrosque manipulos circumstantes adorare manipulum meum.',
        8: 'Responderunt fratres eius: Numquid rex noster eris? aut subiiciemur ditioni tuae? Haec ergo causa somniorum atque sermonum, invidiae et odii fomitem ministravit.',
        9: 'Aliud quoque vidit somnium, quod narrans fratribus, ait: Vidi per somnium, quasi solem, et lunam, et stellas undecim adorare me.',
        10: 'Quod cum patri suo, et fratribus retulisset, increpavit eum pater suus, et dixit: Quid sibi vult hoc somnium quod vidisti? num ego et mater tua, et fratres tui adorabimus te super terram?',
        11: 'Invidebant ei igitur fratres sui: pater vero rem tacitus considerabat.',
        12: 'Cumque fratres illius in pascendis gregibus patris morarentur in Sichem,',
        13: 'dixit ad eum Israel: Fratres tui pascunt oves in Sichimis: veni, mittam te ad eos. Quo respondente,',
        14: 'Praesto sum, ait ei: Vade, et vide si cuncta prospera sint erga fratres tuos, et pecora: et renuncia mihi quid agatur. Missus de Valle Hebron, venit in Sichem:',
        15: 'invenitque eum vir errantem in agro, et interrogavit quid quaereret.',
        16: 'At ille respondit: Fratres meos quaero, indica mihi ubi pascant greges.',
        17: 'Dixitque ei vir: Recesserunt de loco isto: audivi autem eos dicentes: Eamus in Dothain. Perrexit itaque Ioseph post fratres suos, et invenit eos in Dothain.',
        18: 'Qui cum vidissent eum procul, antequam accederet ad eos, cogitaverunt illum occidere:',
        19: 'et mutuo loquebantur: Ecce somniator venit:',
        20: 'venite, occidamus eum, et mittamus in cisternam veterem: dicemusque: Fera pessima devoravit eum: et tunc apparebit quid illi prosint somnia sua.',
        21: 'Audiens autem hoc Ruben, nitebatur liberare eum de manibus eorum, et dicebat:',
        22: 'Non interficiatis animam eius, nec effundatis sanguinem: sed proiicite eum in cisternam hanc, quae est in solitudine, manusque vestras servate innoxias: hoc autem dicebat, volens eripere eum de manibus eorum, et reddere patri suo.',
        23: 'Confestim igitur ut pervenit ad fratres suos, nudaverunt eum tunica talari, et polymita:',
        24: 'miseruntque eum in cisternam veterem, quae non habebat aquam.',
        25: 'Et sedentes ut comederent panem, viderunt Ismaelitas viatores venire de Galaad, et camelos eorum portantes aromata, et resinam, et stacten in Aegyptum.',
        26: 'Dixit ergo Iudas fratribus suis: Quid nobis prodest si occiderimus fratrem nostrum, et celaverimus sanguinem ipsius?',
        27: 'Melius est ut venundetur Ismaelitis, et manus nostrae non polluantur: frater enim, et caro nostra est. Acquieverunt fratres sermonibus illius.',
        28: 'Et praetereuntibus Madianitis negotiatoribus, extrahentes eum de cisterna, vendiderunt eum Ismaelitis, viginti argenteis: qui duxerunt eum in Aegyptum.',
        29: 'Reversusque Ruben ad cisternam, non invenit puerum:',
        30: 'et scissis vestibus pergens ad fratres suos, ait: Puer non comparet, et ego quo ibo?',
        31: 'Tulerunt autem tunicam eius, et in sanguinem hoedi, quem occiderant, tinxerunt:',
        32: 'mittentes qui ferrent ad patrem, et dicerent: Hanc invenimus: vide utrum tunica filii tui sit, an non.',
        33: 'Quam cum agnovisset pater, ait: Tunica filii mei est, fera pessima comedit eum, bestia devoravit Ioseph.',
        34: 'Scissisque vestibus, indutus est cilicio, lugens filium suum multo tempore.',
        35: 'Congregatis autem cunctis liberis eius ut lenirent dolorem patris, noluit consolationem accipere, sed ait: Descendam ad filium meum lugens in infernum. Et illo perseverante in fletu,',
        36: 'Madianitae vendiderunt Ioseph in Aegypto Phutiphari eunucho Pharaonis magistro militum.',
    },
    38: {
        1: 'Eodem tempore descendens Iudas a fratribus suis, divertit ad Virum Odollamitem, nomine Hiram.',
        2: 'Viditque ibi filiam hominis Chananaei, vocabulo Sue: et accepta uxore, ingressus est ad eam.',
        3: 'Quae concepit, et peperit filium, et vocavit nomen eius Her.',
        4: 'Rursumque concepto foetu, natum filium vocavit Onan.',
        5: 'Tertium quoque peperit: quem appellavit Sela. quo nato, parere ultra cessavit.',
        6: 'Dedit autem Iudas uxorem primogenito suo Her, nomine Thamar.',
        7: 'Fuit quoque Her primogenitus Iudae, nequam in conspectu Domini: et ab eo occisus est.',
        8: 'Dixit ergo Iudas ad Onan filium suum: Ingredere uxorem fratris tui, et sociare illi, ut suscites semen fratri tuo.',
        9: 'Ille sciens non sibi nasci filios, introiens ad uxorem fratris sui, semen fundebat in terram, ne liberi fratris nomine nascerentur.',
        10: 'Et idcirco percussit eum Dominus, eo quod rem detestabilem faceret.',
        11: 'Quam ob rem dixit Iudas Thamar nurui suae: Esto vidua in domo patris tui, donec crescat Sela filius meus: timebat enim ne et ipse moreretur, sicut fratres eius. Quae abiit, et habitavit in domo patris sui.',
        12: 'Evolutis autem multis diebus, mortua est Sue uxor Iudae: qui post luctum consolatione suscepta, ascendebat ad tonsores ovium suarum, ipse et Hiras opilio gregis Odollamites, in Thamnas.',
        13: 'Nunciatumque est Thamar quod socer illius ascenderet in Thamnas ad tondendas oves.',
        14: 'Quae, depositis viduitatis vestibus, assumpsit theristrum: et mutato habitu, sedit in bivio itineris, quod ducit Thamnam: eo quod crevisset Sela, et non eum accepisset maritum.',
        15: 'Quam cum vidisset Iudas, suspicatus est esse meretricem: operuerat enim vultum suum, ne agnosceretur.',
        16: 'Ingrediensque ad eam, ait: Dimitte me ut coeam tecum: nesciebat enim quod nurus sua esset. Qua respondente: Quid dabis mihi ut fruaris concubitu meo?',
        17: 'dixit: Mittam tibi hoedum de gregibus. Rursumque illa dicente: Patiar quod vis, si dederis mihi arrhabonem, donec mittas quod polliceris.',
        18: 'Ait Iudas: Quid tibi vis pro arrhabone dari? Respondit: Annulum tuum, et armillam, et baculum quem manu tenes. Ad unum igitur coitum mulier concepit,',
        19: 'et surgens abiit: depositoque habitu, quem sumpserat, induta est viduitatis vestibus.',
        20: 'Misit autem Iudas hoedum per pastorem suum Odollamitem, ut reciperet pignus quod dederat mulieri: qui cum non invenisset eam,',
        21: 'interrogavit homines loci illius: Ubi est mulier quae sedebat in bivio? Respondentibus cunctis: Non fuit in loco ista meretrix.',
        22: 'Reversus est ad Iudam, et dixit ei: Non inveni eam: sed et homines loci illius dixerunt mihi, numquam sedisse ibi scortum.',
        23: 'Ait Iudas: Habeat sibi, certe mendacii arguere nos non potest, ego misi hoedum quem promiseram: et tu non invenisti eam.',
        24: 'Ecce autem post tres menses nunciaverunt Iudae, dicentes: Fornicata est Thamar nurus tua, et videtur uterus illius intumescere. Dixitque Iudas: Producite eam ut comburatur.',
        25: 'Quae cum duceretur ad poenam, misit ad socerum suum, dicens: De viro, cuius haec sunt, concepi: cognosce cuius sit annulus, et armilla, et baculus.',
        26: 'Qui, agnitis muneribus, ait: Iustior me est: quia non tradidi eam Sela filio meo. Attamen ultra non cognovit eam.',
        27: 'Instante autem partu, apparuerunt gemini in utero: atque in ipsa effusione infantium unus protulit manum, in qua obstetrix ligavit coccinum, dicens:',
        28: 'Iste egredietur prior.',
        29: 'Illo vero retrahente manum, egressus est alter: dixitque mulier: Quare divisa est propter te maceria? et ob hanc causam vocavit nomen eius Phares.',
        30: 'Postea egressus est frater eius, in cuius manu erat coccinum: quem appellavit Zara.',
    },
    39: {
        1: 'Igitur Ioseph ductus est in Aegyptum, emitque eum Phutiphar eunuchus Pharaonis, princeps exercitus sui, vir Aegyptius, de manu Ismaelitarum, a quibus perductus erat.',
        2: 'Fuitque Dominus cum eo, et erat vir in cunctis prospere agens: habitavitque in domo domini sui,',
        3: 'qui optime noverat Dominum esse cum eo, et omnia, quae gerebat, ab eo dirigi in manu illius.',
        4: 'Invenitque Ioseph gratiam coram domino suo, et ministrabat ei, a quo praepositus omnibus gubernabat creditam sibi domum, et universa quae ei tradita fuerant:',
        5: 'benedixitque Dominus domui Aegyptii propter Ioseph, et multiplicavit tam in aedibus quam in agris cunctam eius substantiam:',
        6: 'nec quidquam aliud noverat, nisi panem quo vescebatur. Erat autem Ioseph pulchra facie, et decorus aspectu.',
        7: 'Post multos itaque dies iniecit domina sua oculos suos in Ioseph, et ait: Dormi mecum.',
        8: 'Qui nequaquam acquiescens operi nefario, dixit ad eam: Ecce dominus meus, omnibus mihi traditis, ignorat quid habeat in domo sua:',
        9: 'nec quidquam est quod non in mea sit potestate, vel non tradiderit mihi, praeter te, quae uxor eius es: quo modo ergo possum hoc malum facere, et peccare in Dominum meum?',
        10: 'Huiuscemodi verbis per singulos dies et mulier molesta erat adolescenti: et ille recusabat stuprum.',
        11: 'Accidit autem quadam die ut intraret Ioseph domum, et operis quippiam absque arbitris faceret:',
        12: 'et illa, apprehensa lacinia vestimenti eius, diceret: Dormi mecum. Qui relicto in manu eius pallio fugit, et egressus est foras.',
        13: 'Cumque vidisset mulier vestem in manibus suis, et se esse contemptam,',
        14: 'vocavit ad se homines domus suae, et ait ad eos: En introduxit virum Hebraeum, ut illuderet nobis: ingressus est ad me, ut coiret mecum: cumque ego succlamassem,',
        15: 'et audisset vocem meam, reliquit pallium quod tenebam, et fugit foras.',
        16: 'In argumentum ergo fidei retentum pallium ostendit marito revertenti domum,',
        17: 'et ait: Ingressus est ad me servus Hebraeus quem adduxisti ut illuderet mihi:',
        18: 'cumque audisset me clamare, reliquit pallium quod tenebam, et fugit foras.',
        19: 'His auditis dominus, et nimium credulus verbis coniugis, iratus est valde:',
        20: 'tradiditque Ioseph in carcerem, ubi vincti regis custodiebantur, et erat ibi clausus.',
        21: 'Fuit autem Dominus cum Ioseph, et misertus illius dedit ei gratiam in conspectu principis carceris.',
        22: 'Qui tradidit in manu illius universos vinctos qui in custodia tenebantur: et quidquid fiebat, sub ipso erat.',
        23: 'Nec noverat aliquid, cunctis ei creditis: Dominus enim erat cum illo, et omnia opera eius dirigebat.',
    },
    40: {
        1: 'His itaque gestis, accidit ut peccarent duo eunuchi, pincerna regis Aegypti, et pistor, domino suo.',
        2: 'Iratusque contra eos Pharao (nam alter pincernis praeerat, alter pistoribus)',
        3: 'misit eos in carcerem principis militum, in quo erat vinctus et Ioseph.',
        4: 'At custos carceris tradidit eos Ioseph, qui et ministrabat eis: aliquantulum temporis fluxerat, et illi in custodia tenebantur.',
        5: 'Videruntque ambo somnium nocte una iuxta interpretationem congruam sibi:',
        6: 'ad quos cum introisset Ioseph mane, et vidisset eos tristes,',
        7: 'sciscitatus est eos, dicens: Cur tristior est hodie solito facies vestra?',
        8: 'Qui responderunt: Somnium vidimus, et non est qui interpretetur nobis. Dixitque ad eos Ioseph: Numquid non Dei est interpretatio? referte mihi quid videritis.',
        9: 'Narravit prior, praepositus pincernarum, somnium suum: Videbam coram me vitem,',
        10: 'in qua erant tres propagines, crescere paulatim in gemmas, et post flores uvas maturescere:',
        11: 'calicemque Pharaonis in manu mea: tuli ergo uvas, et expressi in calicem quem tenebam, et tradidi poculum Pharaoni.',
        12: 'Respondit Ioseph: Haec est interpretatio somnii: Tres propagines, tres adhuc dies sunt:',
        13: 'post quos recordabitur Pharao ministerii tui, et restituet te in gradum pristinum: dabisque ei calicem iuxta officium tuum, sicut ante facere consueveras.',
        14: 'Tantum memento mei, cum bene tibi fuerit, et facias mecum misericordiam: ut suggeras Pharaoni ut educat me de isto carcere:',
        15: 'quia furtim sublatus sum de terra Hebraeorum, et hic innocens in lacum missus sum.',
        16: 'Videns pistorum magister quod prudenter somnium dissolvisset, ait: Et ego vidi somnium, Quod tria canistra farinae haberem super caput meum:',
        17: 'et in uno canistro quod erat excelsius, portare me omnes cibos qui fiunt arte pistoria, avesque comedere ex eo.',
        18: 'Respondit Ioseph: Haec est interpretatio somnii: Tria canistra, tres adhuc dies sunt:',
        19: 'post quos auferet Pharao caput tuum, ac suspendet te in cruce, et lacerabunt volucres carnes tuas.',
        20: 'Exinde dies tertius natalitius Pharaonis erat: qui faciens grande convivium pueris suis, recordatus est inter epulas magistri pincernarum, et pistorum principis.',
        21: 'Restituitque alterum in locum suum, ut porrigeret ei poculum:',
        22: 'alterum suspendit in patibulo, ut coniectoris veritas probaretur.',
        23: 'Et tamen succedentibus prosperis, praepositus pincernarum oblitus est interpretis sui.',
    },
    41: {
        1: 'Post duos annos vidit Pharao somnium. Putabat se stare super fluvium,',
        2: 'de quo ascendebant septem boves, pulchrae et crassae nimis: et pascebantur in locis palustribus.',
        3: 'Aliae quoque septem emergebant de flumine, foedae, confectaeque macie: et pascebantur in ipsa amnis ripa in locis virentibus:',
        4: 'devoraveruntque eas, quarum mira species, et habitudo corporum erat. Expergefactus Pharao,',
        5: 'rursum dormivit, et vidit alterum somnium: Septem spicae pullulabant in culmo uno plenae atque formosae:',
        6: 'aliae quoque totidem spicae tenues, et percussae uredine oriebantur,',
        7: 'devorantes omnium priorum pulchritudinem. Evigilans Pharao post quietem,',
        8: 'et facto mane, pavore perterritus, misit ad omnes coniectores Aegypti, cunctosque sapientes: et accersitis narravit somnium, nec erat qui interpretaretur.',
        9: 'Tunc demum reminiscens pincernarum magister, ait: Confiteor peccatum meum:',
        10: 'Iratus rex servis suis, me et magistrum pistorum retrudi iussit in carcerem principis militum:',
        11: 'ubi una nocte uterque vidimus somnium praesagium futurorum.',
        12: 'Erat ibi puer Hebraeus, eiusdem ducis militum famulus: cui narrantes somnia,',
        13: 'audivimus quidquid postea rei probavit eventus. ego enim redditus sum officio meo: et ille suspensus est in cruce.',
        14: 'Protinus ad regis imperium eductum de carcere Ioseph totonderunt: ac veste mutata, obtulerunt ei.',
        15: 'Cui ille ait: Vidi somnia, nec est qui edisserat: quae audivi te sapientissime coniicere.',
        16: 'Respondit Ioseph: Absque me Deus respondebit prospera Pharaoni.',
        17: 'Narravit ergo Pharao quod viderat: Putabam me stare super ripam fluminis,',
        18: 'et septem boves de amne conscendere, pulchras nimis, et obesis carnibus: quae in pastu paludis virecta carpebant.',
        19: 'et ecce, has sequebantur aliae septem boves in tantum deformes et macilentae, ut numquam tales in terra Aegypti viderim:',
        20: 'quae, devoratis et consumptis prioribus,',
        21: 'nullum saturitatis dedere vestigium: sed simili macie et squalore torpebant. Evigilans, rursus sopore depressus,',
        22: 'vidi somnium: Septem spicae pullulabant in culmo uno plenae atque pulcherrimae.',
        23: 'Aliae quoque septem tenues et percussae uredine, oriebantur e stipula:',
        24: 'quae priorum pulchritudinem devoraverunt. Narravi coniectoribus somnium, et nemo est qui edisserat.',
        25: 'Respondit Ioseph: Somnium regis unum est: quae facturus est Deus, ostendit Pharaoni.',
        26: 'Septem boves pulchrae, et septem spicae plenae: septem hubertatis anni sunt: eandemque vim somnii comprehendunt.',
        27: 'Septem quoque boves tenues atque macilentae, quae ascenderunt post eas, et septem spicae tenues, et vento urente percussae, septem anni venturae sunt famis.',
        28: 'Qui hoc ordine complebuntur:',
        29: 'Ecce septem anni venient fertilitatis magnae in universa terra Aegypti:',
        30: 'quos sequentur septem anni alii tantae sterilitatis, ut oblivioni tradatur cuncta retro abundantia: consumptura est enim fames omnem terram,',
        31: 'et ubertatis magnitudinem perditura est inopiae magnitudo.',
        32: 'Quod autem vidisti secundo ad eandem rem pertinens somnium: firmitatis indicium est, eo quod fiat sermo Dei, et velocius impleatur.',
        33: 'Nunc ergo provideat rex virum sapientem et industrium, et praeficiat eum Terrae Aegypti:',
        34: 'Qui constituat praepositos per cunctas regiones: et quintam partem fructuum per septem annos fertilitatis,',
        35: 'qui iam nunc futuri sunt, congreget in horrea: et omne frumentum sub Pharaonis potestate condatur, serveturque in urbibus.',
        36: 'Et praeparetur futurae septem annorum fami, quae oppressura est Aegyptum, et non consumetur terra inopia.',
        37: 'Placuit Pharaoni consilium et cunctis ministris eius:',
        38: 'locutusque est ad eos: Num invenire poterimus talem virum, qui spiritu Dei plenus sit?',
        39: 'Dixit ergo ad Ioseph: Quia ostendit tibi Deus omnia quae locutus es, numquid sapientiorem et consimilem tui invenire potero?',
        40: 'Tu eris super domum meam, et ad tui oris imperium cunctus populus obediet: uno tantum regni solio te praecedam.',
        41: 'Dixitque rursus Pharao ad Ioseph: Ecce, constitui te super universam terram Aegypti.',
        42: 'Tulitque annulum de manu sua, et dedit eum in manu eius: vestivitque eum stola byssina, et collo torquem auream circumposuit.',
        43: 'Fecitque eum ascendere super currum suum secundum, clamante praecone, ut omnes coram eo genu flecterent, et praepositum esse scirent universae Terrae Aegypti.',
        44: 'Dixit quoque rex Aegypti ad Ioseph: Ego sum Pharao: absque tuo imperio non movebit quisquam manum aut pedem in omni terra Aegypti.',
        45: 'Vertitque nomen eius, et vocavit eum lingua Aegyptiaca, Salvatorem mundi. Deditque illi uxorem Aseneth filiam Phutipharis sacerdotis Heliopoleos. Egressus est itaque Ioseph ad terram Aegypti',
        46: '(Triginta autem annorum erat quando stetit in conspectu regis Pharaonis) et circuivit omnes regiones Aegypti.',
        47: 'Venitque fertilitas septem annorum: et in manipulos redactae segetes congregatae sunt in horrea Aegypti.',
        48: 'Omnis etiam frugum abundantia in singulis urbibus condita est.',
        49: 'Tantaque fuit abundantia tritici, ut arenae maris coaequaretur, et copia mensuram excederet.',
        50: 'Natique sunt Ioseph filii duo antequam veniret fames: quos peperit ei Aseneth filia Phutipharis sacerdotis Heliopoleos.',
        51: 'Vocavitque nomen primogeniti, Manasses, dicens: Oblivisci me fecit Deus omnium laborum meorum, et domus patris mei.',
        52: 'Nomen quoque secundi appellavit Ephraim, dicens: Crescere me fecit Deus in terra paupertatis meae.',
        53: 'Igitur transactis septem hubertatis annis, qui fuerant in Aegypto:',
        54: 'coeperunt venire septem anni inopiae: quos praedixerat Ioseph: et in universo orbe fames praevaluit, in cuncta autem terra Aegypti panis erat.',
        55: 'Qua esuriente, clamavit populus ad Pharaonem, alimenta petens. Quibus ille respondit: Ite ad Ioseph: et quidquid ipse vobis dixerit, facite.',
        56: 'Crescebat autem quotidie fames in omni terra: aperuitque Ioseph universa horrea, et vendebat Aegyptiis: nam et illos oppresserat fames.',
        57: 'Omnesque provinciae veniebant in Aegyptum, ut emerent escas, et malum inopiae temperarent.',
    },
    42: {
        1: 'Audiens autem Iacob quod alimenta venderentur in Aegypto, dixit filiis suis: Quare negligitis?',
        2: 'audivi quod triticum venundetur in Aegypto: descendite, et emite nobis necessaria, ut possimus vivere, et non consumamur inopia.',
        3: 'Descendentes igitur fratres Ioseph decem, ut emerent frumenta in Aegypto,',
        4: 'Beniamin domi retento a Iacob, qui dixerat fratribus eius: Ne forte in itinere quidquam patiatur mali:',
        5: 'ingressi sunt terram Aegypti cum aliis qui pergebant ad emendum. Erat autem fames in terra Chanaan.',
        6: 'Et Ioseph erat princeps in terra Aegypti, atque ad eius nutum frumenta populis vendebantur. Cumque adorassent eum fratres sui,',
        7: 'et agnovisset eos, quasi ad alienos durius loquebatur, interrogans eos: Unde venistis? Qui responderunt: De terra Chanaan, ut emamus victui necessaria.',
        8: 'Et tamen fratres ipse cognoscens, non est cognitus ab eis.',
        9: 'Recordatusque somniorum, quae aliquando viderat, ait ad eos: Exploratores estis: ut videatis infirmiora terrae venistis.',
        10: 'Qui dixerunt: Non est ita, domine, sed servi tui venerunt ut emerent cibos.',
        11: 'Omnes filii unius viri sumus: pacifici venimus, nec quidquam famuli tui machinantur mali.',
        12: 'Quibus ille respondit: Aliter est: immunita terrae huius considerare venistis.',
        13: 'At illi: Duodecim, inquiunt, servi tui, fratres sumus, filii viri unius in terra Chanaan: minimus cum patre nostro est, alius non est super.',
        14: 'Hoc est, ait, quod locutus sum: Exploratores estis.',
        15: 'Iam nunc experimentum vestri capiam: per salutem Pharaonis non egrediemini hinc, donec veniat frater vester minimus.',
        16: 'Mittite ex vobis unum, et adducat eum: vos autem eritis in vinculis, donec probentur quae dixistis utrum vera an falsa sint: alioquin per salutem Pharaonis exploratores estis.',
        17: 'Tradidit ergo illos custodiae tribus diebus.',
        18: 'Die autem tertio eductis de carcere, ait: Facite quae dixi, et vivetis: Deum enim timeo.',
        19: 'Si pacifici estis, frater vester unus ligetur in carcere: vos autem abite, et ferte frumenta quae emistis, in domos vestras,',
        20: 'et fratrem vestrum minimum ad me adducite, ut possim vestros probare sermones, et non moriamini. Fecerunt ut dixerat,',
        21: 'et locuti sunt ad invicem: Merito haec patimur, quia peccavimus in fratrem nostrum, videntes angustiam animae illius, dum deprecaretur nos, et non audivimus: idcirco venit super nos ista tribulatio.',
        22: 'E quibus unus Ruben, ait: Numquid non dixi vobis: Nolite peccare in puerum: et non audistis me? en sanguis eius exquiritur.',
        23: 'Nesciebant autem quod intelligeret Ioseph: eo quod per interpretem loqueretur ad eos.',
        24: 'Avertitque se parumper, et flevit: et reversus locutus est ad eos.',
        25: 'Tollensque Simeon, et ligans illis praesentibus, iussit ministris ut implerent eorum saccos tritico, et reponerent pecunias singulorum in sacculis suis, datis supra cibariis in viam: qui fecerunt ita.',
        26: 'At illi portantes frumenta in asinis suis, profecti sunt.',
        27: 'Apertoque unus sacco, ut daret iumento pabulum in diversorio, contemplatus pecuniam in ore sacculi,',
        28: 'dixit fratribus suis: Reddita est mihi pecunia, en habetur in sacco. Et obstupefacti, turbatique mutuo dixerunt: Quidnam est hoc quod fecit nobis Deus?',
        29: 'Veneruntque ad Iacob patrem suum in terram Chanaan, et narraverunt ei omnia quae accidissent sibi, dicentes:',
        30: 'Locutus est nobis dominus terrae dure, et putavit nos exploratores esse provinciae.',
        31: 'Cui respondimus: Pacifici sumus, nec ullas molimur insidias.',
        32: 'Duodecim fratres uno patre geniti sumus: unus non est super, minimus cum patre nostro est in terra Chanaan.',
        33: 'Qui ait nobis: Sic probabo quod pacifici sitis: Fratrem vestrum unum dimittite apud me, et cibaria domibus vestris necessaria sumite, et abite,',
        34: 'fratremque vestrum minimum adducite ad me, ut sciam quod non sitis exploratores: et istum, qui tenetur in vinculis, recipere possitis: ac deinceps quae vultis, emendi habeatis licentiam.',
        35: 'His dictis, cum frumenta effunderent, singuli repererunt in ore saccorum ligatas pecunias, exterritisque simul omnibus,',
        36: 'dixit pater Iacob: Absque liberis me esse fecistis, Ioseph non est super, Simeon tenetur in vinculis, et Beniamin auferetis: in me haec omnia mala reciderunt.',
        37: 'Cui respondit Ruben: Duos filios meos interfice, si non reduxero illum tibi: trade illum in manu mea, et ego eum tibi restituam.',
        38: 'At ille: Non descendet, inquit, filius meus vobiscum: frater eius mortuus est, et ipse solus remansit: si quid ei adversi acciderit in terra ad quam pergitis, deducetis canos meos cum dolore ad inferos.',
    },
    43: {
        1: 'Interim fames omnem terram vehementer premebat.',
        2: 'Consumptisque cibis quos ex Aegypto detulerant, dixit Iacob ad filios suos: Revertimini, et emite nobis pauxillum escarum.',
        3: 'Respondit Iudas: Denunciavit nobis vir ille sub attestatione iurisiurandi, dicens: Non videbitis faciem meam, nisi fratrem vestrum minimum adduxeritis vobiscum.',
        4: 'Si ergo vis eum mittere nobiscum, pergemus pariter, et ememus tibi necessaria:',
        5: 'sin autem non vis, non ibimus: vir enim, ut saepe diximus, denunciavit nobis, dicens: Non videbitis faciem meam absque fratre vestro minimo.',
        6: 'Dixit eis Israel: In meam hoc fecistis miseriam, ut indicaretis ei et alium habere vos fratrem.',
        7: 'At illi responderunt: Interrogavit nos homo per ordinem nostram progeniem: si pater viveret: si haberemus fratrem: et nos respondimus ei consequenter iuxta id quod fuerat sciscitatus: numquid scire poteramus quod dicturus esset: Adducite fratrem vestrum vobiscum?',
        8: 'Iudas quoque dixit patri suo: Mitte puerum mecum, ut proficiscamur, et possimus vivere: ne moriamur nos et parvuli nostri.',
        9: 'Ego suscipio puerum: de manu mea require illum. nisi reduxero, et reddidero eum tibi, ero peccati reus in te omni tempore.',
        10: 'Si non intercessisset dilatio, iam vice alter venissemus.',
        11: 'Igitur Israel pater eorum dixit ad eos: Si sic necesse est, facite quod vultis: sumite de optimis terrae frugibus in vasis vestris, et deferte viro munera, modicum resinae, et mellis, et storacis, stactes, et terebinthi, et amygdalarum.',
        12: 'Pecuniam quoque duplicem ferte vobiscum: et illam, quam invenistis in sacculis, reportate, ne forte errore factum sit:',
        13: 'sed et fratrem vestrum tollite, et ite ad virum.',
        14: 'Deus autem meus omnipotens faciat vobis eum placabilem: et remittat vobiscum fratrem vestrum quem tenet in vinculis, et hunc Beniamin: ego autem quasi orbatus absque liberis ero.',
        15: 'Tulerunt ergo viri munera, et pecuniam duplicem, et Beniamin: descenderuntque in Aegyptum, et steterunt coram Ioseph.',
        16: 'Quos cum ille vidisset, et Beniamin simul, praecepit dispensatori domus suae, dicens: Introduc viros domum, et occide victimas, et instrue convivium: quoniam mecum sunt comesturi meridie.',
        17: 'Fecit ille sicut fuerat imperatum, et introduxit viros domum.',
        18: 'Ibique exterriti, dixerunt mutuo: Propter pecuniam, quam retulimus prius in saccis nostris, introducti sumus: ut devolvat in nos calumniam, et violenter subiiciat servituti et nos, et asinos nostros.',
        19: 'Quamobrem in ipsis foribus accedentes ad dispensatorem domus',
        20: 'locuti sunt: Oramus domine ut audias nos. Iam ante descendimus ut emeremus escas:',
        21: 'quibus emptis, cum venissemus ad diversorium, aperuimus saccos nostros, et invenimus pecuniam in ore saccorum: quam nunc eodem pondere reportavimus.',
        22: 'Sed et aliud attulimus argentum, ut emamus quae nobis necessaria sunt: non est in nostra conscientia quis posuerit eam in marsupiis nostris.',
        23: 'At ille respondit: Pax vobiscum, nolite timere: Deus vester, et Deus patris vestri dedit vobis thesauros in saccis vestris. nam pecuniam, quam dedistis mihi, probatam ego habeo. Eduxitque ad eos Simeon.',
        24: 'Et introductis domum, attulit aquam, et laverunt pedes suos, deditque pabulum asinis eorum.',
        25: 'Illi vero parabant munera, donec ingrederetur Ioseph meridie: audierant enim quod ibi comesturi essent panem.',
        26: 'Igitur ingressus est Ioseph domum suam, obtuleruntque ei munera, tenentes in manibus suis: et adoraverunt proni in terram.',
        27: 'At ille, clementer resalutatis eis, interrogavit eos, dicens: Sanusne est pater vester senex, de quo dixeratis mihi? Adhuc vivit?',
        28: 'Qui responderunt: Sospes est servus tuus pater noster, adhuc vivit. Et incurvati, adoraverunt eum.',
        29: 'Attollens autem Ioseph oculos, vidit Beniamin fratrem suum uterinum, et ait: Iste est frater vester parvulus, de quo dixeratis mihi? Et rursum: Deus, inquit, misereatur tui, fili mi.',
        30: 'Festinavitque quia commota fuerant viscera eius super fratre suo, et erumpebant lacrymae: et introiens cubiculum flevit.',
        31: 'Rursumque lota facie egressus, continuit se, et ait: Ponite panes.',
        32: 'Quibus appositis, seorsum Ioseph, et seorsum fratribus, Aegyptiis quoque qui vescebantur simul, seorsum (illicitum est enim Aegyptiis comedere cum Hebraeis, et profanum putant huiuscemodi convivium)',
        33: 'sederunt coram eo, primogenitus iuxta primogenita sua, et minimus iuxta aetatem suam. Et mirabantur nimis,',
        34: 'sumptis partibus quas ab eo acceperant: maiorque pars venit Beniamin, ita ut quinque partibus excederet. Biberuntque et inebriati sunt cum eo.',
    },
    44: {
        1: 'Praecepit autem Ioseph dispensatori domus suae, dicens: Imple saccos eorum frumento, quantum possunt capere: et pone pecuniam singulorum in summitate sacci.',
        2: 'Scyphum autem meum argenteum, et pretium quod dedit tritici, pone in ore sacci iunioris. factumque est ita.',
        3: 'Et orto mane, dimissi sunt cum asinis suis.',
        4: 'Iamque urbem exierant, et processerant paululum: tunc Ioseph accersito dispensatore domus, Surge, inquit, et persequere viros: et apprehensis dicito: Quare reddidistis malum pro bono?',
        5: 'Scyphus, quem furati estis, ipse est in quo bibit dominus meus, et in quo augurari solet: pessimam rem fecistis.',
        6: 'Fecit ille ut iusserat. Et apprehensis per ordinem locutus est.',
        7: 'Qui responderunt: Quare sic loquitur dominus noster, ut servi tui tantum flagitii commiserint?',
        8: 'Pecuniam, quam invenimus in summitate saccorum, reportavimus ad te de terra Chanaan: et quo modo consequens est ut furati simus de domo domini tui aurum vel argentum?',
        9: 'Apud quemcumque fuerit inventum servorum tuorum quod quaeris, moriatur, et nos erimus servi domini nostri.',
        10: 'Qui dixit eis: Fiat iuxta vestram sententiam: apud quemcumque fuerit inventus, ipse sit servus meus, vos autem eritis innoxii.',
        11: 'Itaque festinato deponentes in terram saccos, aperuerunt singuli.',
        12: 'Quos scrutatus, incipiens a maiore usque ad minimum, invenit scyphum in sacco Beniamin.',
        13: 'At illi, scissis vestibus, oneratisque rursum asinis, reversi sunt in oppidum.',
        14: 'Primusque Iudas cum fratribus ingressus est ad Ioseph (necdum enim de loco abierat) omnesque ante eum pariter in terram corruerunt.',
        15: 'Quibus ille ait: Cur sic agere voluistis? an ignoratis quod non sit similis mei in augurandi scientia?',
        16: 'Cui Iudas: Quid respondebimus, inquit, domino meo? vel quid loquemur aut iuste poterimus obtendere? Deus invenit iniquitatem servorum tuorum: en omnes servi sumus domini mei, et nos, et apud quem inventus est scyphus.',
        17: 'Responditque Ioseph: Absit a me ut sic agam: qui furatus est scyphum, ipse sit servus meus: vos autem abite liberi ad patrem vestrum.',
        18: 'Accedens autem propius Iudas, confidenter ait: Oro domini mi, loquatur servus tuus verbum in auribus tuis, et ne irascaris famulo tuo: tu es enim post Pharaonem',
        19: 'dominus meus. Interrogasti prius servos tuos: Habetis patrem, aut fratrem?',
        20: 'et nos respondimus tibi domino meo: Est nobis pater senex, et puer parvulus, qui in senectute illius natus est; cuius uterinus frater mortuus est: et ipsum solum habet mater sua, pater vero tenere diliget eum.',
        21: 'Dixistique servis tuis: Adducite eum ad me, et ponam oculos meos super illum.',
        22: 'Suggessimus domino meo: Non potest puer relinquere patrem suum: si enim illum dimiserit, morietur.',
        23: 'Et dixisti servis tuis: Nisi venerit frater vester minimus vobiscum, non videbitis amplius faciem meam.',
        24: 'Cum ergo ascendissemus ad famulum tuum patrem nostrum, narravimus ei omnia quae locutus est dominus meus.',
        25: 'Et dixit pater noster: Revertimini, et emite nobis parum tritici.',
        26: 'Cui diximus: Ire non possumus: si frater noster minimus descenderit nobiscum, proficiscemur simul: alioquin illo absente, non audemus videre faciem viri.',
        27: 'Ad quae ille respondit: Vos scitis quod duos genuerit mihi uxor mea.',
        28: 'Egressus est unus, et dixistis: Bestia devoravit eum: et hucusque non comparet.',
        29: 'Si tuleritis et istum, et aliquid ei in via contigerit, deducetis canos meos cum moerore ad inferos.',
        30: 'Igitur si intravero ad servum tuum patrem nostrum, et puer defuerit, (cum anima illius ex huius anima dependeat)',
        31: 'videritque eum non esse nobiscum, morietur, et deducent famuli tui canos eius cum dolore ad inferos.',
        32: 'Ego proprie servus tuus sim qui in meam hunc recepi fidem, et spopondi dicens: Nisi reduxero eum, peccati reus ero in patrem meum omni tempore.',
        33: 'Manebo itaque servus tuus pro puero in ministerio domini mei, et puer ascendat cum fratribus suis.',
        34: 'Non enim possum redire ad patrem meum, absente puero: ne calamitatis, quae oppressura est patrem meum, testis assistam.',
    },
    45: {
        1: 'Non se poterat ultra cohibere Ioseph multis coram astantibus: unde praecepit ut egrederentur cuncti foras, et nullus interesset alienus agnitioni mutuae.',
        2: 'Elevavitque vocem cum fletu: quam audierunt Aegyptii, omnisque domus Pharaonis.',
        3: 'Et dixit fratribus suis: Ego sum Ioseph: adhuc pater meus vivit? Non poterant respondere fratres nimio terrore perterriti.',
        4: 'Ad quos ille clementer: Accedite, inquit, ad me. Et cum accessissent prope, Ego sum, ait, Ioseph, frater vester, quem vendidistis in Aegyptum.',
        5: 'Nolite pavere, neque vobis durum esse videatur quod vendidistis me in his regionibus: pro salute enim vestra misit me Deus ante vos in Aegyptum.',
        6: 'Biennium est enim quod coepit fames esse in terra: et adhuc quinque anni restant, quibus nec arari poterit nec meti.',
        7: 'Praemisitque me Deus ut reservemini super terram, et escas ad vivendum habere possitis.',
        8: 'Non vestro consilio, sed Dei voluntate huc missum sum: qui fecit me quasi patrem Pharaonis, et dominum universae domus eius, ac principem in omni terra Aegypti.',
        9: 'Festinate, et ascendite ad patrem meum, et dicetis ei: Haec mandat filius tuus Ioseph: Deus fecit me dominum universae terrae Aegypti: descende ad me, ne moreris,',
        10: 'et habitabis in terra Gessen: erisque iuxta me tu, et filii tui, et filii filiorum tuorum, oves tuae, et armenta tua, et universa quae possides.',
        11: 'Ibique te pascam (adhuc enim quinque anni residui sunt famis) ne et tu pereas, et domus tua, et omnia quae possides.',
        12: 'En oculi vestri, et oculi fratris mei Beniamin vident quod os meum loquatur ad vos.',
        13: 'Nunciate patri meo universam gloriam meam, et cuncta quae vidistis in Aegypto: festinate, et adducite eum ad me.',
        14: 'Cumque amplexatus recidisset in collum Beniamin fratris sui, flevit: illo quoque similiter flente super collum eius.',
        15: 'Osculatusque est Ioseph omnes fratres suos, et ploravit super singulos: post quae ausi sunt loqui ad eum.',
        16: 'Auditumque est, et celebri sermone vulgatum in aula regis: Venerunt fratres Ioseph: et gavisus est Pharao, atque omnis familia eius.',
        17: 'Dixitque ad Ioseph ut imperaret fratribus suis, dicens: Onerantes iumenta, ite in terram Chanaan,',
        18: 'et tollite inde patrem vestrum et cognationem, et venite ad me: et ego dabo vobis omnia bona Aegypti, ut comedatis medullam terrae.',
        19: 'Praecipe etiam ut tollant plaustra de terra Aegypti, ad subvectionem parvulorum suorum ac coniugum: et dicito: Tollite patrem vestrum, et properate quantocyus venientes.',
        20: 'Nec demittatis quidquam de supellectili vestra: quia omnes opes Aegypti, vestrae erunt.',
        21: 'Feceruntque filii Israel ut eis mandatum fuerat. Quibus dedit Ioseph plaustra, secundum Pharaonis imperium: et cibaria in itinere.',
        22: 'Singulis quoque proferri iussit binas stolas: Beniamin vero dedit trecentos argenteos cum quinque stolis optimis:',
        23: 'tantumdem pecuniae et vestium mittens patri suo, addens et asinos decem, qui subveherent ex omnibus divitiis Aegypti: et totidem asinas, triticum in itinere, panesque portantes.',
        24: 'Dimisit ergo fratres suos, et proficiscentibus ait: Ne irascamini in via.',
        25: 'Qui ascendentes ex Aegypto, venerunt in terram Chanaan ad patrem suum Iacob.',
        26: 'Et nunciaverunt ei, dicentes: Ioseph filius tuus vivit: et ipse dominatur in omni terra Aegypti. Quo audito Iacob, quasi de gravi somno evigilans, tamen non credebat eis.',
        27: 'Illi econtra referebant omnem ordinem rei. Cumque vidisset plaustra, et universa quae miserat, revixit spiritus eius,',
        28: 'et ait: Sufficit mihi si adhuc Ioseph filius meus vivit: vadam, et videbo illum antequam moriar.',
    },
    46: {
        1: 'Profectusque Israel cum omnibus quae habebat, venit ad Puteum iuramenti. et mactatis ibi victimis Deo patris sui Isaac,',
        2: 'audivit eum per visionem nocte vocantem se, et dicentem sibi: Iacob, Iacob. Cui respondit: Ecce adsum.',
        3: 'Ait illi Deus: Ego sum fortissimus Deus patris tui: noli timere, descende in Aegyptum, quia in gentem magnam faciam te ibi.',
        4: 'Ego descendam tecum illuc, et ego inde adducam te revertentem: Ioseph quoque ponet manus suas super oculos tuos.',
        5: 'Surrexit autem Iacob a Puteo iuramenti: tuleruntque eum filii cum parvulis et uxoribus suis in plaustris quae miserat Pharao ad portandum senem,',
        6: 'et omnia quae possederat in Terra Chanaan: venitque in Aegyptum cum omni semine suo,',
        7: 'filii eius, et nepotes, filiae, et cuncta simul progenies.',
        8: 'Haec sunt autem nomina filiorum Israel, qui ingressi sunt in Aegyptum, ipse cum liberis suis. Primogenitus Ruben.',
        9: 'Filii Ruben: Henoch et Phallu et Hesron et Charmi.',
        10: 'Filii Simeon: Iamuel et Iamin et Ahod, et Iachin et Sohar, et Saul filius Chanaanitidis.',
        11: 'Filii Levi: Gerson et Caath et Merari.',
        12: 'Filii Iuda: Her et Onan et Sela et Phares et Zara. mortui sunt autem Her et Onan in terra Chanaan. Natique sunt filii Phares: Hesron et Hamul.',
        13: 'Filii Issachar: Thola et Phua et Iob et Semron.',
        14: 'Filii Zabulon: Sared et Elon et Iahelel.',
        15: 'Hi filii Lia quos genuit in Mesopotamia Syriae cum Dina filia sua. omnes animae filiorum eius et filiarum, triginta tres.',
        16: 'Filii Gad: Sephion et Haggi et Suni et Esebon et Heri et Arodi et Areli.',
        17: 'Filii Aser: Iamne et Iesua et Iessui et Beria, Sara quoque soror eorum. Filii Beria: Heber et Melchiel.',
        18: 'hi filii Zelphae, quam dedit Laban Liae filiae suae. et hos genuit Iacob sedecim animas.',
        19: 'Filii Rachel uxoris Iacob: Ioseph et Beniamin.',
        20: 'Natique sunt Ioseph filii in Terra Aegypti, quos genuit ei Aseneth filia Phutipharis sacerdotis Heliopoleos: Manasses et Ephraim.',
        21: 'Filii Beniamin: Bela et Bechor et Asbel et Gera et Naaman et Echi et Ros et Mophim et Ophim et Ared.',
        22: 'hi filii Rachel quos genuit Iacob: omnes animae, quattuordecim.',
        23: 'Filii Dan: Husim.',
        24: 'Filii Nephthali: Iasiel et Guni et Ieser et Sallem.',
        25: 'Hi filii Balae, quam dedit Laban Racheli filiae suae: et hos genuit Iacob: omnes animae, septem.',
        26: 'Cunctae animae, quae ingressae sunt cum Iacob in Aegyptum, et egressae sunt de femore illius, absque uxoribus filiorum eius, sexaginta sex.',
        27: 'Filii autem Ioseph, qui nati sunt ei in terra Aegypti, animae duae. Omnes animae domus Iacob, quae ingressae sunt in Aegyptum, fuere septuaginta.',
        28: 'Misit autem Iudam ante se ad Ioseph, ut nunciaret ei, et occurreret in Gessen.',
        29: 'Quo cum pervenisset, iuncto Ioseph curro suo, ascendit obviam patri suo ad eumdem locum: vidensque eum, irruit super collum eius, et inter amplexus flevit.',
        30: 'Dixitque pater ad Ioseph: Iam laetus moriar, quia vidi faciem tuam, et superstitem te relinquo.',
        31: 'At ille locutus est ad fratres suos, et ad omnem domum patris sui: Ascendam, et nunciabo Pharaoni dicamque ei: Fratres mei, et domus patris mei, qui erant in Terra Chanaan, venerunt ad me:',
        32: 'et sunt viri pastores ovium, curamque habent alendorum gregum: pecora sua, et armenta, et omnia quae habere potuerunt, adduxerunt secum.',
        33: 'Cumque vocaverit vos, et dixerit: Quod est opus vestrum?',
        34: 'Respondebitis: Viri pastores sumus servi tui, ab infantia nostra usque in praesens, et nos et patres nostri. Haec autem dicetis, ut habitare possitis in Terra Gessen: quia detestantur Aegyptii omnes pastores ovium.',
    },
    47: {
        1: 'Ingressus ergo Ioseph nunciavit Pharaoni, dicens: Pater meus et fratres, oves eorum et armenta, et cuncta quae possident, venerunt de Terra Chanaan: et ecce consistunt in Terra Gessen.',
        2: 'Extremos quoque fratrum suorum quinque viros constituit coram rege:',
        3: 'quos ille interrogavit: Quid habetis operis? Responderunt: Pastores ovium sumus servi tui, et nos, et patres nostri.',
        4: 'Ad peregrinandum in terram tuam venimus: quoniam non est herba gregibus servorum tuorum, ingravescente fame in terra Chanaan: petimusque ut esse nos iubeas servos tuos in Terra Gessen.',
        5: 'Dixit itaque rex ad Ioseph: Pater tuus et fratres tui venerunt ad te.',
        6: 'Terra Aegypti in conspectu tuo est: in optimo loco fac eos habitare, et trade eis Terram Gessen. Quod si nosti in eis esse viros industrios, constitue illos magistros pecorum meorum.',
        7: 'Post haec introduxit Ioseph patrem suum ad Regem, et statuit eum coram eo: qui benedicens illi,',
        8: 'et interrogatus ab eo: Quot sunt dies annorum vitae tuae?',
        9: 'Respondit: Dies peregrinationis meae centum triginta annorum sunt, parvi et mali, et non pervenerunt usque ad dies patrum meorum quibus peregrinati sunt.',
        10: 'Et benedicto rege, egressus est foras.',
        11: 'Ioseph vero patri et fratribus suis dedit possessionem in Aegypto in optimo terrae loco, Ramesses, ut praeceperat Pharao.',
        12: 'Et alebat eos, omnemque domum patris sui, praebens cibaria singulis.',
        13: 'In toto enim orbe panis deerat, et oppresserat fames terram, maxime Aegypti et Chanaan.',
        14: 'E quibus omnem pecuniam congregavit pro venditione frumenti, et intulit eam in aerarium regis.',
        15: 'Cumque defecisset emptoribus pretium, venit cuncta Aegyptus ad Ioseph, dicens: Da nobis panes: quare morimur coram te, deficiente pecunia?',
        16: 'Quibus ille respondit: Adducite pecora vestra, et dabo vobis pro eis cibos, si pretium non habetis.',
        17: 'Quae cum adduxissent, dedit eis alimenta pro equis, et ovibus, et bobus, et asinis: sustentavitque eos illo anno pro commutatione pecorum.',
        18: 'Venerunt quoque anno secundo, et dixerunt ei: Non celamus domino nostro quod deficiente pecunia, pecora simul defecerunt: nec clam te est, quod absque corporibus et terra nihil habeamus.',
        19: 'Cur ergo moriemur te vidente? et nos et terra nostra tui erimus: eme nos in servitutem regiam, et praebe semina, ne pereunte cultore redigatur terra in solitudinem.',
        20: 'Emit igitur Ioseph omnem Terram Aegypti, vendentibus singulis possessiones suas prae magnitudine famis. Subiecitque eam Pharaoni,',
        21: 'et cunctos populos eius a novissimis terminis Aegypti usque ad extremos fines eius,',
        22: 'praeter terram sacerdotum, quae a rege tradita fuerat eis: quibus et statuta cibaria ex horreis publicis praebebantur, et idcirco non sunt compulsi vendere possessiones suas.',
        23: 'Dixit ergo Ioseph ad populos: En ut cernitis, et vos et terram vestram Pharao possidet: accipite semina, et serite agros,',
        24: 'ut fruges habere possitis. Quintam partem regi dabitis: quattuor reliquas permitto vobis in sementem, et in cibum familiis et liberis vestris.',
        25: 'Qui responderunt: Salus nostra in manu tua est: respiciat nos tantum dominus noster, et laeti serviemus regi.',
        26: 'Ex eo tempore usque in praesentem diem in universa terra Aegypti regibus quinta pars solvitur, et factum est quasi in legem, absque terra sacerdotali, quae libera ab hac conditione fuit.',
        27: 'Habitavit ergo Israel in Aegypto, idest, in Terra Gessen, et possedit eam: auctusque est, et multiplicatus nimis.',
        28: 'Et vixit in ea decem et septem annis: factique sunt omnes dies vitae illius centum quadraginta septem annorum.',
        29: 'Cumque appropinquare cerneret diem mortis suae, vocavit filium suum Ioseph, et dixit ad eum: Si inveni gratiam in conspectu tuo, pone manum tuam sub femore meo: et facies mihi misericordiam et veritatem, ut non sepelias me in Aegypto:',
        30: 'sed dormiam cum patribus meis, et auferas me de terra hac, condasque in sepulchro maiorum meorum. Cui respondit Ioseph: Ego faciam quod iussisti.',
        31: 'Et ille: Iura ergo, inquit, mihi. Quo iurante, adoravit Israel Deum, conversus ad lectuli caput.',
    },
    48: {
        1: 'His itaque transactis, nunciatum est Ioseph quod aegrotaret pater suus: qui, assumptis duobus filiis Manasse et Ephraim, ire perrexit.',
        2: 'Dictumque est seni: Ecce filius tuus Ioseph venit ad te. Qui confortatus sedit in lectulo.',
        3: 'Et ingresso ad se Ioseph ait: Deus omnipotens apparuit mihi in Luza, quae est in Terra Chanaan: benedixitque mihi,',
        4: 'et ait: Ego te augebo et multiplicabo, et faciam te in turbas populorum: daboque tibi terram hanc, et semini tuo post te in possessionem sempiternam.',
        5: 'Duo ergo filii tui, qui nati sunt tibi in Terra Aegypti, antequam huc venirem ad te, mei erunt: Ephraim et Manasses, sicut Ruben et Simeon reputabuntur mihi.',
        6: 'Reliquos autem quos genueris post eos, tui erunt, et nomine fratrum suorum vocabuntur in possessionibus suis.',
        7: 'Mihi enim, quando veniebam de Mesopotamia, mortua est Rachel in terra Chanaan in ipso itinere, eratque vernum tempus: et ingrediebar Ephratam, et sepelivi eam iuxta viam Ephratae, quae alio nomine appellatur Bethlehem.',
        8: 'Videns autem filios eius dixit ad eum: Qui sunt isti?',
        9: 'Respondit: Filii mei sunt, quos donavit mihi Deus in hoc loco. Adduc, inquit, eos ad me, ut benedicam illis.',
        10: 'Oculi enim Israel caligabant prae nimia senectute, et clare videre non poterat. Applicitosque ad se, deosculatus et circumplexus eos,',
        11: 'dixit ad filium suum: Non sum fraudatus aspectu tuo: insuper ostendit mihi Deus semen tuum.',
        12: 'Cumque tulisset eos Ioseph de gremio patris, adoravit pronus in terram.',
        13: 'Et posuit Ephraim ad dexteram suam, id est, ad sinistram Israel: Manassen vero in sinistra sua, ad dexteram scilicet patris, applicuitque ambos ad eum.',
        14: 'Qui extendens manum dexteram, posuit super caput Ephraim minoris fratris: sinistram autem super caput Manasse qui maior natu erat, commutans manus.',
        15: 'Benedixitque Iacob filiis Ioseph, et ait: Deus, in cuius conspectu ambulaverunt patres mei Abraham, et Isaac, Deus qui pascit me ab adolescentia mea usque in praesentem diem:',
        16: 'Angelus, qui eruit me de cunctis malis, benedicat pueris istis: et invocetur super eos nomen meum, nomina quoque patrum meorum Abraham, et Isaac, et crescant in multitudinem super terram.',
        17: 'Videns autem Ioseph quod posuisset pater suus dexteram manum super caput Ephraim, graviter accepit: et apprehensam manum patris levare conatus est de capite Ephraim, et transferre super caput Manasse.',
        18: 'Dixitque ad patrem: Non ita convenit, pater: quia hic est primogenitus, pone dexteram tuam super caput eius.',
        19: 'Qui renuens, ait: Scio fili mi, scio: et iste quidem erit in populos, et multiplicabitur: sed frater eius minor, maior erit illo: et semen illius crescet in gentes.',
        20: 'Benedixitque eis in tempore illo, dicens: In te benedicetur Israel, atque dicetur: Faciat tibi Deus sicut Ephraim, et sicut Manasse. Constituitque Ephraim ante Manassen.',
        21: 'Et ait ad Ioseph filium suum: En ego morior, et erit Deus vobiscum, reducetque vos ad terram patrum vestrorum.',
        22: 'Do tibi partem unam extra fratres tuos, quam tuli de manu Amorrhaei in gladio et arcu meo.',
    },
    49: {
        1: 'Vocavit autem Iacob filios suos, et ait eis: Congregamini, ut annunciem quae ventura sunt vobis in diebus novissimis.',
        2: 'Congregamini, et audite filii Iacob, audite Israel patrem vestrum:',
        3: 'Ruben primogenitus meus, tu fortitudo mea, et principium doloris mei: prior in donis, maior in imperio.',
        4: 'Effusus es sicut aqua, non crescas: quia ascendisti cubile patris tui, et maculasti stratum eius.',
        5: 'Simeon et Levi fratres: vasa iniquitatis bellantia.',
        6: 'In consilium eorum non veniat anima mea, et in coetu illorum non sit gloria mea: quia in furore suo occiderunt virum, et in voluntate sua suffoderunt murum.',
        7: 'Maledictus furor eorum, quia pertinax: et indignatio eorum, quia dura: dividam eos in Iacob, et dispergam eos in Israel.',
        8: 'Iuda, te laudabunt fratres tui: manus tua in cervicibus inimicorum tuorum, adorabunt te filii patris tui.',
        9: 'Catulus leonis Iuda: ad praedam fili mi ascendisti: requiescens accubuisti ut leo, et quasi leaena, quis suscitabit eum?',
        10: 'NON AUFERETUR sceptrum de Iuda, et dux de femore eius, donec veniat qui mittendus est, et ipse erit expectatio gentium.',
        11: 'Ligans ad vineam pullum suum, et ad vitem, o fili mi, asinam suam. Lavabit in vino stolam suam, et in sanguine uvae pallium suum.',
        12: 'Pulchriores sunt oculi eius vino, et dentes eius lacte candidiores.',
        13: 'Zabulon in littore maris habitabit, et in statione navium pertingens usque ad Sidonem.',
        14: 'Issachar asinus fortis accubans inter terminos.',
        15: 'Vidit requiem quod esset bona: et terram quod optima: et supposuit humerum suum ad portandum, factusque est tributis serviens.',
        16: 'Dan iudicabit populum suum sicut et alia tribus in Israel.',
        17: 'Fiat Dan coluber in via, cerastes in semita, mordens ungulas equi, ut cadat ascensor eius retro.',
        18: 'SALUTARE tuum expectabo Domine.',
        19: 'Gad, accinctus praeliabatur ante eum: et ipse accingetur retrorsum.',
        20: 'Aser, pinguis panis eius, et praebebit delicias regibus.',
        21: 'Nephthali, cervus emissus, et dans eloquia pulchritudinis.',
        22: 'Filius accrescens Ioseph, filius accrescens et decorus aspectu: filiae discurrerunt super murum.',
        23: 'Sed exasperaverunt eum, et iurgati sunt, invideruntque illi habentes iacula.',
        24: 'Sedit in forti arcus eius, et dissoluta sunt vincula brachiorum et manuum illius per manus potentis Iacob: inde pastor egressus est lapis Israel.',
        25: 'Deus patris tui erit adiutor tuus, et omnipotens benedicet tibi benedictionibus caeli desuper, benedictionibus abyssi iacentis deorsum, benedictionibus huberum et vulvae.',
        26: 'Benedictiones patris tui confortatae sunt benedictionibus patrum eius: donec veniret desiderium collium aeternorum: fiant in capite Ioseph, et in vertice Nazaraei inter fratres suos.',
        27: 'Beniamin lupus rapax, mane comedat praedam, et vespere dividet spolia.',
        28: 'Omnes hi in tribubus Israel duodecim: haec locutus est eis pater suus, benedixitque singulis benedictionibus propriis.',
        29: 'Et praecepit eis, dicens: Ego congregor ad populum meum: sepelite me cum patribus meis in spelunca duplici quae est in agro Ephron Hethaei,',
        30: 'contra Mambre in Terra Chanaan, quam emit Abraham cum agro ab Ephron Hethaeo in possessionem sepulchri.',
        31: 'Ibi sepelierunt eum, et Saram uxorem eius: ibi sepultus est Isaac cum Rebecca coniuge sua: ibi et Lia condita iacet.',
        32: 'Finitisque mandatis quibus filios instruebat, collegit pedes suos super lectulum, et obiit: appositusque est ad populum suum.',
    },
    50: {
        1: 'Quod cernens Ioseph, ruit super faciem patris flens et deosculans eum.',
        2: 'Praecepitque servis suis medicis ut aromatibus condirent patrem.',
        3: 'Quibus iussa explentibus, transierunt quadraginta dies: iste quippe mos erat cadaverum conditorum. flevitque eum Aegyptus septuaginta diebus.',
        4: 'Et expleto planctus tempore, locutus est Ioseph ad familiam Pharaonis: Si inveni gratiam in conspectu vestro, loquimini in auribus Pharaonis:',
        5: 'eo quod pater meus adiuraverit me, dicens: En morior, in sepulchro meo quod fodi mihi in terra Chanaan, sepelies me. Ascendam igitur, et sepeliam patrem meum, ac revertar.',
        6: 'Dixitque ei Pharao: Ascende et sepeli patrem tuum sicut adiuratus es.',
        7: 'Quo ascendente, ierunt cum eo omnes senes domus Pharaonis, cunctique maiores natu Terrae Aegypti:',
        8: 'domus Ioseph cum fratribus suis, absque parvulis et gregibus, atque armentis quae dereliquerunt in Terra Gessen.',
        9: 'Habuit quoque in comitatu currus et equites: et facta est turba non modica.',
        10: 'Veneruntque ad Aream Arad, quae sita est trans Iordanem: ubi celebrantes exequias planctu magno atque vehementi, impleverunt septem dies.',
        11: 'Quod cum vidissent habitatores Terrae Chanaan, dixerunt: Planctus magnus est iste Aegyptiis. Et idcirco vocatum est nomen loci illius, Planctus Aegypti.',
        12: 'Fecerunt ergo filii Iacob sicut praeceperat eis:',
        13: 'Et portantes eum in Terram Chanaan, sepelierunt eum in spelunca duplici, quam emerat Abraham cum agro in possessionem sepulchri ab Ephron Hethaeo contra faciem Mambre.',
        14: 'Reversusque est Ioseph in Aegyptum cum fratribus suis, et omni comitatu, sepulto patre.',
        15: 'Quo mortuo, timentes fratres eius, et mutuo colloquentes: Ne forte memor sit iniuriae quam passus est, et reddat nobis omne malum quod fecimus,',
        16: 'mandaverunt ei dicentes: Pater tuus praecepit nobis antequam moreretur,',
        17: 'ut haec tibi verbis illius diceremus: Obsecro ut obliviscaris sceleris fratrum tuorum, et peccati atque malitiae quam exercuerunt in te: nos quoque oramus ut servo Dei patri tuo dimittas iniquitatem hanc. Quibus auditis flevit Ioseph.',
        18: 'Veneruntque ad eum fratres sui: et proni adorantes in terram dixerunt: Servi tui sumus.',
        19: 'Quibus ille respondit: Nolite timere: num Dei possumus resistere voluntati?',
        20: 'Vos cogitastis de me malum: sed Deus vertit illud in bonum, ut exaltaret me, sicut in praesentiarum cernitis, et salvos faceret multos populos.',
        21: 'Nolite timere: ego pascam vos et parvulos vestros. consolatusque est eos, et blande ac leniter est locutus.',
        22: 'Et habitavit in Aegypto cum omni domo patris sui: vixitque centum decem annis. Et vidit Ephraim filios usque ad tertiam generationem. Filii quoque Machir filii Manasse nati sunt in genibus Ioseph.',
        23: 'Quibus transactis, locutus est fratribus suis: Post mortem meam Deus visitabit vos, et ascendere vos faciet de terra ista ad terram quam iuravit Abraham, Isaac, et Iacob.',
        24: 'Cumque adiurasset eos atque dixisset: Deus visitabit vos: asportate ossa mea vobiscum de loco isto:',
        25: 'mortuus est, expletis centum decem vitae suae annis. Et conditus aromatibus, repositus est in loculo in Aegypto.',
    },
}
